    D.listeningExercises.push(...[{"id":"ets-orig-test-2-q1","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 1","partNumber":1,"level":"ETS Format","title":"Test 02 • Câu 1 (Part 1: Mô tả hình ảnh (Photographs))","questionPrompt":"Look at the picture and choose the statement that best describes it.","imageType":"office_laptop","imageCaption":"Một nữ nhân viên đang ngồi tại bàn, làm việc trên chiếc máy tính xách tay đang mở; bên trái có một tờ giấy.","imageUrl":"listening/images/lv1-test-02/part1/q1.jpg","audioUrl":"listening/audio/lv1-test-02/p1-q001.mp3","audioText":"A. A woman is working on an open laptop beside a sheet of paper. B. A technician is repairing a printer in the office. C. The woman is putting her laptop into a carrying case. D. The desk has been cleared of all documents.","fullTranscript":"A woman is working on an open laptop beside a sheet of paper.","vietnamese":"A. Một người phụ nữ đang làm việc trên chiếc máy tính xách tay đang mở, bên cạnh là một tờ giấy.\nB. Một kỹ thuật viên đang sửa máy in trong văn phòng.\nC. Người phụ nữ đang cất máy tính xách tay vào túi đựng.\nD. Chiếc bàn đã được dọn sạch mọi tài liệu.","optionTranslations":"A. Một người phụ nữ đang làm việc trên chiếc máy tính xách tay đang mở, bên cạnh là một tờ giấy.\nB. Một kỹ thuật viên đang sửa máy in trong văn phòng.\nC. Người phụ nữ đang cất máy tính xách tay vào túi đựng.\nD. Chiếc bàn đã được dọn sạch mọi tài liệu.","explanation":"Hình minh họa có một người phụ nữ ngồi sau bàn, trước mặt là chiếc máy tính đang mở; phía bên trái là một tờ giấy. A mô tả đúng người, hành động và các vật thể này. B sai vì trong hình không có máy in hay kỹ thuật viên. C sai vì máy tính vẫn đang mở trên bàn, không có túi đựng và không có động tác cất máy. D sai vì tờ giấy vẫn nằm trên bàn, nên mặt bàn không hề trống.","hintWords":["woman","working","open","laptop","beside"],"keyVocab":[{"word":"laptop","meaning":"máy tính xách tay"},{"word":"keyboard","meaning":"bàn phím"},{"word":"sheet","meaning":"tờ (giấy)"},{"word":"technician","meaning":"kỹ thuật viên"},{"word":"clear","meaning":"dọn sạch, làm trống"}],"practiceOptions":[{"key":"A","text":"A woman is working on an open laptop beside a sheet of paper.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p1-q001-a.mp3","keyVocab":[{"word":"laptop","meaning":"máy tính xách tay"},{"word":"sheet","meaning":"tờ (giấy)"},{"word":"open","meaning":"mở, khai trương"}]},{"key":"B","text":"A technician is repairing a printer in the office.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q001-b.mp3","keyVocab":[{"word":"technician","meaning":"kỹ thuật viên"},{"word":"print","meaning":"in"},{"word":"repair","meaning":"sự sửa chữa"}]},{"key":"C","text":"The woman is putting her laptop into a carrying case.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q001-c.mp3","keyVocab":[{"word":"laptop","meaning":"máy tính xách tay"}]},{"key":"D","text":"The desk has been cleared of all documents.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q001-d.mp3","keyVocab":[{"word":"clear","meaning":"dọn sạch, làm trống"},{"word":"desk","meaning":"bàn làm việc"},{"word":"document","meaning":"tài liệu"}]}]},{"id":"ets-orig-test-2-q2","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 1","partNumber":1,"level":"ETS Format","title":"Test 02 • Câu 2 (Part 1: Mô tả hình ảnh (Photographs))","questionPrompt":"Look at the picture and choose the statement that best describes it.","imageType":"calendar_meeting","imageCaption":"Hai đồng nghiệp đứng sau một chiếc bàn dài, phía trên là tấm lịch treo tường.","imageUrl":"listening/images/lv1-test-02/part1/q2.jpg","audioUrl":"listening/audio/lv1-test-02/p1-q002.mp3","audioText":"A. A wall calendar is being taken down. B. Two colleagues are standing at a table below a wall calendar. C. A group of trainees is watching a presentation. D. One employee is writing on a whiteboard.","fullTranscript":"Two colleagues are standing at a table below a wall calendar.","vietnamese":"A. Một tấm lịch treo tường đang được gỡ xuống.\nB. Hai đồng nghiệp đang đứng tại một chiếc bàn, bên dưới tấm lịch treo tường.\nC. Một nhóm học viên đang xem phần trình bày.\nD. Một nhân viên đang viết lên bảng trắng.","optionTranslations":"A. Một tấm lịch treo tường đang được gỡ xuống.\nB. Hai đồng nghiệp đang đứng tại một chiếc bàn, bên dưới tấm lịch treo tường.\nC. Một nhóm học viên đang xem phần trình bày.\nD. Một nhân viên đang viết lên bảng trắng.","explanation":"Hình có tấm lịch lớn gắn trên tường, ngay phía trên chiếc bàn dài; hai người đứng sát bàn. B mô tả đúng số người, tư thế và vị trí của tấm lịch. A sai vì lịch vẫn cố định trên tường, không có ai chạm vào. C sai vì chỉ có hai người, không có màn hình hay buổi thuyết trình. D sai vì không có bảng trắng và không ai đang viết.","hintWords":["colleagues","standing","table","below","wall"],"keyVocab":[{"word":"calendar","meaning":"lịch"},{"word":"colleague","meaning":"đồng nghiệp"},{"word":"wall","meaning":"bức tường"},{"word":"presentation","meaning":"bài trình bày, buổi thuyết trình"},{"word":"remove","meaning":"gỡ xuống, di chuyển ra khỏi vị trí"}],"practiceOptions":[{"key":"A","text":"A wall calendar is being taken down.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q002-a.mp3","keyVocab":[{"word":"calendar","meaning":"lịch"},{"word":"wall","meaning":"bức tường"},{"word":"be down","meaning":"bị ngắt, không hoạt động"}]},{"key":"B","text":"Two colleagues are standing at a table below a wall calendar.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p1-q002-b.mp3","keyVocab":[{"word":"calendar","meaning":"lịch"},{"word":"colleague","meaning":"đồng nghiệp"},{"word":"wall","meaning":"bức tường"}]},{"key":"C","text":"A group of trainees is watching a presentation.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q002-c.mp3","keyVocab":[{"word":"presentation","meaning":"bài trình bày, buổi thuyết trình"}]},{"key":"D","text":"One employee is writing on a whiteboard.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q002-d.mp3","keyVocab":[{"word":"employee","meaning":"nhân viên"},{"word":"whiteboard","meaning":"bảng trắng"}]}]},{"id":"ets-orig-test-2-q3","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 1","partNumber":1,"level":"ETS Format","title":"Test 02 • Câu 3 (Part 1: Mô tả hình ảnh (Photographs))","questionPrompt":"Look at the picture and choose the statement that best describes it.","imageType":"shipping_contract","imageCaption":"Một chứng từ vận chuyển và một chiếc bút nằm trên bàn, ngay cạnh một thùng các-tông.","imageUrl":"listening/images/lv1-test-02/part1/q3.jpg","audioUrl":"listening/audio/lv1-test-02/p1-q003.mp3","audioText":"A. A pen has been placed inside an open box. B. A delivery truck is being loaded at a warehouse. C. A pen rests on some paperwork next to a carton. D. The package has been sealed with tape.","fullTranscript":"A pen rests on some paperwork next to a carton.","vietnamese":"A. Một chiếc bút đã được đặt vào bên trong một chiếc hộp đang mở.\nB. Một chiếc xe tải giao hàng đang được chất hàng tại nhà kho.\nC. Một chiếc bút nằm trên một số giấy tờ, ngay cạnh một thùng các-tông.\nD. Kiện hàng đã được dán kín bằng băng dính.","optionTranslations":"A. Một chiếc bút đã được đặt vào bên trong một chiếc hộp đang mở.\nB. Một chiếc xe tải giao hàng đang được chất hàng tại nhà kho.\nC. Một chiếc bút nằm trên một số giấy tờ, ngay cạnh một thùng các-tông.\nD. Kiện hàng đã được dán kín bằng băng dính.","explanation":"Ở bên trái là một số giấy tờ có các dòng chữ, chiếc bút đặt chéo ngay trên đó; bên phải là thùng các-tông. C khớp với cả ba vật thể và quan hệ vị trí giữa chúng. A sai vì bút nằm ngoài thùng, không ở bên trong. B sai vì hình không có xe tải, nhà kho hay người bốc xếp. D sai vì không thấy băng dính hay thao tác dán kín.","hintWords":["rests","some","paperwork","next","carton"],"keyVocab":[{"word":"paperwork","meaning":"giấy tờ, hồ sơ"},{"word":"carton","meaning":"thùng các-tông"},{"word":"seal","meaning":"dán kín, niêm phong"},{"word":"warehouse","meaning":"nhà kho"},{"word":"package","meaning":"kiện hàng, bưu kiện"}],"practiceOptions":[{"key":"A","text":"A pen has been placed inside an open box.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q003-a.mp3","keyVocab":[{"word":"open","meaning":"mở, khai trương"},{"word":"box","meaning":"hộp, thùng"}]},{"key":"B","text":"A delivery truck is being loaded at a warehouse.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q003-b.mp3","keyVocab":[{"word":"warehouse","meaning":"nhà kho"},{"word":"delivery truck","meaning":"xe tải giao hàng"},{"word":"load","meaning":"chất hàng, bốc hàng"}]},{"key":"C","text":"A pen rests on some paperwork next to a carton.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p1-q003-c.mp3","keyVocab":[{"word":"paperwork","meaning":"giấy tờ, hồ sơ"},{"word":"carton","meaning":"thùng các-tông"},{"word":"next to","meaning":"ngay cạnh, bên cạnh"}]},{"key":"D","text":"The package has been sealed with tape.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q003-d.mp3","keyVocab":[{"word":"seal","meaning":"dán kín, niêm phong"},{"word":"package","meaning":"kiện hàng, bưu kiện"},{"word":"tape","meaning":"băng dính"}]}]},{"id":"ets-orig-test-2-q4","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 1","partNumber":1,"level":"ETS Format","title":"Test 02 • Câu 4 (Part 1: Mô tả hình ảnh (Photographs))","questionPrompt":"Look at the picture and choose the statement that best describes it.","imageType":"conference_badges","imageCaption":"Ba người tham dự đang đứng sau một chiếc bàn dài, mỗi người đeo một tấm thẻ tên.","imageUrl":"listening/images/lv1-test-02/part1/q4.jpg","audioUrl":"listening/audio/lv1-test-02/p1-q004.mp3","audioText":"A. Three attendees are wearing name badges behind a table. B. A speaker is presenting slides to a large audience. C. Name badges are being printed at a registration desk. D. The conference room has been rearranged for a banquet.","fullTranscript":"Three attendees are wearing name badges behind a table.","vietnamese":"A. Ba người tham dự đang đeo thẻ tên và đứng sau một chiếc bàn.\nB. Một diễn giả đang trình chiếu slide cho một lượng lớn khán giả.\nC. Những tấm thẻ tên đang được in tại quầy đăng ký.\nD. Phòng hội nghị đã được sắp xếp lại để tổ chức tiệc chiêu đãi.","optionTranslations":"A. Ba người tham dự đang đeo thẻ tên và đứng sau một chiếc bàn.\nB. Một diễn giả đang trình chiếu slide cho một lượng lớn khán giả.\nC. Những tấm thẻ tên đang được in tại quầy đăng ký.\nD. Phòng hội nghị đã được sắp xếp lại để tổ chức tiệc chiêu đãi.","explanation":"Hình có đúng ba người đứng cạnh nhau sau bàn dài; mỗi người đeo dây và thẻ tên màu trắng trước ngực. A đúng với số người, vật thể và vị trí. B sai vì không có diễn giả, màn hình hay khán giả. C sai vì không có máy in và thẻ đã được đeo sẵn, không phải đang in. D sai vì bối cảnh chỉ gồm bàn và ba người, không có bàn tiệc hay cách bài trí của tiệc chiêu đãi.","hintWords":["three","attendees","wearing","name","badges"],"keyVocab":[{"word":"attendee","meaning":"người tham dự"},{"word":"name badge","meaning":"thẻ tên"},{"word":"lanyard","meaning":"dây đeo thẻ"},{"word":"registration desk","meaning":"quầy đăng ký"},{"word":"rearrange","meaning":"sắp xếp lại"}],"practiceOptions":[{"key":"A","text":"Three attendees are wearing name badges behind a table.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p1-q004-a.mp3","keyVocab":[{"word":"attendee","meaning":"người tham dự"},{"word":"name badge","meaning":"thẻ tên"},{"word":"wear","meaning":"sự hao mòn"}]},{"key":"B","text":"A speaker is presenting slides to a large audience.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q004-b.mp3","keyVocab":[{"word":"slide","meaning":"trang trình chiếu"},{"word":"present","meaning":"trình bày"},{"word":"audience","meaning":"khán giả, thính giả"}]},{"key":"C","text":"Name badges are being printed at a registration desk.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q004-c.mp3","keyVocab":[{"word":"name badge","meaning":"thẻ tên"},{"word":"registration desk","meaning":"quầy đăng ký"},{"word":"print","meaning":"in"}]},{"key":"D","text":"The conference room has been rearranged for a banquet.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q004-d.mp3","keyVocab":[{"word":"rearrange","meaning":"sắp xếp lại"},{"word":"conference room","meaning":"phòng họp"},{"word":"banquet","meaning":"tiệc lớn, yến tiệc"}]}]},{"id":"ets-orig-test-2-q5","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 1","partNumber":1,"level":"ETS Format","title":"Test 02 • Câu 5 (Part 1: Mô tả hình ảnh (Photographs))","questionPrompt":"Look at the picture and choose the statement that best describes it.","imageType":"office_meeting","imageCaption":"Hai nhân viên ngồi tại bàn họp, phía sau là màn hình lớn hiển thị biểu đồ.","imageUrl":"listening/images/lv1-test-02/part1/q5.jpg","audioUrl":"listening/audio/lv1-test-02/p1-q005.mp3","audioText":"A. A projector is being mounted on the ceiling. B. Two employees are cleaning the meeting room. C. The meeting room is completely empty. D. Two colleagues are seated at a table near a screen displaying a chart.","fullTranscript":"Two colleagues are seated at a table near a screen displaying a chart.","vietnamese":"A. Một chiếc máy chiếu đang được lắp trên trần nhà.\nB. Hai nhân viên đang dọn dẹp phòng họp.\nC. Phòng họp hoàn toàn trống.\nD. Hai đồng nghiệp đang ngồi tại một chiếc bàn gần màn hình hiển thị biểu đồ.","optionTranslations":"A. Một chiếc máy chiếu đang được lắp trên trần nhà.\nB. Hai nhân viên đang dọn dẹp phòng họp.\nC. Phòng họp hoàn toàn trống.\nD. Hai đồng nghiệp đang ngồi tại một chiếc bàn gần màn hình hiển thị biểu đồ.","explanation":"Hình cho thấy hai người ngồi hai bên bàn, phía sau bên phải là màn hình lớn có đường biểu diễn. D khớp với số người, tư thế ngồi và vật thể trong hình. A sai vì không có máy chiếu hay người lắp đặt. B sai vì không có dụng cụ dọn dẹp và hai người đang ngồi làm việc. C sai rõ ràng vì trong phòng có hai nhân viên cùng bàn và màn hình.","hintWords":["colleagues","seated","table","near","screen"],"keyVocab":[{"word":"colleague","meaning":"đồng nghiệp"},{"word":"screen","meaning":"màn hình"},{"word":"chart","meaning":"biểu đồ"},{"word":"ceiling","meaning":"trần nhà"},{"word":"mount","meaning":"lắp đặt, gắn lên"}],"practiceOptions":[{"key":"A","text":"A projector is being mounted on the ceiling.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q005-a.mp3","keyVocab":[{"word":"ceiling","meaning":"trần nhà"},{"word":"mount","meaning":"lắp đặt, gắn lên"},{"word":"projector","meaning":"máy chiếu"}]},{"key":"B","text":"Two employees are cleaning the meeting room.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q005-b.mp3","keyVocab":[{"word":"employee","meaning":"nhân viên"}]},{"key":"C","text":"The meeting room is completely empty.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q005-c.mp3","keyVocab":[{"word":"completely","meaning":"hoàn toàn"},{"word":"empty","meaning":"trống"}]},{"key":"D","text":"Two colleagues are seated at a table near a screen displaying a chart.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p1-q005-d.mp3","keyVocab":[{"word":"colleague","meaning":"đồng nghiệp"},{"word":"screen","meaning":"màn hình"},{"word":"chart","meaning":"biểu đồ"},{"word":"seat","meaning":"có chỗ ngồi cho"}]}]},{"id":"ets-orig-test-2-q6","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 1","partNumber":1,"level":"ETS Format","title":"Test 02 • Câu 6 (Part 1: Mô tả hình ảnh (Photographs))","questionPrompt":"Look at the picture and choose the statement that best describes it.","imageType":"cafe_outdoor","imageCaption":"Một chiếc bàn trống được đặt dưới chiếc ô lớn tại khu vực ngoài trời.","imageUrl":"listening/images/lv1-test-02/part1/q6.jpg","audioUrl":"listening/audio/lv1-test-02/p1-q006.mp3","audioText":"A. A customer is paying at an outdoor counter. B. The tables have been stacked against the wall. C. A pedestal table stands beneath a wide umbrella. D. A server is watering the plants outside.","fullTranscript":"A pedestal table stands beneath a wide umbrella.","vietnamese":"A. Một khách hàng đang thanh toán tại quầy ngoài trời.\nB. Những chiếc bàn đã được xếp chồng dựa vào tường.\nC. Một chiếc bàn chân đế đứng bên dưới chiếc ô rộng.\nD. Một nhân viên phục vụ đang tưới cây ở bên ngoài.","optionTranslations":"A. Một khách hàng đang thanh toán tại quầy ngoài trời.\nB. Những chiếc bàn đã được xếp chồng dựa vào tường.\nC. Một chiếc bàn chân đế đứng bên dưới chiếc ô rộng.\nD. Một nhân viên phục vụ đang tưới cây ở bên ngoài.","explanation":"Hình chụp trắng đen cho thấy chiếc bàn chân đế đặt dưới tán ô lớn ở khu vực ngoài trời, xung quanh có cây xanh và không có người. C đúng vì mô tả chuẩn xác kiểu bàn và vị trí dưới tán ô. A sai vì không có khách hàng hay quầy thanh toán. B sai vì bàn ghế vẫn đang được bày ra, không bị xếp chồng dựa vào tường. D sai vì có cây xanh nhưng không có nhân viên phục vụ hay hoạt động tưới cây.","hintWords":["pedestal","table","stands","beneath","wide"],"keyVocab":[{"word":"umbrella","meaning":"ô, dù"},{"word":"outdoor","meaning":"ngoài trời"},{"word":"stack","meaning":"xếp chồng"},{"word":"server","meaning":"nhân viên phục vụ"},{"word":"pedestal","meaning":"chân đế"}],"practiceOptions":[{"key":"A","text":"A customer is paying at an outdoor counter.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q006-a.mp3","keyVocab":[{"word":"outdoor","meaning":"ngoài trời"},{"word":"customer","meaning":"khách hàng"},{"word":"counter","meaning":"quầy"}]},{"key":"B","text":"The tables have been stacked against the wall.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q006-b.mp3","keyVocab":[{"word":"stack","meaning":"xếp chồng"},{"word":"wall","meaning":"bức tường"}]},{"key":"C","text":"A pedestal table stands beneath a wide umbrella.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p1-q006-c.mp3","keyVocab":[{"word":"umbrella","meaning":"ô, dù"},{"word":"pedestal","meaning":"chân đế"}]},{"key":"D","text":"A server is watering the plants outside.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p1-q006-d.mp3","keyVocab":[{"word":"server","meaning":"nhân viên phục vụ"}]}]},{"id":"ets-orig-test-2-q7","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 7 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q007.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q007-q.mp3","questionScript":"Where did you put the new shipment of winter coats?","questionVi":"Anh/chị đã để lô áo khoác mùa đông mới ở đâu?","questionVocab":[{"word":"shipment","meaning":"lô hàng, chuyến hàng"}],"audioText":"Where did you put the new shipment of winter coats? A. In the stockroom on the second floor. B. Yes, they went on sale last week. C. About forty dollars each.","fullTranscript":"Question: Where did you put the new shipment of winter coats? (A) In the stockroom on the second floor. (B) Yes, they went on sale last week. (C) About forty dollars each.","vietnamese":"Câu hỏi: Anh/chị đã để lô áo khoác mùa đông mới ở đâu?\n(A) Trong kho ở tầng hai.\n(B) Vâng, tuần trước chúng đã được giảm giá.\n(C) Khoảng bốn mươi đô-la một chiếc.","optionTranslations":"Câu hỏi: Anh/chị đã để lô áo khoác mùa đông mới ở đâu?\n(A) Trong kho ở tầng hai.\n(B) Vâng, tuần trước chúng đã được giảm giá.\n(C) Khoảng bốn mươi đô-la một chiếc.","explanation":"Câu hỏi bắt đầu bằng 'Where' nên cần một cụm chỉ nơi chốn. (A) 'In the stockroom on the second floor' trả lời trực tiếp cho 'where'. (B) sai vì đây là câu hỏi Wh-, không phải Yes/No, và 'went on sale' là thông tin không được hỏi. (C) là giá tiền, phù hợp với câu hỏi 'How much' chứ không phải 'Where'.","hintWords":["question","where","shipment","winter","coats"],"keyVocab":[{"word":"shipment","meaning":"lô hàng, chuyến hàng"},{"word":"stockroom","meaning":"kho chứa hàng"},{"word":"go on sale","meaning":"được bán ra / bắt đầu giảm giá"}],"practiceOptions":[{"key":"A","text":"In the stockroom on the second floor.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q007-a.mp3","keyVocab":[{"word":"stockroom","meaning":"kho chứa hàng"},{"word":"floor","meaning":"tầng"}]},{"key":"B","text":"Yes, they went on sale last week.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q007-b.mp3","keyVocab":[{"word":"on sale","meaning":"đang được giảm giá"},{"word":"last","meaning":"kéo dài"}]},{"key":"C","text":"About forty dollars each.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q007-c.mp3","keyVocab":[{"word":"forty","meaning":"bốn mươi"},{"word":"dollar","meaning":"đô la"}]}]},{"id":"ets-orig-test-2-q8","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 8 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q008.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q008-q.mp3","questionScript":"Have you finished reconciling the bank statements for March?","questionVi":"Anh/chị đã đối chiếu xong sao kê ngân hàng của tháng Ba chưa?","questionVocab":[{"word":"reconcile","meaning":"đối chiếu (sổ sách, tài khoản)"},{"word":"bank statement","meaning":"sao kê ngân hàng"},{"word":"finish","meaning":"kết thúc"},{"word":"March","meaning":"tháng Ba"}],"audioText":"Have you finished reconciling the bank statements for March? A. The bank is just around the corner. B. Not yet—I'm still waiting for the final invoice. C. I'll take the 9:15 train to Boston.","fullTranscript":"Question: Have you finished reconciling the bank statements for March? (A) The bank is just around the corner. (B) Not yet—I'm still waiting for the final invoice. (C) I'll take the 9:15 train to Boston.","vietnamese":"Câu hỏi: Anh/chị đã đối chiếu xong sao kê ngân hàng của tháng Ba chưa?\n(A) Ngân hàng ở ngay gần đây.\n(B) Chưa — tôi vẫn đang chờ hóa đơn cuối cùng.\n(C) Tôi sẽ đi chuyến tàu 9 giờ 15 đến Boston.","optionTranslations":"Câu hỏi: Anh/chị đã đối chiếu xong sao kê ngân hàng của tháng Ba chưa?\n(A) Ngân hàng ở ngay gần đây.\n(B) Chưa — tôi vẫn đang chờ hóa đơn cuối cùng.\n(C) Tôi sẽ đi chuyến tàu 9 giờ 15 đến Boston.","explanation":"Đây là câu hỏi Yes/No dạng 'Have you finished...?'. (B) mở đầu bằng 'Not yet' (câu trả lời phủ định tự nhiên cho thì hiện tại hoàn thành) và giải thích lý do còn chờ hóa đơn — phù hợp ngữ cảnh. (A) lặp lại từ 'bank' nhưng nói về vị trí, không trả lời việc đã làm xong hay chưa. (C) nói về chuyến tàu, hoàn toàn không liên quan.","hintWords":["question","have","finished","reconciling","bank"],"keyVocab":[{"word":"reconcile","meaning":"đối chiếu (sổ sách, tài khoản)"},{"word":"bank statement","meaning":"sao kê ngân hàng"},{"word":"invoice","meaning":"hóa đơn"}],"practiceOptions":[{"key":"A","text":"The bank is just around the corner.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q008-a.mp3","keyVocab":[{"word":"around","meaning":"khoảng, chừng"},{"word":"corner","meaning":"góc phòng"}]},{"key":"B","text":"Not yet—I'm still waiting for the final invoice.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q008-b.mp3","keyVocab":[{"word":"invoice","meaning":"hóa đơn"},{"word":"final","meaning":"cuối cùng"},{"word":"not yet","meaning":"vẫn chưa"},{"word":"wait","meaning":"thời gian chờ"}]},{"key":"C","text":"I'll take the 9:15 train to Boston.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q008-c.mp3","keyVocab":[{"word":"train","meaning":"tàu hỏa"}]}]},{"id":"ets-orig-test-2-q9","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 9 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q009.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q009-q.mp3","questionScript":"The client's flight lands at six o'clock, doesn't it?","questionVi":"Chuyến bay của khách hàng hạ cánh lúc sáu giờ, đúng không?","questionVocab":[{"word":"land","meaning":"hạ cánh"},{"word":"client","meaning":"khách hàng"},{"word":"flight","meaning":"chuyến bay"}],"audioText":"The client's flight lands at six o'clock, doesn't it? A. At the information desk in Terminal 2. B. Two window seats, please. C. Actually, it's been delayed by an hour.","fullTranscript":"Question: The client's flight lands at six o'clock, doesn't it? (A) At the information desk in Terminal 2. (B) Two window seats, please. (C) Actually, it's been delayed by an hour.","vietnamese":"Câu hỏi: Chuyến bay của khách hàng hạ cánh lúc sáu giờ, đúng không?\n(A) Tại quầy thông tin ở Nhà ga số 2.\n(B) Cho tôi hai ghế cạnh cửa sổ.\n(C) Thực ra, chuyến bay đã bị hoãn một tiếng.","optionTranslations":"Câu hỏi: Chuyến bay của khách hàng hạ cánh lúc sáu giờ, đúng không?\n(A) Tại quầy thông tin ở Nhà ga số 2.\n(B) Cho tôi hai ghế cạnh cửa sổ.\n(C) Thực ra, chuyến bay đã bị hoãn một tiếng.","explanation":"Câu hỏi đuôi (tag question) 'doesn't it?' xác nhận giờ hạ cánh; (C) phản hồi bằng cách đưa thông tin mới ('delayed by an hour') — cách trả lời rất phổ biến trong Part 2. (A) trả lời cho 'Where', không phải câu hỏi đuôi về giờ. (B) là câu yêu cầu mua vé, không liên quan đến việc xác nhận giờ bay.","hintWords":["question","client","flight","lands","clock"],"keyVocab":[{"word":"land","meaning":"hạ cánh"},{"word":"delayed","meaning":"bị hoãn, bị trễ"},{"word":"terminal","meaning":"nhà ga (sân bay)"}],"practiceOptions":[{"key":"A","text":"At the information desk in Terminal 2.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q009-a.mp3","keyVocab":[{"word":"terminal","meaning":"nhà ga (sân bay)"},{"word":"desk","meaning":"bàn làm việc"}]},{"key":"B","text":"Two window seats, please.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q009-b.mp3","keyVocab":[{"word":"seat","meaning":"có chỗ ngồi cho"}]},{"key":"C","text":"Actually, it's been delayed by an hour.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q009-c.mp3","keyVocab":[{"word":"delayed","meaning":"bị hoãn, bị trễ"},{"word":"actual","meaning":"thực tế"}]}]},{"id":"ets-orig-test-2-q10","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 10 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q010.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q010-q.mp3","questionScript":"Would you like me to reserve the training room for Thursday?","questionVi":"Anh/chị có muốn tôi đặt phòng tập huấn cho thứ Năm không?","questionVocab":[{"word":"reserve","meaning":"đặt trước, giữ chỗ"},{"word":"training room","meaning":"phòng tập huấn/đào tạo"},{"word":"Thursday","meaning":"thứ Năm"}],"audioText":"Would you like me to reserve the training room for Thursday? A. That would be a real help, thanks. B. The room is quite spacious. C. He trained for six months in Osaka.","fullTranscript":"Question: Would you like me to reserve the training room for Thursday? (A) That would be a real help, thanks. (B) The room is quite spacious. (C) He trained for six months in Osaka.","vietnamese":"Câu hỏi: Anh/chị có muốn tôi đặt phòng tập huấn cho thứ Năm không?\n(A) Như vậy thì giúp tôi rất nhiều, cảm ơn.\n(B) Căn phòng khá rộng rãi.\n(C) Anh ấy đã được đào tạo sáu tháng ở Osaka.","optionTranslations":"Câu hỏi: Anh/chị có muốn tôi đặt phòng tập huấn cho thứ Năm không?\n(A) Như vậy thì giúp tôi rất nhiều, cảm ơn.\n(B) Căn phòng khá rộng rãi.\n(C) Anh ấy đã được đào tạo sáu tháng ở Osaka.","explanation":"'Would you like me to + V?' là lời đề nghị giúp đỡ; cách đáp đúng là chấp nhận hoặc từ chối lịch sự. (A) 'That would be a real help, thanks' là lời cảm ơn và đồng ý — chính xác. (B) chỉ nhận xét về căn phòng, không trả lời lời đề nghị. (C) là câu trần thuật về người khác, dùng từ 'trained' gần âm với 'training' để gây nhiễu.","hintWords":["question","would","like","reserve","training"],"keyVocab":[{"word":"reserve","meaning":"đặt trước, giữ chỗ"},{"word":"spacious","meaning":"rộng rãi"},{"word":"training room","meaning":"phòng tập huấn/đào tạo"}],"practiceOptions":[{"key":"A","text":"That would be a real help, thanks.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q010-a.mp3","keyVocab":[{"word":"help","meaning":"giúp đỡ"}]},{"key":"B","text":"The room is quite spacious.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q010-b.mp3","keyVocab":[{"word":"spacious","meaning":"rộng rãi"}]},{"key":"C","text":"He trained for six months in Osaka.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q010-c.mp3","keyVocab":[{"word":"month","meaning":"tháng"},{"word":"train","meaning":"tàu hỏa"}]}]},{"id":"ets-orig-test-2-q11","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 11 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q011.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q011-q.mp3","questionScript":"When is the scaffolding scheduled to come down?","questionVi":"Khi nào giàn giáo được dỡ xuống?","questionVocab":[{"word":"scaffolding","meaning":"giàn giáo"},{"word":"schedule","meaning":"lịch trình, tiến độ"}],"audioText":"When is the scaffolding scheduled to come down? A. The crew is still plastering the east wall. B. Yes, the site passed its safety check. C. Not until the roof inspection clears.","fullTranscript":"Question: When is the scaffolding scheduled to come down? (A) The crew is still plastering the east wall. (B) Yes, the site passed its safety check. (C) Not until the roof inspection clears.","vietnamese":"Câu hỏi: Khi nào giàn giáo được dỡ xuống?\n(A) Đội thi công vẫn đang trát tường phía đông.\n(B) Vâng, công trường đã qua kiểm tra an toàn.\n(C) Phải đến khi đợt kiểm tra mái nhà được thông qua.","optionTranslations":"Câu hỏi: Khi nào giàn giáo được dỡ xuống?\n(A) Đội thi công vẫn đang trát tường phía đông.\n(B) Vâng, công trường đã qua kiểm tra an toàn.\n(C) Phải đến khi đợt kiểm tra mái nhà được thông qua.","explanation":"'When' hỏi về thời gian; (C) 'Not until...' là cách trả lời chuẩn cho mốc thời gian (chưa thể dỡ cho đến khi kiểm tra mái xong). (A) là hoạt động đang diễn ra, không nêu thời điểm. (B) trả lời như câu Yes/No dù câu hỏi bắt đầu bằng 'When' nên sai loại.","hintWords":["question","when","scaffolding","scheduled","come"],"keyVocab":[{"word":"scaffolding","meaning":"giàn giáo"},{"word":"plaster","meaning":"trát vữa, trát tường"},{"word":"inspection","meaning":"sự kiểm tra, thanh tra"},{"word":"crew","meaning":"đội thi công, tổ nhân viên"}],"practiceOptions":[{"key":"A","text":"The crew is still plastering the east wall.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q011-a.mp3","keyVocab":[{"word":"plaster","meaning":"trát vữa, trát tường"},{"word":"crew","meaning":"đội thi công, tổ nhân viên"},{"word":"wall","meaning":"bức tường"}]},{"key":"B","text":"Yes, the site passed its safety check.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q011-b.mp3","keyVocab":[{"word":"site","meaning":"công trường, địa điểm"}]},{"key":"C","text":"Not until the roof inspection clears.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q011-c.mp3","keyVocab":[{"word":"inspection","meaning":"sự kiểm tra, thanh tra"},{"word":"clear","meaning":"dọn trống"}]}]},{"id":"ets-orig-test-2-q12","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 12 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q012.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q012-q.mp3","questionScript":"Why was the shipment of laptops sent back to the supplier?","questionVi":"Tại sao lô máy tính xách tay lại bị gửi trả cho nhà cung cấp?","questionVocab":[{"word":"supplier","meaning":"nhà cung cấp"},{"word":"laptop","meaning":"máy tính xách tay"},{"word":"shipment","meaning":"lô hàng, chuyến hàng"},{"word":"supply","meaning":"cung cấp"}],"audioText":"Why was the shipment of laptops sent back to the supplier? A. In the warehouse by the loading dock. B. Because half of them arrived with cracked screens. C. Last Tuesday afternoon, I believe.","fullTranscript":"Question: Why was the shipment of laptops sent back to the supplier? (A) In the warehouse by the loading dock. (B) Because half of them arrived with cracked screens. (C) Last Tuesday afternoon, I believe.","vietnamese":"Câu hỏi: Tại sao lô máy tính xách tay lại bị gửi trả cho nhà cung cấp?\n(A) Trong kho cạnh bến bốc hàng.\n(B) Vì một nửa số máy đến nơi bị nứt màn hình.\n(C) Tôi nghĩ là chiều thứ Ba tuần trước.","optionTranslations":"Câu hỏi: Tại sao lô máy tính xách tay lại bị gửi trả cho nhà cung cấp?\n(A) Trong kho cạnh bến bốc hàng.\n(B) Vì một nửa số máy đến nơi bị nứt màn hình.\n(C) Tôi nghĩ là chiều thứ Ba tuần trước.","explanation":"'Why' hỏi nguyên nhân nên đáp án phải nêu lý do, thường bắt đầu bằng 'Because'. (B) giải thích rõ nguyên nhân (nứt màn hình) — chính xác. (A) là nơi chốn (trả lời 'Where'), (C) là thời gian (trả lời 'When'), cả hai đều sai loại thông tin dù cùng chủ đề giao hàng.","hintWords":["question","shipment","laptops","sent","back"],"keyVocab":[{"word":"supplier","meaning":"nhà cung cấp"},{"word":"warehouse","meaning":"nhà kho"},{"word":"cracked","meaning":"bị nứt, bị rạn"},{"word":"loading dock","meaning":"bến bốc xếp hàng"}],"practiceOptions":[{"key":"A","text":"In the warehouse by the loading dock.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q012-a.mp3","keyVocab":[{"word":"warehouse","meaning":"nhà kho"},{"word":"loading dock","meaning":"bến bốc xếp hàng"}]},{"key":"B","text":"Because half of them arrived with cracked screens.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q012-b.mp3","keyVocab":[{"word":"cracked","meaning":"bị nứt, bị rạn"},{"word":"screen","meaning":"màn hình"},{"word":"arrive","meaning":"đến nơi"}]},{"key":"C","text":"Last Tuesday afternoon, I believe.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q012-c.mp3","keyVocab":[{"word":"last","meaning":"kéo dài"},{"word":"afternoon","meaning":"buổi chiều"},{"word":"believe","meaning":"tin rằng, cho rằng"},{"word":"Tuesday","meaning":"thứ Ba"}]}]},{"id":"ets-orig-test-2-q13","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 13 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q013.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q013-q.mp3","questionScript":"Could you forward me the latest budget spreadsheet?","questionVi":"Anh/chị có thể chuyển tiếp cho tôi bảng tính ngân sách mới nhất không?","questionVocab":[{"word":"forward","meaning":"chuyển tiếp (email, tài liệu)"},{"word":"spreadsheet","meaning":"bảng tính"},{"word":"budget","meaning":"ngân sách"},{"word":"latest","meaning":"mới nhất"}],"audioText":"Could you forward me the latest budget spreadsheet? A. Sure, I'll send it right after this call. B. The budget was approved back in June. C. No, I've never been to Paris.","fullTranscript":"Question: Could you forward me the latest budget spreadsheet? (A) Sure, I'll send it right after this call. (B) The budget was approved back in June. (C) No, I've never been to Paris.","vietnamese":"Câu hỏi: Anh/chị có thể chuyển tiếp cho tôi bảng tính ngân sách mới nhất không?\n(A) Được, tôi sẽ gửi ngay sau cuộc gọi này.\n(B) Ngân sách đã được phê duyệt hồi tháng Sáu.\n(C) Không, tôi chưa bao giờ đến Paris.","optionTranslations":"Câu hỏi: Anh/chị có thể chuyển tiếp cho tôi bảng tính ngân sách mới nhất không?\n(A) Được, tôi sẽ gửi ngay sau cuộc gọi này.\n(B) Ngân sách đã được phê duyệt hồi tháng Sáu.\n(C) Không, tôi chưa bao giờ đến Paris.","explanation":"'Could you + V?' là lời yêu cầu lịch sự; (A) 'Sure, I'll send it...' vừa đồng ý vừa nêu hành động cụ thể — phù hợp nhất. (B) nói về việc phê duyệt ngân sách, không phải việc gửi tệp. (C) trả lời 'No' cho một câu hỏi về Paris hoàn toàn không xuất hiện trong câu hỏi.","hintWords":["question","could","forward","latest","budget"],"keyVocab":[{"word":"forward","meaning":"chuyển tiếp (email, tài liệu)"},{"word":"spreadsheet","meaning":"bảng tính"},{"word":"approve","meaning":"phê duyệt"}],"practiceOptions":[{"key":"A","text":"Sure, I'll send it right after this call.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q013-a.mp3","keyVocab":[{"word":"sure","meaning":"chắc chắn"},{"word":"call","meaning":"cuộc gọi, gọi"},{"word":"right after","meaning":"ngay sau"}]},{"key":"B","text":"The budget was approved back in June.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q013-b.mp3","keyVocab":[{"word":"approve","meaning":"phê duyệt"},{"word":"budget","meaning":"ngân sách"}]},{"key":"C","text":"No, I've never been to Paris.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q013-c.mp3","keyVocab":[{"word":"never","meaning":"chưa từng, chưa bao giờ"}]}]},{"id":"ets-orig-test-2-q14","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 14 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q014.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q014-q.mp3","questionScript":"How many people signed up for the leadership workshop?","questionVi":"Bao nhiêu người đã đăng ký buổi hội thảo về kỹ năng lãnh đạo?","questionVocab":[{"word":"sign up","meaning":"đăng ký tham gia"},{"word":"workshop","meaning":"buổi hội thảo, buổi tập huấn"},{"word":"leadership","meaning":"năng lực lãnh đạo"},{"word":"sign-up","meaning":"việc đăng ký"}],"audioText":"How many people signed up for the leadership workshop? A. In the main conference hall. B. It was a very useful workshop. C. Thirty-two, according to the registration list.","fullTranscript":"Question: How many people signed up for the leadership workshop? (A) In the main conference hall. (B) It was a very useful workshop. (C) Thirty-two, according to the registration list.","vietnamese":"Câu hỏi: Bao nhiêu người đã đăng ký buổi hội thảo về kỹ năng lãnh đạo?\n(A) Ở hội trường chính.\n(B) Đó là một buổi hội thảo rất bổ ích.\n(C) Ba mươi hai người, theo danh sách đăng ký.","optionTranslations":"Câu hỏi: Bao nhiêu người đã đăng ký buổi hội thảo về kỹ năng lãnh đạo?\n(A) Ở hội trường chính.\n(B) Đó là một buổi hội thảo rất bổ ích.\n(C) Ba mươi hai người, theo danh sách đăng ký.","explanation":"'How many' hỏi số lượng nên đáp án phải là một con số. (C) nêu 'Thirty-two' kèm nguồn thông tin — chính xác. (A) là địa điểm (trả lời 'Where'), (B) là nhận xét về chất lượng buổi hội thảo, cả hai đều không trả lời số lượng.","hintWords":["question","many","people","signed","leadership"],"keyVocab":[{"word":"sign up","meaning":"đăng ký tham gia"},{"word":"registration","meaning":"sự đăng ký"},{"word":"workshop","meaning":"buổi hội thảo, buổi tập huấn"}],"practiceOptions":[{"key":"A","text":"In the main conference hall.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q014-a.mp3","keyVocab":[{"word":"conference","meaning":"hội nghị"},{"word":"hall","meaning":"hành lang"}]},{"key":"B","text":"It was a very useful workshop.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q014-b.mp3","keyVocab":[{"word":"workshop","meaning":"buổi hội thảo, buổi tập huấn"}]},{"key":"C","text":"Thirty-two, according to the registration list.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q014-c.mp3","keyVocab":[{"word":"registration","meaning":"sự đăng ký"},{"word":"list","meaning":"danh sách; liệt kê"}]}]},{"id":"ets-orig-test-2-q15","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 15 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q015.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q015-q.mp3","questionScript":"Did the building inspector approve the electrical work?","questionVi":"Thanh tra xây dựng đã nghiệm thu phần điện chưa?","questionVocab":[{"word":"inspector","meaning":"thanh tra viên, người kiểm tra"},{"word":"electrical work","meaning":"công việc điện, phần điện"},{"word":"approve","meaning":"phê duyệt, chấp thuận"},{"word":"building","meaning":"tòa nhà"}],"audioText":"Did the building inspector approve the electrical work? A. The inspector was quite friendly. B. Yes, but he asked us to fix two outlets. C. It's due on the twenty-first.","fullTranscript":"Question: Did the building inspector approve the electrical work? (A) The inspector was quite friendly. (B) Yes, but he asked us to fix two outlets. (C) It's due on the twenty-first.","vietnamese":"Câu hỏi: Thanh tra xây dựng đã nghiệm thu phần điện chưa?\n(A) Viên thanh tra khá thân thiện.\n(B) Rồi, nhưng ông ấy yêu cầu chúng tôi sửa hai ổ cắm.\n(C) Hạn chót là ngày 21.","optionTranslations":"Câu hỏi: Thanh tra xây dựng đã nghiệm thu phần điện chưa?\n(A) Viên thanh tra khá thân thiện.\n(B) Rồi, nhưng ông ấy yêu cầu chúng tôi sửa hai ổ cắm.\n(C) Hạn chót là ngày 21.","explanation":"Câu hỏi Yes/No dạng 'Did...?' cần câu trả lời khẳng định hoặc phủ định. (B) 'Yes, but...' vừa xác nhận vừa bổ sung điều kiện — chính xác và tự nhiên. (A) chỉ nhận xét tính cách viên thanh tra, không trả lời việc nghiệm thu. (C) nói về hạn chót, không liên quan.","hintWords":["question","building","inspector","approve","electrical"],"keyVocab":[{"word":"inspector","meaning":"thanh tra viên, người kiểm tra"},{"word":"outlet","meaning":"ổ cắm điện"},{"word":"electrical work","meaning":"công việc điện, phần điện"},{"word":"be due","meaning":"đến hạn"}],"practiceOptions":[{"key":"A","text":"The inspector was quite friendly.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q015-a.mp3","keyVocab":[{"word":"inspector","meaning":"thanh tra viên, người kiểm tra"}]},{"key":"B","text":"Yes, but he asked us to fix two outlets.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q015-b.mp3","keyVocab":[{"word":"outlet","meaning":"ổ cắm điện"}]},{"key":"C","text":"It's due on the twenty-first.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q015-c.mp3","keyVocab":[{"word":"due","meaning":"đến hạn"},{"word":"twenty","meaning":"hai mươi"}]}]},{"id":"ets-orig-test-2-q16","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 16 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q016.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q016-q.mp3","questionScript":"Should we book the hotel before the conference rates go up?","questionVi":"Chúng ta có nên đặt khách sạn trước khi giá phòng cho hội nghị tăng không?","questionVocab":[{"word":"book","meaning":"đặt (phòng, vé)"},{"word":"rate","meaning":"giá, mức giá"},{"word":"go up","meaning":"tăng lên"},{"word":"conference","meaning":"hội nghị"}],"audioText":"Should we book the hotel before the conference rates go up? A. Definitely—I'll do it this afternoon. B. The conference was well organized. C. By train, I think.","fullTranscript":"Question: Should we book the hotel before the conference rates go up? (A) Definitely—I'll do it this afternoon. (B) The conference was well organized. (C) By train, I think.","vietnamese":"Câu hỏi: Chúng ta có nên đặt khách sạn trước khi giá phòng cho hội nghị tăng không?\n(A) Chắc chắn rồi — chiều nay tôi sẽ đặt.\n(B) Hội nghị đã được tổ chức rất tốt.\n(C) Tôi nghĩ là đi tàu.","optionTranslations":"Câu hỏi: Chúng ta có nên đặt khách sạn trước khi giá phòng cho hội nghị tăng không?\n(A) Chắc chắn rồi — chiều nay tôi sẽ đặt.\n(B) Hội nghị đã được tổ chức rất tốt.\n(C) Tôi nghĩ là đi tàu.","explanation":"'Should we...?' là câu hỏi đề xuất, cần câu trả lời đồng ý/từ chối kèm hướng hành động. (A) 'Definitely—I'll do it this afternoon' thể hiện sự đồng tình và nhận việc — chính xác. (B) nhận xét hội nghị (dùng từ 'conference' gây nhiễu). (C) trả lời cho 'How will you get there?', không phải câu hỏi về việc đặt phòng.","hintWords":["question","should","book","hotel","before"],"keyVocab":[{"word":"book","meaning":"đặt (phòng, vé)"},{"word":"rate","meaning":"giá, mức giá"},{"word":"go up","meaning":"tăng lên"}],"practiceOptions":[{"key":"A","text":"Definitely—I'll do it this afternoon.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q016-a.mp3","keyVocab":[{"word":"afternoon","meaning":"buổi chiều"}]},{"key":"B","text":"The conference was well organized.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q016-b.mp3","keyVocab":[{"word":"conference","meaning":"hội nghị"}]},{"key":"C","text":"By train, I think.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q016-c.mp3","keyVocab":[{"word":"train","meaning":"tàu hỏa"}]}]},{"id":"ets-orig-test-2-q17","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 17 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q017.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q017-q.mp3","questionScript":"Who is handling the quarterly tax filing this year?","questionVi":"Ai đang phụ trách việc khai thuế hàng quý năm nay?","questionVocab":[{"word":"handle","meaning":"phụ trách, xử lý"},{"word":"quarterly","meaning":"hàng quý"},{"word":"tax filing","meaning":"việc khai thuế"},{"word":"file","meaning":"nộp (hồ sơ, tờ khai thuế); hồ sơ"}],"audioText":"Who is handling the quarterly tax filing this year? A. It's usually due in April. B. Yes, the figures look accurate. C. Ms. Tran has taken it over from Mr. Cole.","fullTranscript":"Question: Who is handling the quarterly tax filing this year? (A) It's usually due in April. (B) Yes, the figures look accurate. (C) Ms. Tran has taken it over from Mr. Cole.","vietnamese":"Câu hỏi: Ai đang phụ trách việc khai thuế hàng quý năm nay?\n(A) Thường thì đến hạn vào tháng Tư.\n(B) Vâng, các con số có vẻ chính xác.\n(C) Cô Trần đã tiếp nhận việc này từ ông Cole.","optionTranslations":"Câu hỏi: Ai đang phụ trách việc khai thuế hàng quý năm nay?\n(A) Thường thì đến hạn vào tháng Tư.\n(B) Vâng, các con số có vẻ chính xác.\n(C) Cô Trần đã tiếp nhận việc này từ ông Cole.","explanation":"'Who' hỏi người nên đáp án phải nêu tên hoặc chức danh. (C) nêu 'Ms. Tran' và việc bàn giao — chính xác. (A) trả lời 'When' (thời hạn), (B) là câu trả lời Yes/No cho câu hỏi không phải dạng Yes/No, cả hai đều sai loại.","hintWords":["question","handling","quarterly","filing","this"],"keyVocab":[{"word":"handle","meaning":"phụ trách, xử lý"},{"word":"quarterly","meaning":"hàng quý"},{"word":"tax filing","meaning":"việc khai thuế"},{"word":"take over","meaning":"tiếp nhận, đảm nhận"}],"practiceOptions":[{"key":"A","text":"It's usually due in April.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q017-a.mp3","keyVocab":[{"word":"due","meaning":"đến hạn"},{"word":"usually","meaning":"thông thường, thường lệ"}]},{"key":"B","text":"Yes, the figures look accurate.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q017-b.mp3","keyVocab":[{"word":"figure","meaning":"con số"}]},{"key":"C","text":"Ms. Tran has taken it over from Mr. Cole.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q017-c.mp3","keyVocab":[{"word":"taken over","meaning":"tiếp quản"}]}]},{"id":"ets-orig-test-2-q18","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 18 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q018.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q018-q.mp3","questionScript":"This order qualifies for free shipping, doesn't it?","questionVi":"Đơn hàng này được miễn phí vận chuyển, đúng không?","questionVocab":[{"word":"qualify for","meaning":"đủ điều kiện để được hưởng"},{"word":"free shipping","meaning":"miễn phí vận chuyển"},{"word":"order","meaning":"đơn hàng"}],"audioText":"This order qualifies for free shipping, doesn't it? A. The shipping department is upstairs. B. Only if it's over fifty dollars. C. I ordered the blue model.","fullTranscript":"Question: This order qualifies for free shipping, doesn't it? (A) The shipping department is upstairs. (B) Only if it's over fifty dollars. (C) I ordered the blue model.","vietnamese":"Câu hỏi: Đơn hàng này được miễn phí vận chuyển, đúng không?\n(A) Bộ phận vận chuyển ở tầng trên.\n(B) Chỉ khi đơn hàng trên năm mươi đô-la.\n(C) Tôi đã đặt mẫu màu xanh.","optionTranslations":"Câu hỏi: Đơn hàng này được miễn phí vận chuyển, đúng không?\n(A) Bộ phận vận chuyển ở tầng trên.\n(B) Chỉ khi đơn hàng trên năm mươi đô-la.\n(C) Tôi đã đặt mẫu màu xanh.","explanation":"Câu hỏi đuôi xác nhận điều kiện miễn phí vận chuyển; (B) 'Only if...' nêu điều kiện kèm theo — cách phản hồi chính xác vì thực tế không phải đơn nào cũng được miễn phí. (A) nói về vị trí phòng ban, (C) nói về mẫu sản phẩm đã đặt, đều không trả lời việc có được miễn phí hay không.","hintWords":["question","this","order","qualifies","free"],"keyVocab":[{"word":"qualify for","meaning":"đủ điều kiện để được hưởng"},{"word":"free shipping","meaning":"miễn phí vận chuyển"},{"word":"order","meaning":"đơn hàng"}],"practiceOptions":[{"key":"A","text":"The shipping department is upstairs.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q018-a.mp3","keyVocab":[{"word":"department","meaning":"phòng, ban"},{"word":"ship","meaning":"gửi hàng, vận chuyển"}]},{"key":"B","text":"Only if it's over fifty dollars.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q018-b.mp3","keyVocab":[{"word":"only if","meaning":"chỉ khi nào"},{"word":"dollar","meaning":"đô la"}]},{"key":"C","text":"I ordered the blue model.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q018-c.mp3","keyVocab":[{"word":"order","meaning":"đơn hàng"}]}]},{"id":"ets-orig-test-2-q19","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 19 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q019.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q019-q.mp3","questionScript":"The client wants to move our meeting to Friday afternoon.","questionVi":"Khách hàng muốn dời cuộc họp của chúng ta sang chiều thứ Sáu.","questionVocab":[{"word":"move","meaning":"dời, thay đổi (lịch)"},{"word":"client","meaning":"khách hàng"},{"word":"afternoon","meaning":"buổi chiều"}],"audioText":"The client wants to move our meeting to Friday afternoon. A. Friday works for me—let's confirm it. B. The client's office is downtown. C. We met there last year.","fullTranscript":"Question: The client wants to move our meeting to Friday afternoon. (A) Friday works for me—let's confirm it. (B) The client's office is downtown. (C) We met there last year.","vietnamese":"Câu trần thuật: Khách hàng muốn dời cuộc họp của chúng ta sang chiều thứ Sáu.\n(A) Thứ Sáu tôi rảnh — chúng ta xác nhận luôn nhé.\n(B) Văn phòng khách hàng ở trung tâm thành phố.\n(C) Chúng tôi đã gặp nhau ở đó năm ngoái.","optionTranslations":"Câu trần thuật: Khách hàng muốn dời cuộc họp của chúng ta sang chiều thứ Sáu.\n(A) Thứ Sáu tôi rảnh — chúng ta xác nhận luôn nhé.\n(B) Văn phòng khách hàng ở trung tâm thành phố.\n(C) Chúng tôi đã gặp nhau ở đó năm ngoái.","explanation":"Đây là câu trần thuật (statement), không phải câu hỏi; người nghe cần phản hồi về thông tin vừa nêu. (A) đồng ý với thời điểm mới và đề nghị xác nhận — phù hợp nhất. (B) nói về địa chỉ văn phòng, (C) nói về lần gặp trước, đều không phản hồi việc dời lịch.","hintWords":["question","client","wants","move","meeting"],"keyVocab":[{"word":"move (a meeting)","meaning":"dời (cuộc họp)"},{"word":"confirm","meaning":"xác nhận"},{"word":"downtown","meaning":"ở trung tâm thành phố"}],"practiceOptions":[{"key":"A","text":"Friday works for me—let's confirm it.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q019-a.mp3","keyVocab":[{"word":"confirm","meaning":"xác nhận"}]},{"key":"B","text":"The client's office is downtown.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q019-b.mp3","keyVocab":[{"word":"downtown","meaning":"ở trung tâm thành phố"},{"word":"client","meaning":"khách hàng"}]},{"key":"C","text":"We met there last year.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q019-c.mp3","keyVocab":[{"word":"last","meaning":"kéo dài"},{"word":"met","meaning":"đã gặp"}]}]},{"id":"ets-orig-test-2-q20","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 20 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q020.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q020-q.mp3","questionScript":"Are you attending the safety certification course next week?","questionVi":"Tuần sau anh/chị có tham dự khóa chứng nhận an toàn không?","questionVocab":[{"word":"attend","meaning":"tham dự"},{"word":"certification","meaning":"chứng nhận"}],"audioText":"Are you attending the safety certification course next week? A. The certification expires in two years. B. I wish I could, but I'll be at a trade show. C. It's on the third floor.","fullTranscript":"Question: Are you attending the safety certification course next week? (A) The certification expires in two years. (B) I wish I could, but I'll be at a trade show. (C) It's on the third floor.","vietnamese":"Câu hỏi: Tuần sau anh/chị có tham dự khóa chứng nhận an toàn không?\n(A) Chứng nhận này hết hạn sau hai năm.\n(B) Tôi ước là có thể, nhưng tôi sẽ ở hội chợ thương mại.\n(C) Nó ở tầng ba.","optionTranslations":"Câu hỏi: Tuần sau anh/chị có tham dự khóa chứng nhận an toàn không?\n(A) Chứng nhận này hết hạn sau hai năm.\n(B) Tôi ước là có thể, nhưng tôi sẽ ở hội chợ thương mại.\n(C) Nó ở tầng ba.","explanation":"Câu hỏi Yes/No về việc tham dự; (B) 'I wish I could, but...' là cách từ chối lịch sự kèm lý do — chính xác. (A) nói về thời hạn chứng nhận, không trả lời việc có tham dự hay không. (C) trả lời 'Where', không phù hợp câu hỏi Yes/No.","hintWords":["question","attending","safety","certification","course"],"keyVocab":[{"word":"attend","meaning":"tham dự"},{"word":"certification","meaning":"chứng nhận"},{"word":"expire","meaning":"hết hạn"},{"word":"trade show","meaning":"hội chợ thương mại"}],"practiceOptions":[{"key":"A","text":"The certification expires in two years.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q020-a.mp3","keyVocab":[{"word":"certification","meaning":"chứng nhận"},{"word":"expire","meaning":"hết hạn"}]},{"key":"B","text":"I wish I could, but I'll be at a trade show.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q020-b.mp3","keyVocab":[{"word":"trade show","meaning":"hội chợ thương mại"}]},{"key":"C","text":"It's on the third floor.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q020-c.mp3","keyVocab":[{"word":"floor","meaning":"tầng"}]}]},{"id":"ets-orig-test-2-q21","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 21 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q021.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q021-q.mp3","questionScript":"How long will the renovation of the lobby take?","questionVi":"Việc cải tạo sảnh chờ sẽ mất bao lâu?","questionVocab":[{"word":"renovation","meaning":"sự cải tạo, sửa chữa lớn"},{"word":"lobby","meaning":"sảnh chờ, tiền sảnh"}],"audioText":"How long will the renovation of the lobby take? A. The lobby is on the ground floor. B. Yes, they started on Monday. C. Roughly six weeks, according to the contractor.","fullTranscript":"Question: How long will the renovation of the lobby take? (A) The lobby is on the ground floor. (B) Yes, they started on Monday. (C) Roughly six weeks, according to the contractor.","vietnamese":"Câu hỏi: Việc cải tạo sảnh chờ sẽ mất bao lâu?\n(A) Sảnh chờ ở tầng trệt.\n(B) Vâng, họ đã bắt đầu từ thứ Hai.\n(C) Khoảng sáu tuần, theo nhà thầu.","optionTranslations":"Câu hỏi: Việc cải tạo sảnh chờ sẽ mất bao lâu?\n(A) Sảnh chờ ở tầng trệt.\n(B) Vâng, họ đã bắt đầu từ thứ Hai.\n(C) Khoảng sáu tuần, theo nhà thầu.","explanation":"'How long' hỏi khoảng thời gian nên đáp án phải là một độ dài thời gian. (C) 'Roughly six weeks' trả lời trực tiếp — chính xác. (A) là vị trí, (B) là câu trả lời Yes/No kèm mốc bắt đầu, cả hai đều không nêu thời lượng.","hintWords":["question","long","will","renovation","lobby"],"keyVocab":[{"word":"renovation","meaning":"sự cải tạo, sửa chữa lớn"},{"word":"lobby","meaning":"sảnh chờ, tiền sảnh"},{"word":"contractor","meaning":"nhà thầu"},{"word":"roughly","meaning":"khoảng chừng"}],"practiceOptions":[{"key":"A","text":"The lobby is on the ground floor.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q021-a.mp3","keyVocab":[{"word":"lobby","meaning":"sảnh chờ, tiền sảnh"},{"word":"floor","meaning":"tầng"}]},{"key":"B","text":"Yes, they started on Monday.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q021-b.mp3","keyVocab":[{"word":"Monday","meaning":"thứ Hai"},{"word":"start","meaning":"bắt đầu"}]},{"key":"C","text":"Roughly six weeks, according to the contractor.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q021-c.mp3","keyVocab":[{"word":"contractor","meaning":"nhà thầu"},{"word":"roughly","meaning":"khoảng chừng"}]}]},{"id":"ets-orig-test-2-q22","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 22 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q022.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q022-q.mp3","questionScript":"Would you mind double-checking these figures before I submit them?","questionVi":"Anh/chị có phiền kiểm tra lại những con số này trước khi tôi nộp không?","questionVocab":[{"word":"double-check","meaning":"kiểm tra lại"},{"word":"figure","meaning":"con số"},{"word":"submit","meaning":"nộp, trình"}],"audioText":"Would you mind double-checking these figures before I submit them? A. Not at all—give me ten minutes. B. I submitted it yesterday. C. Yes, the numbers are quite high.","fullTranscript":"Question: Would you mind double-checking these figures before I submit them? (A) Not at all—give me ten minutes. (B) I submitted it yesterday. (C) Yes, the numbers are quite high.","vietnamese":"Câu hỏi: Anh/chị có phiền kiểm tra lại những con số này trước khi tôi nộp không?\n(A) Không phiền chút nào — cho tôi mười phút.\n(B) Tôi đã nộp nó hôm qua.\n(C) Vâng, các con số khá cao.","optionTranslations":"Câu hỏi: Anh/chị có phiền kiểm tra lại những con số này trước khi tôi nộp không?\n(A) Không phiền chút nào — cho tôi mười phút.\n(B) Tôi đã nộp nó hôm qua.\n(C) Vâng, các con số khá cao.","explanation":"'Would you mind + V-ing?' hỏi một cách lịch sự; nếu đồng ý thì trả lời 'Not at all' (không phiền). (A) đúng cả về hình thức lẫn nội dung. (C) sai vì 'Yes' ở câu hỏi này mang nghĩa từ chối, và nội dung nói về độ cao của con số chứ không phải việc kiểm tra. (B) nói về việc đã nộp, không liên quan.","hintWords":["question","would","mind","double","checking"],"keyVocab":[{"word":"double-check","meaning":"kiểm tra lại"},{"word":"figure","meaning":"con số"},{"word":"submit","meaning":"nộp, trình"}],"practiceOptions":[{"key":"A","text":"Not at all—give me ten minutes.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q022-a.mp3","keyVocab":[{"word":"minute","meaning":"phút"}]},{"key":"B","text":"I submitted it yesterday.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q022-b.mp3","keyVocab":[{"word":"submit","meaning":"nộp, trình"},{"word":"yesterday","meaning":"hôm qua"}]},{"key":"C","text":"Yes, the numbers are quite high.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q022-c.mp3","keyVocab":[{"word":"high","meaning":"nhiệt độ cao nhất"}]}]},{"id":"ets-orig-test-2-q23","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 23 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q023.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q023-q.mp3","questionScript":"Why did the regional manager cancel her trip to Singapore?","questionVi":"Tại sao giám đốc khu vực lại hủy chuyến công tác đến Singapore?","questionVocab":[{"word":"regional manager","meaning":"giám đốc khu vực"},{"word":"cancel","meaning":"hủy"}],"audioText":"Why did the regional manager cancel her trip to Singapore? A. She travels almost every month. B. By way of Hong Kong. C. She's recovering from the flu.","fullTranscript":"Question: Why did the regional manager cancel her trip to Singapore? (A) She travels almost every month. (B) By way of Hong Kong. (C) She's recovering from the flu.","vietnamese":"Câu hỏi: Tại sao giám đốc khu vực lại hủy chuyến công tác đến Singapore?\n(A) Cô ấy gần như tháng nào cũng đi công tác.\n(B) Quá cảnh qua Hồng Kông.\n(C) Cô ấy đang hồi phục sau cơn cúm.","optionTranslations":"Câu hỏi: Tại sao giám đốc khu vực lại hủy chuyến công tác đến Singapore?\n(A) Cô ấy gần như tháng nào cũng đi công tác.\n(B) Quá cảnh qua Hồng Kông.\n(C) Cô ấy đang hồi phục sau cơn cúm.","explanation":"'Why' hỏi lý do; (C) nêu nguyên nhân sức khỏe — chính xác. (A) là thói quen đi lại, không phải lý do hủy chuyến. (B) trả lời cho 'How / By what route?', không liên quan đến việc hủy chuyến.","hintWords":["question","regional","manager","cancel","trip"],"keyVocab":[{"word":"regional manager","meaning":"giám đốc khu vực"},{"word":"cancel","meaning":"hủy"},{"word":"recover","meaning":"hồi phục"},{"word":"by way of","meaning":"quá cảnh qua"}],"practiceOptions":[{"key":"A","text":"She travels almost every month.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q023-a.mp3","keyVocab":[{"word":"travel","meaning":"đi lại, du lịch"},{"word":"month","meaning":"tháng"}]},{"key":"B","text":"By way of Hong Kong.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q023-b.mp3","keyVocab":[{"word":"by way of","meaning":"quá cảnh qua"}]},{"key":"C","text":"She's recovering from the flu.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q023-c.mp3","keyVocab":[{"word":"recover","meaning":"hồi phục"}]}]},{"id":"ets-orig-test-2-q24","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 24 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q024.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q024-q.mp3","questionScript":"The auditor will be here first thing Monday morning.","questionVi":"Kiểm toán viên sẽ đến vào sáng thứ Hai.","questionVocab":[{"word":"auditor","meaning":"kiểm toán viên"},{"word":"first thing","meaning":"ngay từ đầu (buổi sáng)"},{"word":"Monday","meaning":"thứ Hai"},{"word":"morning","meaning":"buổi sáng"}],"audioText":"The auditor will be here first thing Monday morning. A. The morning shift starts at seven. B. I'll have all the records ready by then. C. Monday is a public holiday.","fullTranscript":"Question: The auditor will be here first thing Monday morning. (A) The morning shift starts at seven. (B) I'll have all the records ready by then. (C) Monday is a public holiday.","vietnamese":"Câu trần thuật: Kiểm toán viên sẽ đến vào sáng thứ Hai.\n(A) Ca sáng bắt đầu lúc bảy giờ.\n(B) Tôi sẽ chuẩn bị xong toàn bộ hồ sơ trước lúc đó.\n(C) Thứ Hai là ngày lễ.","optionTranslations":"Câu trần thuật: Kiểm toán viên sẽ đến vào sáng thứ Hai.\n(A) Ca sáng bắt đầu lúc bảy giờ.\n(B) Tôi sẽ chuẩn bị xong toàn bộ hồ sơ trước lúc đó.\n(C) Thứ Hai là ngày lễ.","explanation":"Với câu trần thuật, phản hồi phù hợp là thể hiện sự chuẩn bị hoặc phản ứng với thông tin. (B) 'I'll have all the records ready by then' là câu đáp tự nhiên, thể hiện trách nhiệm — chính xác. (A) nói về giờ ca làm (dùng từ 'morning' gây nhiễu). (C) tuy có thể là thông tin đáng chú ý nhưng không phải phản hồi trực tiếp cho việc kiểm toán viên đến.","hintWords":["question","auditor","will","here","first"],"keyVocab":[{"word":"auditor","meaning":"kiểm toán viên"},{"word":"first thing","meaning":"ngay từ đầu (buổi sáng)"},{"word":"records","meaning":"hồ sơ, sổ sách"},{"word":"shift","meaning":"ca làm việc"}],"practiceOptions":[{"key":"A","text":"The morning shift starts at seven.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q024-a.mp3","keyVocab":[{"word":"shift","meaning":"ca làm việc"},{"word":"morning","meaning":"buổi sáng"},{"word":"start","meaning":"bắt đầu"}]},{"key":"B","text":"I'll have all the records ready by then.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q024-b.mp3","keyVocab":[{"word":"records","meaning":"hồ sơ, sổ sách"}]},{"key":"C","text":"Monday is a public holiday.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q024-c.mp3","keyVocab":[{"word":"Monday","meaning":"thứ Hai"},{"word":"public holiday","meaning":"ngày lễ"}]}]},{"id":"ets-orig-test-2-q25","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 25 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q025.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q025-q.mp3","questionScript":"What was the customer's complaint about?","questionVi":"Khách hàng đã phàn nàn về việc gì?","questionVocab":[{"word":"complaint","meaning":"lời phàn nàn, khiếu nại"},{"word":"customer","meaning":"khách hàng"}],"audioText":"What was the customer's complaint about? A. A missing part in the assembly kit. B. She called twice yesterday. C. At the service counter.","fullTranscript":"Question: What was the customer's complaint about? (A) A missing part in the assembly kit. (B) She called twice yesterday. (C) At the service counter.","vietnamese":"Câu hỏi: Khách hàng đã phàn nàn về việc gì?\n(A) Một bộ phận bị thiếu trong bộ lắp ráp.\n(B) Cô ấy đã gọi hai lần vào hôm qua.\n(C) Tại quầy dịch vụ.","optionTranslations":"Câu hỏi: Khách hàng đã phàn nàn về việc gì?\n(A) Một bộ phận bị thiếu trong bộ lắp ráp.\n(B) Cô ấy đã gọi hai lần vào hôm qua.\n(C) Tại quầy dịch vụ.","explanation":"'What ... about?' hỏi nội dung/đối tượng của lời phàn nàn; (A) nêu đúng vấn đề (thiếu phụ tùng) — chính xác. (B) nói về số lần gọi điện, không phải nội dung phàn nàn. (C) trả lời 'Where', sai loại thông tin.","hintWords":["question","what","customer","complaint","about"],"keyVocab":[{"word":"complaint","meaning":"lời phàn nàn, khiếu nại"},{"word":"assembly kit","meaning":"bộ lắp ráp"},{"word":"service counter","meaning":"quầy dịch vụ"}],"practiceOptions":[{"key":"A","text":"A missing part in the assembly kit.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q025-a.mp3","keyVocab":[{"word":"assembly kit","meaning":"bộ lắp ráp"},{"word":"missing","meaning":"bị mất, thiếu"}]},{"key":"B","text":"She called twice yesterday.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q025-b.mp3","keyVocab":[{"word":"call","meaning":"cuộc gọi, gọi"},{"word":"twice","meaning":"hai lần"},{"word":"yesterday","meaning":"hôm qua"}]},{"key":"C","text":"At the service counter.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q025-c.mp3","keyVocab":[{"word":"service counter","meaning":"quầy dịch vụ"}]}]},{"id":"ets-orig-test-2-q26","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 26 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q026.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q026-q.mp3","questionScript":"You've already sent the invitation to the vendors, haven't you?","questionVi":"Anh/chị đã gửi thư mời cho các nhà cung cấp rồi, đúng không?","questionVocab":[{"word":"invitation","meaning":"thư mời, lời mời"},{"word":"vendor","meaning":"nhà cung cấp, nhà bán hàng"}],"audioText":"You've already sent the invitation to the vendors, haven't you? A. The vendors are in the next building. B. Yes, the invitation was beautiful. C. Not yet—I'm sending them this afternoon.","fullTranscript":"Question: You've already sent the invitation to the vendors, haven't you? (A) The vendors are in the next building. (B) Yes, the invitation was beautiful. (C) Not yet—I'm sending them this afternoon.","vietnamese":"Câu hỏi: Anh/chị đã gửi thư mời cho các nhà cung cấp rồi, đúng không?\n(A) Các nhà cung cấp ở tòa nhà bên cạnh.\n(B) Vâng, thư mời rất đẹp.\n(C) Chưa — chiều nay tôi sẽ gửi.","optionTranslations":"Câu hỏi: Anh/chị đã gửi thư mời cho các nhà cung cấp rồi, đúng không?\n(A) Các nhà cung cấp ở tòa nhà bên cạnh.\n(B) Vâng, thư mời rất đẹp.\n(C) Chưa — chiều nay tôi sẽ gửi.","explanation":"Câu hỏi đuôi 'haven't you?' xác nhận việc đã gửi; (C) 'Not yet—I'm sending them this afternoon' phủ nhận khéo léo và nêu kế hoạch — chính xác. (B) 'Yes' hàm ý đã gửi nhưng lại nhận xét thư mời đẹp, không trả lời đúng trọng tâm. (A) nói về vị trí nhà cung cấp, không liên quan.","hintWords":["question","already","sent","invitation","vendors"],"keyVocab":[{"word":"invitation","meaning":"thư mời, lời mời"},{"word":"vendor","meaning":"nhà cung cấp, nhà bán hàng"},{"word":"not yet","meaning":"vẫn chưa"}],"practiceOptions":[{"key":"A","text":"The vendors are in the next building.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q026-a.mp3","keyVocab":[{"word":"vendor","meaning":"nhà cung cấp, nhà bán hàng"},{"word":"building","meaning":"tòa nhà"}]},{"key":"B","text":"Yes, the invitation was beautiful.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q026-b.mp3","keyVocab":[{"word":"invitation","meaning":"thư mời, lời mời"}]},{"key":"C","text":"Not yet—I'm sending them this afternoon.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q026-c.mp3","keyVocab":[{"word":"not yet","meaning":"vẫn chưa"},{"word":"afternoon","meaning":"buổi chiều"}]}]},{"id":"ets-orig-test-2-q27","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 27 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q027.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q027-q.mp3","questionScript":"Do we have enough cement for tomorrow's pour?","questionVi":"Chúng ta có đủ xi măng cho việc đổ bê tông ngày mai không?","questionVocab":[{"word":"cement","meaning":"xi măng"},{"word":"pour","meaning":"việc đổ (bê tông)"}],"audioText":"Do we have enough cement for tomorrow's pour? A. The pour was scheduled for 8 a.m. B. I'll check the inventory and let you know. C. The cement truck is yellow.","fullTranscript":"Question: Do we have enough cement for tomorrow's pour? (A) The pour was scheduled for 8 a.m. (B) I'll check the inventory and let you know. (C) The cement truck is yellow.","vietnamese":"Câu hỏi: Chúng ta có đủ xi măng cho việc đổ bê tông ngày mai không?\n(A) Việc đổ bê tông được lên lịch lúc 8 giờ sáng.\n(B) Tôi sẽ kiểm tra kho và báo lại anh/chị.\n(C) Xe tải xi măng màu vàng.","optionTranslations":"Câu hỏi: Chúng ta có đủ xi măng cho việc đổ bê tông ngày mai không?\n(A) Việc đổ bê tông được lên lịch lúc 8 giờ sáng.\n(B) Tôi sẽ kiểm tra kho và báo lại anh/chị.\n(C) Xe tải xi măng màu vàng.","explanation":"Câu hỏi Yes/No về số lượng vật tư; khi chưa chắc chắn, người trả lời thường nói sẽ kiểm tra rồi báo lại — (B) là phương án phù hợp nhất. (A) nói về giờ thi công, không trả lời việc có đủ xi măng. (C) nói về màu xe tải, hoàn toàn không liên quan.","hintWords":["question","have","enough","cement","tomorrow"],"keyVocab":[{"word":"cement","meaning":"xi măng"},{"word":"pour","meaning":"việc đổ (bê tông)"},{"word":"inventory","meaning":"hàng tồn kho, vật tư trong kho"},{"word":"schedule","meaning":"lên lịch"}],"practiceOptions":[{"key":"A","text":"The pour was scheduled for 8 a.m.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q027-a.mp3","keyVocab":[{"word":"pour","meaning":"việc đổ (bê tông)"},{"word":"schedule","meaning":"lên lịch"}]},{"key":"B","text":"I'll check the inventory and let you know.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q027-b.mp3","keyVocab":[{"word":"inventory","meaning":"hàng tồn kho, vật tư trong kho"}]},{"key":"C","text":"The cement truck is yellow.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q027-c.mp3","keyVocab":[{"word":"cement","meaning":"xi măng"},{"word":"truck","meaning":"xe tải"}]}]},{"id":"ets-orig-test-2-q28","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 28 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q028.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q028-q.mp3","questionScript":"Where should I drop off the rental car?","questionVi":"Tôi nên trả xe thuê ở đâu?","questionVocab":[{"word":"drop off","meaning":"trả (xe), để (ai đó) xuống"},{"word":"rental car","meaning":"xe cho thuê"}],"audioText":"Where should I drop off the rental car? A. At the airport return lot. B. Around three o'clock. C. The car was very comfortable.","fullTranscript":"Question: Where should I drop off the rental car? (A) At the airport return lot. (B) Around three o'clock. (C) The car was very comfortable.","vietnamese":"Câu hỏi: Tôi nên trả xe thuê ở đâu?\n(A) Ở bãi trả xe của sân bay.\n(B) Khoảng ba giờ.\n(C) Xe chạy rất thoải mái.","optionTranslations":"Câu hỏi: Tôi nên trả xe thuê ở đâu?\n(A) Ở bãi trả xe của sân bay.\n(B) Khoảng ba giờ.\n(C) Xe chạy rất thoải mái.","explanation":"'Where' hỏi địa điểm; (A) 'At the airport return lot' trả lời trực tiếp — chính xác. (B) là giờ giấc (trả lời 'When'), (C) là nhận xét về xe, cả hai đều không nêu địa điểm trả xe.","hintWords":["question","where","should","drop","rental"],"keyVocab":[{"word":"drop off","meaning":"trả (xe), để (ai đó) xuống"},{"word":"rental car","meaning":"xe cho thuê"},{"word":"return lot","meaning":"bãi trả xe"}],"practiceOptions":[{"key":"A","text":"At the airport return lot.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q028-a.mp3","keyVocab":[{"word":"return lot","meaning":"bãi trả xe"},{"word":"airport","meaning":"sân bay"}]},{"key":"B","text":"Around three o'clock.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q028-b.mp3","keyVocab":[{"word":"around","meaning":"khoảng, chừng"}]},{"key":"C","text":"The car was very comfortable.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q028-c.mp3","keyVocab":[{"word":"comfortable","meaning":"thoải mái"}]}]},{"id":"ets-orig-test-2-q29","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 29 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q029.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q029-q.mp3","questionScript":"Let's move the budget review to Thursday morning, shall we?","questionVi":"Chúng ta hãy dời buổi xem xét ngân sách sang sáng thứ Năm nhé?","questionVocab":[{"word":"budget review","meaning":"buổi xem xét ngân sách"},{"word":"move","meaning":"dời, thay đổi (lịch)"},{"word":"morning","meaning":"buổi sáng"},{"word":"Thursday","meaning":"thứ Năm"}],"audioText":"Let's move the budget review to Thursday morning, shall we? A. The budget is quite tight this year. B. That gives us more time to prepare. C. In the small meeting room.","fullTranscript":"Question: Let's move the budget review to Thursday morning, shall we? (A) The budget is quite tight this year. (B) That gives us more time to prepare. (C) In the small meeting room.","vietnamese":"Câu hỏi: Chúng ta hãy dời buổi xem xét ngân sách sang sáng thứ Năm nhé?\n(A) Ngân sách năm nay khá eo hẹp.\n(B) Như vậy sẽ cho chúng ta thêm thời gian chuẩn bị.\n(C) Ở phòng họp nhỏ.","optionTranslations":"Câu hỏi: Chúng ta hãy dời buổi xem xét ngân sách sang sáng thứ Năm nhé?\n(A) Ngân sách năm nay khá eo hẹp.\n(B) Như vậy sẽ cho chúng ta thêm thời gian chuẩn bị.\n(C) Ở phòng họp nhỏ.","explanation":"'Let's..., shall we?' là lời đề nghị cùng làm gì đó; (B) thể hiện sự đồng tình kèm lý do có lợi — phù hợp nhất. (A) nhận xét về ngân sách, không phản hồi đề nghị dời lịch. (C) trả lời 'Where', trong khi câu hỏi nói về thời điểm.","hintWords":["question","move","budget","review","thursday"],"keyVocab":[{"word":"budget review","meaning":"buổi xem xét ngân sách"},{"word":"tight","meaning":"eo hẹp, chặt"},{"word":"prepare","meaning":"chuẩn bị"}],"practiceOptions":[{"key":"A","text":"The budget is quite tight this year.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q029-a.mp3","keyVocab":[{"word":"tight","meaning":"eo hẹp, chặt"},{"word":"budget","meaning":"ngân sách"}]},{"key":"B","text":"That gives us more time to prepare.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q029-b.mp3","keyVocab":[{"word":"prepare","meaning":"chuẩn bị"}]},{"key":"C","text":"In the small meeting room.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q029-c.mp3","keyVocab":[{"word":"small","meaning":"nhỏ"}]}]},{"id":"ets-orig-test-2-q30","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 30 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q030.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q030-q.mp3","questionScript":"Has the finance team approved the extra funding for the project?","questionVi":"Bộ phận tài chính đã phê duyệt khoản tài trợ bổ sung cho dự án chưa?","questionVocab":[{"word":"funding","meaning":"nguồn tài trợ, kinh phí"},{"word":"approve","meaning":"phê duyệt"},{"word":"extra","meaning":"thêm, dư"}],"audioText":"Has the finance team approved the extra funding for the project? A. The project starts next quarter. B. Yes, the funding is in the third column. C. Not yet—they're reviewing the cost breakdown.","fullTranscript":"Question: Has the finance team approved the extra funding for the project? (A) The project starts next quarter. (B) Yes, the funding is in the third column. (C) Not yet—they're reviewing the cost breakdown.","vietnamese":"Câu hỏi: Bộ phận tài chính đã phê duyệt khoản tài trợ bổ sung cho dự án chưa?\n(A) Dự án bắt đầu vào quý sau.\n(B) Vâng, khoản tiền nằm ở cột thứ ba.\n(C) Chưa — họ đang xem xét bảng phân tích chi phí.","optionTranslations":"Câu hỏi: Bộ phận tài chính đã phê duyệt khoản tài trợ bổ sung cho dự án chưa?\n(A) Dự án bắt đầu vào quý sau.\n(B) Vâng, khoản tiền nằm ở cột thứ ba.\n(C) Chưa — họ đang xem xét bảng phân tích chi phí.","explanation":"Câu hỏi Yes/No ở thì hiện tại hoàn thành; (C) 'Not yet—they're reviewing...' trả lời phủ định kèm lý do đang xem xét — chính xác. (B) 'Yes' nhưng phần sau nói về vị trí trong bảng, không khẳng định việc phê duyệt. (A) nói về thời điểm dự án, không liên quan.","hintWords":["question","finance","team","approved","extra"],"keyVocab":[{"word":"funding","meaning":"nguồn tài trợ, kinh phí"},{"word":"approve","meaning":"phê duyệt"},{"word":"cost breakdown","meaning":"bảng phân tích chi phí"},{"word":"quarter","meaning":"quý (ba tháng)"}],"practiceOptions":[{"key":"A","text":"The project starts next quarter.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q030-a.mp3","keyVocab":[{"word":"quarter","meaning":"quý (ba tháng)"},{"word":"start","meaning":"bắt đầu"}]},{"key":"B","text":"Yes, the funding is in the third column.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q030-b.mp3","keyVocab":[{"word":"funding","meaning":"nguồn tài trợ, kinh phí"}]},{"key":"C","text":"Not yet—they're reviewing the cost breakdown.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q030-c.mp3","keyVocab":[{"word":"cost breakdown","meaning":"bảng phân tích chi phí"},{"word":"review","meaning":"xem lại, rà soát"},{"word":"not yet","meaning":"vẫn chưa"}]}]},{"id":"ets-orig-test-2-q31","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 2","partNumber":2,"level":"ETS Format","title":"Test 02 • Câu 31 (Part 2: Hỏi - Đáp (Question - Response))","questionPrompt":"Nghe một câu hỏi và 3 phương án trả lời, chọn câu phản hồi phù hợp nhất:","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p2-q031.mp3","questionAudioUrl":"listening/audio/lv1-test-02/p2-q031-q.mp3","questionScript":"What time does the orientation for new hires begin?","questionVi":"Buổi định hướng cho nhân viên mới bắt đầu lúc mấy giờ?","questionVocab":[{"word":"orientation","meaning":"buổi định hướng"},{"word":"new hire","meaning":"nhân viên mới"},{"word":"begin","meaning":"bắt đầu"}],"audioText":"What time does the orientation for new hires begin? A. At nine o'clock in the cafeteria. B. About twenty new hires. C. It lasted nearly two hours.","fullTranscript":"Question: What time does the orientation for new hires begin? (A) At nine o'clock in the cafeteria. (B) About twenty new hires. (C) It lasted nearly two hours.","vietnamese":"Câu hỏi: Buổi định hướng cho nhân viên mới bắt đầu lúc mấy giờ?\n(A) Lúc chín giờ, tại nhà ăn.\n(B) Khoảng hai mươi nhân viên mới.\n(C) Nó kéo dài gần hai tiếng.","optionTranslations":"Câu hỏi: Buổi định hướng cho nhân viên mới bắt đầu lúc mấy giờ?\n(A) Lúc chín giờ, tại nhà ăn.\n(B) Khoảng hai mươi nhân viên mới.\n(C) Nó kéo dài gần hai tiếng.","explanation":"'What time' hỏi giờ cụ thể; (A) 'At nine o'clock...' trả lời chính xác. (B) là số lượng người (trả lời 'How many'), (C) là thời lượng (trả lời 'How long'), không phải giờ bắt đầu.","hintWords":["question","what","time","does","orientation"],"keyVocab":[{"word":"orientation","meaning":"buổi định hướng"},{"word":"new hire","meaning":"nhân viên mới"},{"word":"cafeteria","meaning":"nhà ăn"},{"word":"last","meaning":"kéo dài"}],"practiceOptions":[{"key":"A","text":"At nine o'clock in the cafeteria.","correct":true,"audioUrl":"listening/audio/lv1-test-02/p2-q031-a.mp3","keyVocab":[{"word":"cafeteria","meaning":"nhà ăn"},{"word":"clock in","meaning":"chấm công vào ca làm"}]},{"key":"B","text":"About twenty new hires.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q031-b.mp3","keyVocab":[{"word":"new hire","meaning":"nhân viên mới"},{"word":"twenty","meaning":"hai mươi"}]},{"key":"C","text":"It lasted nearly two hours.","correct":false,"audioUrl":"listening/audio/lv1-test-02/p2-q031-c.mp3","keyVocab":[{"word":"last","meaning":"kéo dài"}]}]},{"id":"ets-orig-test-2-q32","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 32 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What problem does the man report?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g01.mp3","audioText":"Ms. Alvarez, the printer delivered the new loyalty cards this morning, but the design doesn't match the proof we approved.\nLet me see... You're right. The logo is gray instead of navy, and the tagline is missing.\nShould I send them back? We're supposed to start handing them out at the anniversary sale on Friday.\nReturning them would take at least a week. Call the printer and ask for a discount; we can use the cards as they are.\nWhat about the signs for the store windows? They have the correct logo.\nGood—put those up on Thursday evening. And ask the staff to mention the loyalty program at checkout.","fullTranscript":"Man: Ms. Alvarez, the printer delivered the new loyalty cards this morning, but the design doesn't match the proof we approved. Woman: Let me see... You're right. The logo is gray instead of navy, and the tagline is missing. Man: Should I send them back? We're supposed to start handing them out at the anniversary sale on Friday. Woman: Returning them would take at least a week. Call the printer and ask for a discount; we can use the cards as they are. Man: What about the signs for the store windows? They have the correct logo. Woman: Good—put those up on Thursday evening. And ask the staff to mention the loyalty program at checkout.","vietnamese":"Câu hỏi: Người đàn ông báo cáo vấn đề gì?\n(A) Buổi bán hàng kỷ niệm đã bị hoãn.\n(B) Thẻ khách hàng thân thiết được in sai.\n(C) Cửa sổ cửa hàng quá nhỏ so với biển hiệu.\n(D) Công ty in chưa giao đơn hàng.","optionTranslations":"Câu hỏi: Người đàn ông báo cáo vấn đề gì?\n(A) Buổi bán hàng kỷ niệm đã bị hoãn.\n(B) Thẻ khách hàng thân thiết được in sai.\n(C) Cửa sổ cửa hàng quá nhỏ so với biển hiệu.\n(D) Công ty in chưa giao đơn hàng.","explanation":"Đáp án đúng: B. Người đàn ông nói: “the design doesn't match the proof we approved”, sau đó người phụ nữ xác nhận logo sai màu và thiếu khẩu hiệu. Thẻ đã được giao nên D sai; buổi bán vẫn diễn ra vào thứ Sáu nên A sai; biển hiệu có logo đúng và không có vấn đề kích thước nên C sai.","hintWords":["alvarez","printer","delivered","loyalty","cards"],"keyVocab":[{"word":"loyalty card","meaning":"thẻ khách hàng thân thiết"},{"word":"proof","meaning":"bản in duyệt thử"},{"word":"tagline","meaning":"khẩu hiệu"}],"practiceOptions":[{"key":"A","text":"The anniversary sale has been postponed.","correct":false},{"key":"B","text":"The loyalty cards were printed incorrectly.","correct":true},{"key":"C","text":"The store windows are too small for the signs.","correct":false},{"key":"D","text":"The printer has not delivered the order.","correct":false}]},{"id":"ets-orig-test-2-q33","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 33 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What does the woman suggest doing?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g01.mp3","audioText":"Ms. Alvarez, the printer delivered the new loyalty cards this morning, but the design doesn't match the proof we approved.\nLet me see... You're right. The logo is gray instead of navy, and the tagline is missing.\nShould I send them back? We're supposed to start handing them out at the anniversary sale on Friday.\nReturning them would take at least a week. Call the printer and ask for a discount; we can use the cards as they are.\nWhat about the signs for the store windows? They have the correct logo.\nGood—put those up on Thursday evening. And ask the staff to mention the loyalty program at checkout.","fullTranscript":"Man: Ms. Alvarez, the printer delivered the new loyalty cards this morning, but the design doesn't match the proof we approved. Woman: Let me see... You're right. The logo is gray instead of navy, and the tagline is missing. Man: Should I send them back? We're supposed to start handing them out at the anniversary sale on Friday. Woman: Returning them would take at least a week. Call the printer and ask for a discount; we can use the cards as they are. Man: What about the signs for the store windows? They have the correct logo. Woman: Good—put those up on Thursday evening. And ask the staff to mention the loyalty program at checkout.","vietnamese":"Câu hỏi: Người phụ nữ đề nghị làm gì?\n(A) Giữ lại thẻ và yêu cầu giảm giá\n(B) Trả thẻ lại cho công ty in\n(C) Hoãn buổi bán hàng kỷ niệm\n(D) Đặt một lô biển hiệu mới","optionTranslations":"Câu hỏi: Người phụ nữ đề nghị làm gì?\n(A) Giữ lại thẻ và yêu cầu giảm giá\n(B) Trả thẻ lại cho công ty in\n(C) Hoãn buổi bán hàng kỷ niệm\n(D) Đặt một lô biển hiệu mới","explanation":"Đáp án đúng: A. Người phụ nữ nói: “Call the printer and ask for a discount; we can use the cards as they are.” Cô ấy từ chối trả lại vì mất ít nhất một tuần nên B sai; không có ý định hoãn buổi bán nên C sai; biển hiệu đã có logo đúng nên không cần đặt mới, D sai.","hintWords":["alvarez","printer","delivered","loyalty","cards"],"keyVocab":[{"word":"discount","meaning":"khoản giảm giá"},{"word":"return","meaning":"trả lại"},{"word":"hand out","meaning":"phát ra, phân phát"}],"practiceOptions":[{"key":"A","text":"Keeping the cards and asking for a discount","correct":true},{"key":"B","text":"Returning the cards to the printer","correct":false},{"key":"C","text":"Delaying the anniversary sale","correct":false},{"key":"D","text":"Ordering a new batch of signs","correct":false}]},{"id":"ets-orig-test-2-q34","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 34 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"When will the signs be put up?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g01.mp3","audioText":"Ms. Alvarez, the printer delivered the new loyalty cards this morning, but the design doesn't match the proof we approved.\nLet me see... You're right. The logo is gray instead of navy, and the tagline is missing.\nShould I send them back? We're supposed to start handing them out at the anniversary sale on Friday.\nReturning them would take at least a week. Call the printer and ask for a discount; we can use the cards as they are.\nWhat about the signs for the store windows? They have the correct logo.\nGood—put those up on Thursday evening. And ask the staff to mention the loyalty program at checkout.","fullTranscript":"Man: Ms. Alvarez, the printer delivered the new loyalty cards this morning, but the design doesn't match the proof we approved. Woman: Let me see... You're right. The logo is gray instead of navy, and the tagline is missing. Man: Should I send them back? We're supposed to start handing them out at the anniversary sale on Friday. Woman: Returning them would take at least a week. Call the printer and ask for a discount; we can use the cards as they are. Man: What about the signs for the store windows? They have the correct logo. Woman: Good—put those up on Thursday evening. And ask the staff to mention the loyalty program at checkout.","vietnamese":"Câu hỏi: Khi nào biển hiệu sẽ được treo lên?\n(A) Sáng thứ Sáu\n(B) Chiều thứ Bảy\n(C) Tối thứ Tư\n(D) Tối thứ Năm","optionTranslations":"Câu hỏi: Khi nào biển hiệu sẽ được treo lên?\n(A) Sáng thứ Sáu\n(B) Chiều thứ Bảy\n(C) Tối thứ Tư\n(D) Tối thứ Năm","explanation":"Đáp án đúng: D. Người phụ nữ nói: “put those up on Thursday evening”; “those” chỉ các biển hiệu cho cửa sổ cửa hàng vừa được nhắc đến. Thứ Sáu là ngày bắt đầu phát thẻ, không phải ngày treo biển, nên A sai; B và C không được nhắc đến.","hintWords":["alvarez","printer","delivered","loyalty","cards"],"keyVocab":[{"word":"put up","meaning":"treo lên"},{"word":"checkout","meaning":"quầy thanh toán"},{"word":"mention","meaning":"nhắc đến"}],"practiceOptions":[{"key":"A","text":"Friday morning","correct":false},{"key":"B","text":"Saturday afternoon","correct":false},{"key":"C","text":"Wednesday evening","correct":false},{"key":"D","text":"Thursday evening","correct":true}]},{"id":"ets-orig-test-2-q35","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 35 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What is the main reason the budget is over the agreed amount?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g02.mp3","audioText":"Daniel, have you finished reviewing the marketing budget for next quarter?\nAlmost. The total is about 8 percent over what we agreed on, mostly because of the trade show in Chicago.\nI thought the trade show fee was already included in the original estimate.\nIt was, but we added two extra booth staff and a larger display. Those costs weren't in the first draft.\nCan we reduce the travel budget instead? We could book economy seats and take the early train.\nWe could, but the sales team needs to arrive the night before. The earliest train gets in at ten.\nThen let's cut the printed brochures. A digital catalog would save us nearly three thousand dollars.\nThat works. I'll update the spreadsheet and send it to you before noon.","fullTranscript":"Woman: Daniel, have you finished reviewing the marketing budget for next quarter? Man: Almost. The total is about 8 percent over what we agreed on, mostly because of the trade show in Chicago. Woman: I thought the trade show fee was already included in the original estimate. Man: It was, but we added two extra booth staff and a larger display. Those costs weren't in the first draft. Woman: Can we reduce the travel budget instead? We could book economy seats and take the early train. Man: We could, but the sales team needs to arrive the night before. The earliest train gets in at ten. Woman: Then let's cut the printed brochures. A digital catalog would save us nearly three thousand dollars. Man: That works. I'll update the spreadsheet and send it to you before noon.","vietnamese":"Câu hỏi: Lý do chính khiến ngân sách vượt mức đã thống nhất là gì?\n(A) Phí hội chợ thương mại đã tăng.\n(B) Nhóm bán hàng đã đặt chuyến bay muộn.\n(C) Đã bổ sung thêm nhân viên gian hàng và một màn trưng bày lớn hơn.\n(D) Brochure in giấy tốn kém hơn dự kiến.","optionTranslations":"Câu hỏi: Lý do chính khiến ngân sách vượt mức đã thống nhất là gì?\n(A) Phí hội chợ thương mại đã tăng.\n(B) Nhóm bán hàng đã đặt chuyến bay muộn.\n(C) Đã bổ sung thêm nhân viên gian hàng và một màn trưng bày lớn hơn.\n(D) Brochure in giấy tốn kém hơn dự kiến.","explanation":"Đáp án đúng: C. Người đàn ông giải thích: “we added two extra booth staff and a larger display. Those costs weren't in the first draft.” Phí hội chợ đã nằm trong dự toán ban đầu nên A sai; chưa có việc đặt vé máy bay muộn nên B sai; brochure in giấy mới chỉ là khoản đang cân nhắc cắt, chưa phải nguyên nhân vượt ngân sách, nên D sai.","hintWords":["woman","daniel","have","finished","reviewing"],"keyVocab":[{"word":"budget","meaning":"ngân sách"},{"word":"estimate","meaning":"dự toán"},{"word":"booth","meaning":"gian hàng"},{"word":"display","meaning":"màn trưng bày"}],"practiceOptions":[{"key":"A","text":"The trade show fee was raised.","correct":false},{"key":"B","text":"The sales team booked late flights.","correct":false},{"key":"C","text":"Extra booth staff and a larger display were added.","correct":true},{"key":"D","text":"The printed brochures cost more than expected.","correct":false}]},{"id":"ets-orig-test-2-q36","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 36 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What does the woman propose?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g02.mp3","audioText":"Daniel, have you finished reviewing the marketing budget for next quarter?\nAlmost. The total is about 8 percent over what we agreed on, mostly because of the trade show in Chicago.\nI thought the trade show fee was already included in the original estimate.\nIt was, but we added two extra booth staff and a larger display. Those costs weren't in the first draft.\nCan we reduce the travel budget instead? We could book economy seats and take the early train.\nWe could, but the sales team needs to arrive the night before. The earliest train gets in at ten.\nThen let's cut the printed brochures. A digital catalog would save us nearly three thousand dollars.\nThat works. I'll update the spreadsheet and send it to you before noon.","fullTranscript":"Woman: Daniel, have you finished reviewing the marketing budget for next quarter? Man: Almost. The total is about 8 percent over what we agreed on, mostly because of the trade show in Chicago. Woman: I thought the trade show fee was already included in the original estimate. Man: It was, but we added two extra booth staff and a larger display. Those costs weren't in the first draft. Woman: Can we reduce the travel budget instead? We could book economy seats and take the early train. Man: We could, but the sales team needs to arrive the night before. The earliest train gets in at ten. Woman: Then let's cut the printed brochures. A digital catalog would save us nearly three thousand dollars. Man: That works. I'll update the spreadsheet and send it to you before noon.","vietnamese":"Câu hỏi: Người phụ nữ đề xuất điều gì?\n(A) Đi chuyến tàu sớm hơn\n(B) Thay brochure in giấy bằng danh mục kỹ thuật số\n(C) Hủy hội chợ thương mại\n(D) Thuê ít nhân viên gian hàng hơn","optionTranslations":"Câu hỏi: Người phụ nữ đề xuất điều gì?\n(A) Đi chuyến tàu sớm hơn\n(B) Thay brochure in giấy bằng danh mục kỹ thuật số\n(C) Hủy hội chợ thương mại\n(D) Thuê ít nhân viên gian hàng hơn","explanation":"Đáp án đúng: B. Người phụ nữ nói: “let's cut the printed brochures. A digital catalog would save us nearly three thousand dollars.” Chuyến tàu sớm từng được nêu nhưng bị loại vì đội bán hàng cần đến từ đêm trước, nên A sai; không ai đề nghị hủy hội chợ hay giảm nhân viên, nên C và D sai.","hintWords":["woman","daniel","have","finished","reviewing"],"keyVocab":[{"word":"digital catalog","meaning":"danh mục kỹ thuật số"},{"word":"brochure","meaning":"tài liệu quảng cáo"},{"word":"propose","meaning":"đề xuất"},{"word":"cut","meaning":"cắt giảm"}],"practiceOptions":[{"key":"A","text":"Taking an earlier train","correct":false},{"key":"B","text":"Replacing printed brochures with a digital catalog","correct":true},{"key":"C","text":"Canceling the trade show","correct":false},{"key":"D","text":"Hiring fewer booth staff","correct":false}]},{"id":"ets-orig-test-2-q37","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 37 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"When will the man send the updated spreadsheet?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g02.mp3","audioText":"Daniel, have you finished reviewing the marketing budget for next quarter?\nAlmost. The total is about 8 percent over what we agreed on, mostly because of the trade show in Chicago.\nI thought the trade show fee was already included in the original estimate.\nIt was, but we added two extra booth staff and a larger display. Those costs weren't in the first draft.\nCan we reduce the travel budget instead? We could book economy seats and take the early train.\nWe could, but the sales team needs to arrive the night before. The earliest train gets in at ten.\nThen let's cut the printed brochures. A digital catalog would save us nearly three thousand dollars.\nThat works. I'll update the spreadsheet and send it to you before noon.","fullTranscript":"Woman: Daniel, have you finished reviewing the marketing budget for next quarter? Man: Almost. The total is about 8 percent over what we agreed on, mostly because of the trade show in Chicago. Woman: I thought the trade show fee was already included in the original estimate. Man: It was, but we added two extra booth staff and a larger display. Those costs weren't in the first draft. Woman: Can we reduce the travel budget instead? We could book economy seats and take the early train. Man: We could, but the sales team needs to arrive the night before. The earliest train gets in at ten. Woman: Then let's cut the printed brochures. A digital catalog would save us nearly three thousand dollars. Man: That works. I'll update the spreadsheet and send it to you before noon.","vietnamese":"Câu hỏi: Khi nào người đàn ông sẽ gửi bảng tính đã cập nhật?\n(A) Trước buổi trưa\n(B) Trước cuối tuần\n(C) Sáng mai\n(D) Sau hội chợ thương mại","optionTranslations":"Câu hỏi: Khi nào người đàn ông sẽ gửi bảng tính đã cập nhật?\n(A) Trước buổi trưa\n(B) Trước cuối tuần\n(C) Sáng mai\n(D) Sau hội chợ thương mại","explanation":"Đáp án đúng: A. Người đàn ông nói: “I'll update the spreadsheet and send it to you before noon.” Các mốc cuối tuần, sáng mai và sau hội chợ đều không được nhắc đến trong hội thoại.","hintWords":["woman","daniel","have","finished","reviewing"],"keyVocab":[{"word":"spreadsheet","meaning":"bảng tính"},{"word":"update","meaning":"cập nhật"},{"word":"noon","meaning":"buổi trưa"}],"practiceOptions":[{"key":"A","text":"Before noon","correct":true},{"key":"B","text":"By the end of the week","correct":false},{"key":"C","text":"Tomorrow morning","correct":false},{"key":"D","text":"After the trade show","correct":false}]},{"id":"ets-orig-test-2-q38","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 38 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What problem does the man have?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g03.mp3","audioText":"Hello, I'm calling about the reservation for the Latham Group. We booked twelve rooms for the conference next month.\nYes, I see the booking. You're arriving on the fourteenth and checking out on the seventeenth.\nThat's right. But our flight was moved, so four of us will now arrive a day early. Do you have rooms available on the thirteenth?\nWe're nearly full that night because of a wedding. I can offer two suites and one double, but not twelve singles.\nHmm, that might be awkward. Is there another hotel nearby that could take the rest?\nThe Parkview Inn is a five-minute walk away. I can call them and arrange a shuttle for your group.\nPlease do. And could you send the updated confirmation to my assistant?\nCertainly. I'll email it this afternoon.","fullTranscript":"Man: Hello, I'm calling about the reservation for the Latham Group. We booked twelve rooms for the conference next month. Woman: Yes, I see the booking. You're arriving on the fourteenth and checking out on the seventeenth. Man: That's right. But our flight was moved, so four of us will now arrive a day early. Do you have rooms available on the thirteenth? Woman: We're nearly full that night because of a wedding. I can offer two suites and one double, but not twelve singles. Man: Hmm, that might be awkward. Is there another hotel nearby that could take the rest? Woman: The Parkview Inn is a five-minute walk away. I can call them and arrange a shuttle for your group. Man: Please do. And could you send the updated confirmation to my assistant? Woman: Certainly. I'll email it this afternoon.","vietnamese":"Câu hỏi: Người đàn ông gặp vấn đề gì?\n(A) Chuyến bay của ông ấy đã bị hủy.\n(B) Khách sạn đã làm mất đặt phòng của ông ấy.\n(C) Hội nghị đã được dời sang ngày khác.\n(D) Bốn đồng nghiệp sẽ đến sớm hơn kế hoạch một ngày.","optionTranslations":"Câu hỏi: Người đàn ông gặp vấn đề gì?\n(A) Chuyến bay của ông ấy đã bị hủy.\n(B) Khách sạn đã làm mất đặt phòng của ông ấy.\n(C) Hội nghị đã được dời sang ngày khác.\n(D) Bốn đồng nghiệp sẽ đến sớm hơn kế hoạch một ngày.","explanation":"Đáp án đúng: D. Người đàn ông nói: “our flight was moved, so four of us will now arrive a day early.” Chuyến bay bị dời giờ chứ không bị hủy nên A sai; khách sạn vẫn thấy đặt phòng nên B sai; hội nghị vẫn diễn ra vào tháng sau nên C sai.","hintWords":["hello","calling","about","reservation","latham"],"keyVocab":[{"word":"reservation","meaning":"đặt phòng"},{"word":"check out","meaning":"trả phòng"},{"word":"suite","meaning":"phòng hạng sang"},{"word":"shuttle","meaning":"xe đưa đón"}],"practiceOptions":[{"key":"A","text":"His flight has been canceled.","correct":false},{"key":"B","text":"The hotel has lost his reservation.","correct":false},{"key":"C","text":"The conference has been moved to another date.","correct":false},{"key":"D","text":"Four colleagues will arrive a day earlier than planned.","correct":true}]},{"id":"ets-orig-test-2-q39","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 39 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What does the woman offer to do?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g03.mp3","audioText":"Hello, I'm calling about the reservation for the Latham Group. We booked twelve rooms for the conference next month.\nYes, I see the booking. You're arriving on the fourteenth and checking out on the seventeenth.\nThat's right. But our flight was moved, so four of us will now arrive a day early. Do you have rooms available on the thirteenth?\nWe're nearly full that night because of a wedding. I can offer two suites and one double, but not twelve singles.\nHmm, that might be awkward. Is there another hotel nearby that could take the rest?\nThe Parkview Inn is a five-minute walk away. I can call them and arrange a shuttle for your group.\nPlease do. And could you send the updated confirmation to my assistant?\nCertainly. I'll email it this afternoon.","fullTranscript":"Man: Hello, I'm calling about the reservation for the Latham Group. We booked twelve rooms for the conference next month. Woman: Yes, I see the booking. You're arriving on the fourteenth and checking out on the seventeenth. Man: That's right. But our flight was moved, so four of us will now arrive a day early. Do you have rooms available on the thirteenth? Woman: We're nearly full that night because of a wedding. I can offer two suites and one double, but not twelve singles. Man: Hmm, that might be awkward. Is there another hotel nearby that could take the rest? Woman: The Parkview Inn is a five-minute walk away. I can call them and arrange a shuttle for your group. Man: Please do. And could you send the updated confirmation to my assistant? Woman: Certainly. I'll email it this afternoon.","vietnamese":"Câu hỏi: Người phụ nữ đề nghị làm gì?\n(A) Nâng cấp cả mười hai phòng\n(B) Hủy đặt phòng của tiệc cưới\n(C) Liên hệ khách sạn khác và thu xếp xe đưa đón\n(D) Đổi ngày trả phòng của đoàn","optionTranslations":"Câu hỏi: Người phụ nữ đề nghị làm gì?\n(A) Nâng cấp cả mười hai phòng\n(B) Hủy đặt phòng của tiệc cưới\n(C) Liên hệ khách sạn khác và thu xếp xe đưa đón\n(D) Đổi ngày trả phòng của đoàn","explanation":"Đáp án đúng: C. Người phụ nữ nói: “The Parkview Inn is a five-minute walk away. I can call them and arrange a shuttle for your group.” Cô ấy chỉ có hai phòng suite và một phòng đôi, không thể nâng cấp cả mười hai phòng, nên A sai; cô ấy không hủy tiệc cưới và ngày trả phòng vẫn là ngày mười bảy, nên B và D sai.","hintWords":["hello","calling","about","reservation","latham"],"keyVocab":[{"word":"upgrade","meaning":"nâng cấp"},{"word":"arrange","meaning":"thu xếp"},{"word":"availability","meaning":"khả năng còn phòng"}],"practiceOptions":[{"key":"A","text":"Upgrade all twelve rooms","correct":false},{"key":"B","text":"Cancel the wedding booking","correct":false},{"key":"C","text":"Contact another hotel and arrange a shuttle","correct":true},{"key":"D","text":"Change the group's check-out date","correct":false}]},{"id":"ets-orig-test-2-q40","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 40 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"How will the woman send the confirmation?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g03.mp3","audioText":"Hello, I'm calling about the reservation for the Latham Group. We booked twelve rooms for the conference next month.\nYes, I see the booking. You're arriving on the fourteenth and checking out on the seventeenth.\nThat's right. But our flight was moved, so four of us will now arrive a day early. Do you have rooms available on the thirteenth?\nWe're nearly full that night because of a wedding. I can offer two suites and one double, but not twelve singles.\nHmm, that might be awkward. Is there another hotel nearby that could take the rest?\nThe Parkview Inn is a five-minute walk away. I can call them and arrange a shuttle for your group.\nPlease do. And could you send the updated confirmation to my assistant?\nCertainly. I'll email it this afternoon.","fullTranscript":"Man: Hello, I'm calling about the reservation for the Latham Group. We booked twelve rooms for the conference next month. Woman: Yes, I see the booking. You're arriving on the fourteenth and checking out on the seventeenth. Man: That's right. But our flight was moved, so four of us will now arrive a day early. Do you have rooms available on the thirteenth? Woman: We're nearly full that night because of a wedding. I can offer two suites and one double, but not twelve singles. Man: Hmm, that might be awkward. Is there another hotel nearby that could take the rest? Woman: The Parkview Inn is a five-minute walk away. I can call them and arrange a shuttle for your group. Man: Please do. And could you send the updated confirmation to my assistant? Woman: Certainly. I'll email it this afternoon.","vietnamese":"Câu hỏi: Người phụ nữ sẽ gửi xác nhận bằng cách nào?\n(A) Bằng fax\n(B) Bằng email\n(C) Bằng tin nhắn văn bản\n(D) Bằng thư","optionTranslations":"Câu hỏi: Người phụ nữ sẽ gửi xác nhận bằng cách nào?\n(A) Bằng fax\n(B) Bằng email\n(C) Bằng tin nhắn văn bản\n(D) Bằng thư","explanation":"Đáp án đúng: B. Người phụ nữ đáp: “Certainly. I'll email it this afternoon.” Fax, tin nhắn và thư đều không được nhắc đến.","hintWords":["hello","calling","about","reservation","latham"],"keyVocab":[{"word":"confirmation","meaning":"xác nhận"},{"word":"assistant","meaning":"trợ lý"},{"word":"afternoon","meaning":"buổi chiều"}],"practiceOptions":[{"key":"A","text":"By fax","correct":false},{"key":"B","text":"By email","correct":true},{"key":"C","text":"By text message","correct":false},{"key":"D","text":"By mail","correct":false}]},{"id":"ets-orig-test-2-q41","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 41 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What concern do employees have about the user guide?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g04.mp3","audioText":"How did the first training session on the new inventory system go?\nBetter than I expected, but several people said the user guide is too technical.\nI was afraid of that. The vendor wrote it for IT staff, not for warehouse employees.\nCould we record a short video that shows the most common tasks? That might be more useful than another meeting.\nI like that idea. You could film it in the training room tomorrow morning.\nI'll need a microphone. The room's built-in one picks up too much background noise.\nI'll borrow one from the media department and leave it at the front desk this afternoon.\nThanks. I'll send the draft to you by Friday so we can review it before the next session.","fullTranscript":"Woman: How did the first training session on the new inventory system go? Man: Better than I expected, but several people said the user guide is too technical. Woman: I was afraid of that. The vendor wrote it for IT staff, not for warehouse employees. Man: Could we record a short video that shows the most common tasks? That might be more useful than another meeting. Woman: I like that idea. You could film it in the training room tomorrow morning. Man: I'll need a microphone. The room's built-in one picks up too much background noise. Woman: I'll borrow one from the media department and leave it at the front desk this afternoon. Man: Thanks. I'll send the draft to you by Friday so we can review it before the next session.","vietnamese":"Câu hỏi: Nhân viên có lo ngại gì về tài liệu hướng dẫn sử dụng?\n(A) Nó quá chuyên môn.\n(B) Nó quá dài.\n(C) Nó thiếu hình ảnh.\n(D) Nó đã lỗi thời.","optionTranslations":"Câu hỏi: Nhân viên có lo ngại gì về tài liệu hướng dẫn sử dụng?\n(A) Nó quá chuyên môn.\n(B) Nó quá dài.\n(C) Nó thiếu hình ảnh.\n(D) Nó đã lỗi thời.","explanation":"Đáp án đúng: A. Người đàn ông cho biết: “several people said the user guide is too technical”, và người phụ nữ giải thích nhà cung cấp viết tài liệu cho nhân viên IT. Không có ý kiến nào nói tài liệu quá dài, thiếu hình hay lỗi thời, nên B, C, D sai.","hintWords":["woman","first","training","session","inventory"],"keyVocab":[{"word":"technical","meaning":"mang tính chuyên môn"},{"word":"user guide","meaning":"tài liệu hướng dẫn sử dụng"},{"word":"session","meaning":"buổi học"},{"word":"inventory system","meaning":"hệ thống kiểm kê"}],"practiceOptions":[{"key":"A","text":"It is too technical.","correct":true},{"key":"B","text":"It is too long.","correct":false},{"key":"C","text":"It lacks pictures.","correct":false},{"key":"D","text":"It is out of date.","correct":false}]},{"id":"ets-orig-test-2-q42","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 42 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What does the man suggest?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g04.mp3","audioText":"How did the first training session on the new inventory system go?\nBetter than I expected, but several people said the user guide is too technical.\nI was afraid of that. The vendor wrote it for IT staff, not for warehouse employees.\nCould we record a short video that shows the most common tasks? That might be more useful than another meeting.\nI like that idea. You could film it in the training room tomorrow morning.\nI'll need a microphone. The room's built-in one picks up too much background noise.\nI'll borrow one from the media department and leave it at the front desk this afternoon.\nThanks. I'll send the draft to you by Friday so we can review it before the next session.","fullTranscript":"Woman: How did the first training session on the new inventory system go? Man: Better than I expected, but several people said the user guide is too technical. Woman: I was afraid of that. The vendor wrote it for IT staff, not for warehouse employees. Man: Could we record a short video that shows the most common tasks? That might be more useful than another meeting. Woman: I like that idea. You could film it in the training room tomorrow morning. Man: I'll need a microphone. The room's built-in one picks up too much background noise. Woman: I'll borrow one from the media department and leave it at the front desk this afternoon. Man: Thanks. I'll send the draft to you by Friday so we can review it before the next session.","vietnamese":"Câu hỏi: Người đàn ông đề xuất điều gì?\n(A) Thuê nhà cung cấp tổ chức thêm một buổi\n(B) Chuyển buổi đào tạo sang phòng lớn hơn\n(C) In một tài liệu hướng dẫn ngắn hơn\n(D) Quay video về các tác vụ thường gặp","optionTranslations":"Câu hỏi: Người đàn ông đề xuất điều gì?\n(A) Thuê nhà cung cấp tổ chức thêm một buổi\n(B) Chuyển buổi đào tạo sang phòng lớn hơn\n(C) In một tài liệu hướng dẫn ngắn hơn\n(D) Quay video về các tác vụ thường gặp","explanation":"Đáp án đúng: D. Người đàn ông nói: “Could we record a short video that shows the most common tasks?” Anh ấy muốn video thay cho một cuộc họp nữa. Không có đề xuất thuê nhà cung cấp, đổi phòng hay in tài liệu ngắn hơn, nên A, B, C sai.","hintWords":["woman","first","training","session","inventory"],"keyVocab":[{"word":"record","meaning":"quay, ghi lại"},{"word":"common","meaning":"thường gặp"},{"word":"draft","meaning":"bản nháp"}],"practiceOptions":[{"key":"A","text":"Hiring the vendor for another session","correct":false},{"key":"B","text":"Moving the training to a larger room","correct":false},{"key":"C","text":"Printing a shorter guide","correct":false},{"key":"D","text":"Recording a video of common tasks","correct":true}]},{"id":"ets-orig-test-2-q43","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 43 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What will the woman provide?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g04.mp3","audioText":"How did the first training session on the new inventory system go?\nBetter than I expected, but several people said the user guide is too technical.\nI was afraid of that. The vendor wrote it for IT staff, not for warehouse employees.\nCould we record a short video that shows the most common tasks? That might be more useful than another meeting.\nI like that idea. You could film it in the training room tomorrow morning.\nI'll need a microphone. The room's built-in one picks up too much background noise.\nI'll borrow one from the media department and leave it at the front desk this afternoon.\nThanks. I'll send the draft to you by Friday so we can review it before the next session.","fullTranscript":"Woman: How did the first training session on the new inventory system go? Man: Better than I expected, but several people said the user guide is too technical. Woman: I was afraid of that. The vendor wrote it for IT staff, not for warehouse employees. Man: Could we record a short video that shows the most common tasks? That might be more useful than another meeting. Woman: I like that idea. You could film it in the training room tomorrow morning. Man: I'll need a microphone. The room's built-in one picks up too much background noise. Woman: I'll borrow one from the media department and leave it at the front desk this afternoon. Man: Thanks. I'll send the draft to you by Friday so we can review it before the next session.","vietnamese":"Câu hỏi: Người phụ nữ sẽ cung cấp gì?\n(A) Một máy tính mới\n(B) Một danh sách nhân viên\n(C) Một chiếc micro\n(D) Một bản hướng dẫn của nhà cung cấp","optionTranslations":"Câu hỏi: Người phụ nữ sẽ cung cấp gì?\n(A) Một máy tính mới\n(B) Một danh sách nhân viên\n(C) Một chiếc micro\n(D) Một bản hướng dẫn của nhà cung cấp","explanation":"Đáp án đúng: C. Sau khi người đàn ông nói cần micro, người phụ nữ đáp: “I'll borrow one from the media department and leave it at the front desk this afternoon.” “One” chính là chiếc micro. Không có máy tính, danh sách nhân viên hay bản hướng dẫn nào được nhắc đến, nên A, B, D sai.","hintWords":["woman","first","training","session","inventory"],"keyVocab":[{"word":"microphone","meaning":"micro"},{"word":"built-in","meaning":"gắn sẵn"},{"word":"background noise","meaning":"tiếng ồn xung quanh"}],"practiceOptions":[{"key":"A","text":"A new computer","correct":false},{"key":"B","text":"A list of employees","correct":false},{"key":"C","text":"A microphone","correct":true},{"key":"D","text":"A copy of the vendor's manual","correct":false}]},{"id":"ets-orig-test-2-q44","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 44 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"Why can't the crew pour the foundation?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g05.mp3","audioText":"Ms. Chen, the crew can't pour the foundation at the Riverside site tomorrow. Why not? The weather forecast is clear. The city inspector hasn't approved the revised drainage plan. Without that approval, we're not allowed to continue. I thought the revision was submitted last week. It was, but the inspector's office says one page is missing—the map showing the new pipe route. I have that map on my laptop. I'll email it to them right away and ask for an expedited review. That would help. If we don't start by Monday, the steel delivery will arrive before we have anywhere to store it. Then let's also ask the supplier to hold the delivery for three days. I will call the steel supplier this morning and confirm the revised delivery window. Thanks. Please copy me on the confirmation e-mail.","fullTranscript":"Man: Ms. Chen, the crew can't pour the foundation at the Riverside site tomorrow. Woman: Why not? The weather forecast is clear. Man: The city inspector hasn't approved the revised drainage plan. Without that approval, we're not allowed to continue. Woman: I thought the revision was submitted last week. Man: It was, but the inspector's office says one page is missing—the map showing the new pipe route. Woman: I have that map on my laptop. I'll email it to them right away and ask for an expedited review. Man: That would help. If we don't start by Monday, the steel delivery will arrive before we have anywhere to store it. Woman: Then let's also ask the supplier to hold the delivery for three days. Man 2: I will call the steel supplier this morning and confirm the revised delivery window. Woman: Thanks. Please copy me on the confirmation e-mail.","vietnamese":"Câu hỏi: Tại sao đội thi công không thể đổ móng?\n(A) Dự báo thời tiết xấu.\n(B) Một bản kế hoạch sửa đổi chưa được phê duyệt.\n(C) Đơn giao thép bị chậm.\n(D) Đội thi công đang làm ở một công trường khác.","optionTranslations":"Câu hỏi: Tại sao đội thi công không thể đổ móng?\n(A) Dự báo thời tiết xấu.\n(B) Một bản kế hoạch sửa đổi chưa được phê duyệt.\n(C) Đơn giao thép bị chậm.\n(D) Đội thi công đang làm ở một công trường khác.","explanation":"Đáp án đúng: B. Người đàn ông nói: “The city inspector hasn't approved the revised drainage plan. Without that approval, we're not allowed to continue.” Dự báo thời tiết đẹp nên A sai; thép sẽ đến nếu không khởi công kịp, nhưng chưa bị chậm, nên C sai; không có thông tin đội đang ở công trường khác, nên D sai.","hintWords":["chen","crew","pour","foundation","riverside"],"keyVocab":[{"word":"foundation","meaning":"móng công trình"},{"word":"crew","meaning":"đội thi công"},{"word":"inspector","meaning":"thanh tra viên"},{"word":"approval","meaning":"sự phê duyệt"}],"practiceOptions":[{"key":"A","text":"Bad weather is expected.","correct":false},{"key":"B","text":"A revised plan has not been approved.","correct":true},{"key":"C","text":"The steel delivery is late.","correct":false},{"key":"D","text":"The crew is working at another site.","correct":false}]},{"id":"ets-orig-test-2-q45","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 45 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What is missing from the submission?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g05.mp3","audioText":"Ms. Chen, the crew can't pour the foundation at the Riverside site tomorrow. Why not? The weather forecast is clear. The city inspector hasn't approved the revised drainage plan. Without that approval, we're not allowed to continue. I thought the revision was submitted last week. It was, but the inspector's office says one page is missing—the map showing the new pipe route. I have that map on my laptop. I'll email it to them right away and ask for an expedited review. That would help. If we don't start by Monday, the steel delivery will arrive before we have anywhere to store it. Then let's also ask the supplier to hold the delivery for three days. I will call the steel supplier this morning and confirm the revised delivery window. Thanks. Please copy me on the confirmation e-mail.","fullTranscript":"Man: Ms. Chen, the crew can't pour the foundation at the Riverside site tomorrow. Woman: Why not? The weather forecast is clear. Man: The city inspector hasn't approved the revised drainage plan. Without that approval, we're not allowed to continue. Woman: I thought the revision was submitted last week. Man: It was, but the inspector's office says one page is missing—the map showing the new pipe route. Woman: I have that map on my laptop. I'll email it to them right away and ask for an expedited review. Man: That would help. If we don't start by Monday, the steel delivery will arrive before we have anywhere to store it. Woman: Then let's also ask the supplier to hold the delivery for three days. Man 2: I will call the steel supplier this morning and confirm the revised delivery window. Woman: Thanks. Please copy me on the confirmation e-mail.","vietnamese":"Câu hỏi: Hồ sơ nộp còn thiếu gì?\n(A) Một biên lai thanh toán\n(B) Chữ ký của thanh tra viên\n(C) Một bản đồ tuyến ống mới\n(D) Bản kế hoạch thoát nước ban đầu","optionTranslations":"Câu hỏi: Hồ sơ nộp còn thiếu gì?\n(A) Một biên lai thanh toán\n(B) Chữ ký của thanh tra viên\n(C) Một bản đồ tuyến ống mới\n(D) Bản kế hoạch thoát nước ban đầu","explanation":"Đáp án đúng: C. Người đàn ông nói: “one page is missing—the map showing the new pipe route.” Bản sửa đổi đã được nộp, chỉ thiếu trang bản đồ. Không có biên lai hay chữ ký nào được nhắc đến; bản gốc không phải tài liệu bị thiếu, nên A, B, D sai.","hintWords":["chen","crew","pour","foundation","riverside"],"keyVocab":[{"word":"drainage","meaning":"hệ thống thoát nước"},{"word":"pipe","meaning":"ống"},{"word":"submit","meaning":"nộp"},{"word":"revised","meaning":"đã được sửa đổi"}],"practiceOptions":[{"key":"A","text":"A payment receipt","correct":false},{"key":"B","text":"The inspector's signature","correct":false},{"key":"C","text":"A map of the new pipe route","correct":true},{"key":"D","text":"The original drainage plan","correct":false}]},{"id":"ets-orig-test-2-q46","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 46 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What does the woman suggest doing?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g05.mp3","audioText":"Ms. Chen, the crew can't pour the foundation at the Riverside site tomorrow. Why not? The weather forecast is clear. The city inspector hasn't approved the revised drainage plan. Without that approval, we're not allowed to continue. I thought the revision was submitted last week. It was, but the inspector's office says one page is missing—the map showing the new pipe route. I have that map on my laptop. I'll email it to them right away and ask for an expedited review. That would help. If we don't start by Monday, the steel delivery will arrive before we have anywhere to store it. Then let's also ask the supplier to hold the delivery for three days. I will call the steel supplier this morning and confirm the revised delivery window. Thanks. Please copy me on the confirmation e-mail.","fullTranscript":"Man: Ms. Chen, the crew can't pour the foundation at the Riverside site tomorrow. Woman: Why not? The weather forecast is clear. Man: The city inspector hasn't approved the revised drainage plan. Without that approval, we're not allowed to continue. Woman: I thought the revision was submitted last week. Man: It was, but the inspector's office says one page is missing—the map showing the new pipe route. Woman: I have that map on my laptop. I'll email it to them right away and ask for an expedited review. Man: That would help. If we don't start by Monday, the steel delivery will arrive before we have anywhere to store it. Woman: Then let's also ask the supplier to hold the delivery for three days. Man 2: I will call the steel supplier this morning and confirm the revised delivery window. Woman: Thanks. Please copy me on the confirmation e-mail.","vietnamese":"Câu hỏi: Người phụ nữ đề nghị làm gì?\n(A) Thuê một thanh tra viên khác\n(B) Chuyển số thép sang công trường khác\n(C) Khởi công mà không có phê duyệt\n(D) Yêu cầu nhà cung cấp hoãn giao hàng","optionTranslations":"Câu hỏi: Người phụ nữ đề nghị làm gì?\n(A) Thuê một thanh tra viên khác\n(B) Chuyển số thép sang công trường khác\n(C) Khởi công mà không có phê duyệt\n(D) Yêu cầu nhà cung cấp hoãn giao hàng","explanation":"Đáp án đúng: D. Người phụ nữ nói: “let's also ask the supplier to hold the delivery for three days.” Bà ấy muốn hoãn giao thép để có chỗ chứa. Không có ý thuê thanh tra khác, chuyển thép đi nơi khác hay làm trái phép, nên A, B, C sai.","hintWords":["chen","crew","pour","foundation","riverside"],"keyVocab":[{"word":"supplier","meaning":"nhà cung cấp"},{"word":"hold","meaning":"giữ lại, hoãn"},{"word":"delivery","meaning":"việc giao hàng"},{"word":"expedited","meaning":"được xử lý nhanh"}],"practiceOptions":[{"key":"A","text":"Hiring another inspector","correct":false},{"key":"B","text":"Moving the steel to a different site","correct":false},{"key":"C","text":"Starting the work without approval","correct":false},{"key":"D","text":"Asking the supplier to delay delivery","correct":true}]},{"id":"ets-orig-test-2-q47","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 47 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"Why does the woman want to change her schedule?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g06.mp3","audioText":"Marcus, do you have the schedule for next week? I need to swap my Saturday shift.\nI haven't posted it yet. What's going on?\nMy sister's graduation is that afternoon. I could work Sunday instead if someone covers the morning.\nLet me check. Priya is already scheduled for Sunday, but she asked for fewer hours.\nMaybe she'd take my Saturday shift. She knows the register and the delivery process.\nI'll ask her this afternoon. Just remember that Saturday is our inventory count, so whoever covers it needs to stay until the store closes.\nI can come in early on Saturday to help with the count before I leave for the ceremony.\nThat would work. I'll confirm the change by Thursday.","fullTranscript":"Woman: Marcus, do you have the schedule for next week? I need to swap my Saturday shift. Man: I haven't posted it yet. What's going on? Woman: My sister's graduation is that afternoon. I could work Sunday instead if someone covers the morning. Man: Let me check. Priya is already scheduled for Sunday, but she asked for fewer hours. Woman: Maybe she'd take my Saturday shift. She knows the register and the delivery process. Man: I'll ask her this afternoon. Just remember that Saturday is our inventory count, so whoever covers it needs to stay until the store closes. Woman: I can come in early on Saturday to help with the count before I leave for the ceremony. Man: That would work. I'll confirm the change by Thursday.","vietnamese":"Câu hỏi: Tại sao người phụ nữ muốn đổi lịch làm việc?\n(A) Cô ấy có cuộc hẹn với bác sĩ.\n(B) Cô ấy đang đi nghỉ.\n(C) Cô ấy tham dự lễ tốt nghiệp của em gái.\n(D) Cô ấy phải làm việc ở một cửa hàng khác.","optionTranslations":"Câu hỏi: Tại sao người phụ nữ muốn đổi lịch làm việc?\n(A) Cô ấy có cuộc hẹn với bác sĩ.\n(B) Cô ấy đang đi nghỉ.\n(C) Cô ấy tham dự lễ tốt nghiệp của em gái.\n(D) Cô ấy phải làm việc ở một cửa hàng khác.","explanation":"Đáp án đúng: C. Người phụ nữ nói: “My sister's graduation is that afternoon.” Cô ấy muốn đổi ca thứ Bảy để dự lễ. Không có cuộc hẹn bác sĩ, kỳ nghỉ hay việc làm ở cửa hàng khác, nên A, B, D sai.","hintWords":["woman","marcus","have","schedule","next"],"keyVocab":[{"word":"shift","meaning":"ca làm việc"},{"word":"swap","meaning":"đổi, hoán đổi"},{"word":"graduation","meaning":"lễ tốt nghiệp"},{"word":"ceremony","meaning":"buổi lễ"}],"practiceOptions":[{"key":"A","text":"She has a doctor's appointment.","correct":false},{"key":"B","text":"She is taking a vacation.","correct":false},{"key":"C","text":"She is attending her sister's graduation.","correct":true},{"key":"D","text":"She has to work at another store.","correct":false}]},{"id":"ets-orig-test-2-q48","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 48 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What does the man remind the woman about Saturday?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g06.mp3","audioText":"Marcus, do you have the schedule for next week? I need to swap my Saturday shift.\nI haven't posted it yet. What's going on?\nMy sister's graduation is that afternoon. I could work Sunday instead if someone covers the morning.\nLet me check. Priya is already scheduled for Sunday, but she asked for fewer hours.\nMaybe she'd take my Saturday shift. She knows the register and the delivery process.\nI'll ask her this afternoon. Just remember that Saturday is our inventory count, so whoever covers it needs to stay until the store closes.\nI can come in early on Saturday to help with the count before I leave for the ceremony.\nThat would work. I'll confirm the change by Thursday.","fullTranscript":"Woman: Marcus, do you have the schedule for next week? I need to swap my Saturday shift. Man: I haven't posted it yet. What's going on? Woman: My sister's graduation is that afternoon. I could work Sunday instead if someone covers the morning. Man: Let me check. Priya is already scheduled for Sunday, but she asked for fewer hours. Woman: Maybe she'd take my Saturday shift. She knows the register and the delivery process. Man: I'll ask her this afternoon. Just remember that Saturday is our inventory count, so whoever covers it needs to stay until the store closes. Woman: I can come in early on Saturday to help with the count before I leave for the ceremony. Man: That would work. I'll confirm the change by Thursday.","vietnamese":"Câu hỏi: Người đàn ông nhắc người phụ nữ điều gì về thứ Bảy?\n(A) Đó là ngày kiểm kê hàng hóa.\n(B) Cửa hàng đóng cửa sớm.\n(C) Priya sẽ đào tạo một nhân viên mới.\n(D) Hàng giao sẽ đến vào buổi sáng.","optionTranslations":"Câu hỏi: Người đàn ông nhắc người phụ nữ điều gì về thứ Bảy?\n(A) Đó là ngày kiểm kê hàng hóa.\n(B) Cửa hàng đóng cửa sớm.\n(C) Priya sẽ đào tạo một nhân viên mới.\n(D) Hàng giao sẽ đến vào buổi sáng.","explanation":"Đáp án đúng: A. Người đàn ông nói: “Just remember that Saturday is our inventory count, so whoever covers it needs to stay until the store closes.” Cửa hàng đóng cửa như thường lệ chứ không sớm, nên B sai; không có việc Priya đào tạo nhân viên mới hay hàng giao buổi sáng, nên C và D sai.","hintWords":["woman","marcus","have","schedule","next"],"keyVocab":[{"word":"inventory count","meaning":"việc kiểm kê hàng hóa"},{"word":"cover","meaning":"trực thay, làm thay"},{"word":"register","meaning":"máy tính tiền"}],"practiceOptions":[{"key":"A","text":"It is the day of the inventory count.","correct":true},{"key":"B","text":"The store closes early.","correct":false},{"key":"C","text":"Priya will train a new employee.","correct":false},{"key":"D","text":"The delivery arrives in the morning.","correct":false}]},{"id":"ets-orig-test-2-q49","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 49 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"When will the man confirm the schedule change?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g06.mp3","audioText":"Marcus, do you have the schedule for next week? I need to swap my Saturday shift.\nI haven't posted it yet. What's going on?\nMy sister's graduation is that afternoon. I could work Sunday instead if someone covers the morning.\nLet me check. Priya is already scheduled for Sunday, but she asked for fewer hours.\nMaybe she'd take my Saturday shift. She knows the register and the delivery process.\nI'll ask her this afternoon. Just remember that Saturday is our inventory count, so whoever covers it needs to stay until the store closes.\nI can come in early on Saturday to help with the count before I leave for the ceremony.\nThat would work. I'll confirm the change by Thursday.","fullTranscript":"Woman: Marcus, do you have the schedule for next week? I need to swap my Saturday shift. Man: I haven't posted it yet. What's going on? Woman: My sister's graduation is that afternoon. I could work Sunday instead if someone covers the morning. Man: Let me check. Priya is already scheduled for Sunday, but she asked for fewer hours. Woman: Maybe she'd take my Saturday shift. She knows the register and the delivery process. Man: I'll ask her this afternoon. Just remember that Saturday is our inventory count, so whoever covers it needs to stay until the store closes. Woman: I can come in early on Saturday to help with the count before I leave for the ceremony. Man: That would work. I'll confirm the change by Thursday.","vietnamese":"Câu hỏi: Khi nào người đàn ông sẽ xác nhận việc đổi lịch?\n(A) Thứ Tư\n(B) Thứ Năm\n(C) Thứ Sáu\n(D) Chủ Nhật","optionTranslations":"Câu hỏi: Khi nào người đàn ông sẽ xác nhận việc đổi lịch?\n(A) Thứ Tư\n(B) Thứ Năm\n(C) Thứ Sáu\n(D) Chủ Nhật","explanation":"Đáp án đúng: B. Người đàn ông kết luận: “I'll confirm the change by Thursday.” Thứ Tư, thứ Sáu và Chủ Nhật không phải mốc xác nhận, dù Chủ Nhật được nhắc đến như một ngày làm việc thay thế.","hintWords":["woman","marcus","have","schedule","next"],"keyVocab":[{"word":"confirm","meaning":"xác nhận"},{"word":"schedule","meaning":"lịch làm việc"},{"word":"post","meaning":"đăng lên"}],"practiceOptions":[{"key":"A","text":"Wednesday","correct":false},{"key":"B","text":"Thursday","correct":true},{"key":"C","text":"Friday","correct":false},{"key":"D","text":"Sunday","correct":false}]},{"id":"ets-orig-test-2-q50","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 50 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What is the discrepancy in the invoice?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g07.mp3","audioText":"Ms. Okafor, I'm reviewing the invoice from Northline Supplies, and the amount doesn't match our purchase order.\nHow much is the difference?\nThey charged us for forty boxes of paper, but we only received thirty. The unit price is correct.\nDid anyone sign for thirty or forty?\nThe delivery receipt says thirty. I think the warehouse manager noted the shortage on the copy.\nGood. Send the receipt and the purchase order to their billing department and ask for a corrected invoice.\nShould I also hold payment until they respond?\nYes. And copy me on the email so I can follow up if we don't hear back by Friday.","fullTranscript":"Man: Ms. Okafor, I'm reviewing the invoice from Northline Supplies, and the amount doesn't match our purchase order. Woman: How much is the difference? Man: They charged us for forty boxes of paper, but we only received thirty. The unit price is correct. Woman: Did anyone sign for thirty or forty? Man: The delivery receipt says thirty. I think the warehouse manager noted the shortage on the copy. Woman: Good. Send the receipt and the purchase order to their billing department and ask for a corrected invoice. Man: Should I also hold payment until they respond? Woman: Yes. And copy me on the email so I can follow up if we don't hear back by Friday.","vietnamese":"Câu hỏi: Sự sai lệch trong hóa đơn là gì?\n(A) Đơn giá quá cao.\n(B) Sai tên công ty.\n(C) Khoản thanh toán đã quá hạn.\n(D) Số lượng bị tính tiền không đúng.","optionTranslations":"Câu hỏi: Sự sai lệch trong hóa đơn là gì?\n(A) Đơn giá quá cao.\n(B) Sai tên công ty.\n(C) Khoản thanh toán đã quá hạn.\n(D) Số lượng bị tính tiền không đúng.","explanation":"Đáp án đúng: D. Người đàn ông nói: “They charged us for forty boxes of paper, but we only received thirty. The unit price is correct.” Hóa đơn tính bốn mươi thùng nhưng chỉ giao ba mươi. Đơn giá đúng nên A sai; không có sai tên công ty hay thanh toán quá hạn, nên B và C sai.","hintWords":["okafor","reviewing","invoice","from","northline"],"keyVocab":[{"word":"invoice","meaning":"hóa đơn"},{"word":"purchase order","meaning":"đơn đặt hàng"},{"word":"discrepancy","meaning":"sự sai lệch"},{"word":"unit price","meaning":"đơn giá"}],"practiceOptions":[{"key":"A","text":"The unit price is too high.","correct":false},{"key":"B","text":"The wrong company is listed.","correct":false},{"key":"C","text":"The payment is overdue.","correct":false},{"key":"D","text":"The quantity charged is incorrect.","correct":true}]},{"id":"ets-orig-test-2-q51","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 51 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What does the woman ask the man to do?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g07.mp3","audioText":"Ms. Okafor, I'm reviewing the invoice from Northline Supplies, and the amount doesn't match our purchase order.\nHow much is the difference?\nThey charged us for forty boxes of paper, but we only received thirty. The unit price is correct.\nDid anyone sign for thirty or forty?\nThe delivery receipt says thirty. I think the warehouse manager noted the shortage on the copy.\nGood. Send the receipt and the purchase order to their billing department and ask for a corrected invoice.\nShould I also hold payment until they respond?\nYes. And copy me on the email so I can follow up if we don't hear back by Friday.","fullTranscript":"Man: Ms. Okafor, I'm reviewing the invoice from Northline Supplies, and the amount doesn't match our purchase order. Woman: How much is the difference? Man: They charged us for forty boxes of paper, but we only received thirty. The unit price is correct. Woman: Did anyone sign for thirty or forty? Man: The delivery receipt says thirty. I think the warehouse manager noted the shortage on the copy. Woman: Good. Send the receipt and the purchase order to their billing department and ask for a corrected invoice. Man: Should I also hold payment until they respond? Woman: Yes. And copy me on the email so I can follow up if we don't hear back by Friday.","vietnamese":"Câu hỏi: Người phụ nữ yêu cầu người đàn ông làm gì?\n(A) Thanh toán hóa đơn ngay lập tức\n(B) Yêu cầu một hóa đơn đã sửa\n(C) Gọi cho quản lý kho\n(D) Đặt thêm giấy","optionTranslations":"Câu hỏi: Người phụ nữ yêu cầu người đàn ông làm gì?\n(A) Thanh toán hóa đơn ngay lập tức\n(B) Yêu cầu một hóa đơn đã sửa\n(C) Gọi cho quản lý kho\n(D) Đặt thêm giấy","explanation":"Đáp án đúng: B. Người phụ nữ nói: “Send the receipt and the purchase order to their billing department and ask for a corrected invoice.” Bà ấy còn đồng ý giữ lại khoản thanh toán, tức là không trả ngay, nên A sai; không yêu cầu gọi quản lý kho hay đặt thêm giấy, nên C và D sai.","hintWords":["okafor","reviewing","invoice","from","northline"],"keyVocab":[{"word":"billing department","meaning":"bộ phận thanh toán"},{"word":"corrected","meaning":"đã được sửa"},{"word":"receipt","meaning":"biên nhận"},{"word":"hold","meaning":"giữ lại, tạm hoãn"}],"practiceOptions":[{"key":"A","text":"Pay the invoice immediately","correct":false},{"key":"B","text":"Request a corrected invoice","correct":true},{"key":"C","text":"Call the warehouse manager","correct":false},{"key":"D","text":"Order more paper","correct":false}]},{"id":"ets-orig-test-2-q52","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 52 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What does the woman want to receive?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g07.mp3","audioText":"Ms. Okafor, I'm reviewing the invoice from Northline Supplies, and the amount doesn't match our purchase order.\nHow much is the difference?\nThey charged us for forty boxes of paper, but we only received thirty. The unit price is correct.\nDid anyone sign for thirty or forty?\nThe delivery receipt says thirty. I think the warehouse manager noted the shortage on the copy.\nGood. Send the receipt and the purchase order to their billing department and ask for a corrected invoice.\nShould I also hold payment until they respond?\nYes. And copy me on the email so I can follow up if we don't hear back by Friday.","fullTranscript":"Man: Ms. Okafor, I'm reviewing the invoice from Northline Supplies, and the amount doesn't match our purchase order. Woman: How much is the difference? Man: They charged us for forty boxes of paper, but we only received thirty. The unit price is correct. Woman: Did anyone sign for thirty or forty? Man: The delivery receipt says thirty. I think the warehouse manager noted the shortage on the copy. Woman: Good. Send the receipt and the purchase order to their billing department and ask for a corrected invoice. Man: Should I also hold payment until they respond? Woman: Yes. And copy me on the email so I can follow up if we don't hear back by Friday.","vietnamese":"Câu hỏi: Người phụ nữ muốn nhận được gì?\n(A) Một bản sao của email\n(B) Một đơn đặt hàng mới\n(C) Một cuộc gọi từ Northline\n(D) Biên nhận giao hàng gốc","optionTranslations":"Câu hỏi: Người phụ nữ muốn nhận được gì?\n(A) Một bản sao của email\n(B) Một đơn đặt hàng mới\n(C) Một cuộc gọi từ Northline\n(D) Biên nhận giao hàng gốc","explanation":"Đáp án đúng: A. Người phụ nữ nói: “copy me on the email so I can follow up if we don't hear back by Friday.” Bà ấy muốn được cc vào email. Không cần đơn đặt hàng mới, không yêu cầu Northline gọi lại và không yêu cầu nhận biên nhận gốc, nên B, C, D sai.","hintWords":["okafor","reviewing","invoice","from","northline"],"keyVocab":[{"word":"copy","meaning":"gửi bản sao"},{"word":"follow up","meaning":"theo dõi, liên hệ lại"},{"word":"shortage","meaning":"sự thiếu hụt"}],"practiceOptions":[{"key":"A","text":"A copy of the email","correct":true},{"key":"B","text":"A new purchase order","correct":false},{"key":"C","text":"A phone call from Northline","correct":false},{"key":"D","text":"The original delivery receipt","correct":false}]},{"id":"ets-orig-test-2-q53","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 53 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"When is the client meeting now?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g08.mp3","audioText":"I've drafted the itinerary for your trip to Singapore. You leave on Tuesday at 8:40 a.m. and arrive at 1:15 p.m. Good. Is the hotel close to the client's office? It's about a ten-minute walk. I've also booked a conference room at the hotel for Wednesday morning. Wednesday morning? I thought the client meeting was on Thursday. It was, but Mr. Tan's assistant called this morning. He has to fly to Bangkok on Thursday, so he asked to move our meeting up. That's fine. Could you send the revised schedule to the project team? They need to prepare the slides a day earlier. I'll do it right after lunch. Do you want me to arrange a car to the airport? No, thanks. The hotel shuttle is included in the room rate. I have already printed the client agenda. Should I leave a copy at the front desk? Yes, and put one in the meeting room as well.","fullTranscript":"Woman: I've drafted the itinerary for your trip to Singapore. You leave on Tuesday at 8:40 a.m. and arrive at 1:15 p.m. Man: Good. Is the hotel close to the client's office? Woman: It's about a ten-minute walk. I've also booked a conference room at the hotel for Wednesday morning. Man: Wednesday morning? I thought the client meeting was on Thursday. Woman: It was, but Mr. Tan's assistant called this morning. He has to fly to Bangkok on Thursday, so he asked to move our meeting up. Man: That's fine. Could you send the revised schedule to the project team? They need to prepare the slides a day earlier. Woman: I'll do it right after lunch. Do you want me to arrange a car to the airport? Man: No, thanks. The hotel shuttle is included in the room rate. Woman 2: I have already printed the client agenda. Should I leave a copy at the front desk? Man: Yes, and put one in the meeting room as well.","vietnamese":"Câu hỏi: Bây giờ cuộc họp với khách hàng diễn ra khi nào?\n(A) Sáng thứ Tư\n(B) Chiều thứ Ba\n(C) Sáng thứ Năm\n(D) Chiều thứ Sáu","optionTranslations":"Câu hỏi: Bây giờ cuộc họp với khách hàng diễn ra khi nào?\n(A) Sáng thứ Tư\n(B) Chiều thứ Ba\n(C) Sáng thứ Năm\n(D) Chiều thứ Sáu","explanation":"Đáp án đúng: A. Người phụ nữ cho biết đã đặt phòng họp cho sáng thứ Tư, sau đó giải thích cuộc họp với khách được dời lên vì ông Tan phải bay sang Bangkok vào thứ Năm. Thứ Năm là lịch cũ nên C sai; chiều thứ Ba là giờ hạ cánh, không phải giờ họp, nên B sai; thứ Sáu không được nhắc đến.","hintWords":["woman","drafted","itinerary","your","trip"],"keyVocab":[{"word":"itinerary","meaning":"lịch trình"},{"word":"conference room","meaning":"phòng hội nghị"},{"word":"move up","meaning":"dời lên sớm hơn"}],"practiceOptions":[{"key":"A","text":"Wednesday morning","correct":true},{"key":"B","text":"Tuesday afternoon","correct":false},{"key":"C","text":"Thursday morning","correct":false},{"key":"D","text":"Friday afternoon","correct":false}]},{"id":"ets-orig-test-2-q54","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 54 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"Why was the meeting moved?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g08.mp3","audioText":"I've drafted the itinerary for your trip to Singapore. You leave on Tuesday at 8:40 a.m. and arrive at 1:15 p.m. Good. Is the hotel close to the client's office? It's about a ten-minute walk. I've also booked a conference room at the hotel for Wednesday morning. Wednesday morning? I thought the client meeting was on Thursday. It was, but Mr. Tan's assistant called this morning. He has to fly to Bangkok on Thursday, so he asked to move our meeting up. That's fine. Could you send the revised schedule to the project team? They need to prepare the slides a day earlier. I'll do it right after lunch. Do you want me to arrange a car to the airport? No, thanks. The hotel shuttle is included in the room rate. I have already printed the client agenda. Should I leave a copy at the front desk? Yes, and put one in the meeting room as well.","fullTranscript":"Woman: I've drafted the itinerary for your trip to Singapore. You leave on Tuesday at 8:40 a.m. and arrive at 1:15 p.m. Man: Good. Is the hotel close to the client's office? Woman: It's about a ten-minute walk. I've also booked a conference room at the hotel for Wednesday morning. Man: Wednesday morning? I thought the client meeting was on Thursday. Woman: It was, but Mr. Tan's assistant called this morning. He has to fly to Bangkok on Thursday, so he asked to move our meeting up. Man: That's fine. Could you send the revised schedule to the project team? They need to prepare the slides a day earlier. Woman: I'll do it right after lunch. Do you want me to arrange a car to the airport? Man: No, thanks. The hotel shuttle is included in the room rate. Woman 2: I have already printed the client agenda. Should I leave a copy at the front desk? Man: Yes, and put one in the meeting room as well.","vietnamese":"Câu hỏi: Tại sao cuộc họp bị dời?\n(A) Văn phòng khách hàng đang được cải tạo.\n(B) Chuyến bay của người đàn ông bị hoãn.\n(C) Ông Tan phải đi công tác ở Bangkok.\n(D) Phòng hội nghị của khách sạn không còn trống.","optionTranslations":"Câu hỏi: Tại sao cuộc họp bị dời?\n(A) Văn phòng khách hàng đang được cải tạo.\n(B) Chuyến bay của người đàn ông bị hoãn.\n(C) Ông Tan phải đi công tác ở Bangkok.\n(D) Phòng hội nghị của khách sạn không còn trống.","explanation":"Đáp án đúng: C. Người phụ nữ nói: “He has to fly to Bangkok on Thursday, so he asked to move our meeting up.” Không có việc cải tạo văn phòng, chuyến bay bị hoãn hay phòng họp không trống, nên A, B, D sai.","hintWords":["woman","drafted","itinerary","your","trip"],"keyVocab":[{"word":"assistant","meaning":"trợ lý"},{"word":"revised","meaning":"đã được điều chỉnh"},{"word":"schedule","meaning":"lịch trình"}],"practiceOptions":[{"key":"A","text":"The client's office is being renovated.","correct":false},{"key":"B","text":"The man's flight was delayed.","correct":false},{"key":"C","text":"Mr. Tan has to travel to Bangkok.","correct":true},{"key":"D","text":"The hotel conference room is unavailable.","correct":false}]},{"id":"ets-orig-test-2-q55","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 55 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"How will the man get to the airport?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g08.mp3","audioText":"I've drafted the itinerary for your trip to Singapore. You leave on Tuesday at 8:40 a.m. and arrive at 1:15 p.m. Good. Is the hotel close to the client's office? It's about a ten-minute walk. I've also booked a conference room at the hotel for Wednesday morning. Wednesday morning? I thought the client meeting was on Thursday. It was, but Mr. Tan's assistant called this morning. He has to fly to Bangkok on Thursday, so he asked to move our meeting up. That's fine. Could you send the revised schedule to the project team? They need to prepare the slides a day earlier. I'll do it right after lunch. Do you want me to arrange a car to the airport? No, thanks. The hotel shuttle is included in the room rate. I have already printed the client agenda. Should I leave a copy at the front desk? Yes, and put one in the meeting room as well.","fullTranscript":"Woman: I've drafted the itinerary for your trip to Singapore. You leave on Tuesday at 8:40 a.m. and arrive at 1:15 p.m. Man: Good. Is the hotel close to the client's office? Woman: It's about a ten-minute walk. I've also booked a conference room at the hotel for Wednesday morning. Man: Wednesday morning? I thought the client meeting was on Thursday. Woman: It was, but Mr. Tan's assistant called this morning. He has to fly to Bangkok on Thursday, so he asked to move our meeting up. Man: That's fine. Could you send the revised schedule to the project team? They need to prepare the slides a day earlier. Woman: I'll do it right after lunch. Do you want me to arrange a car to the airport? Man: No, thanks. The hotel shuttle is included in the room rate. Woman 2: I have already printed the client agenda. Should I leave a copy at the front desk? Man: Yes, and put one in the meeting room as well.","vietnamese":"Câu hỏi: Người đàn ông sẽ đến sân bay bằng cách nào?\n(A) Bằng taxi\n(B) Bằng tàu\n(C) Bằng xe thuê\n(D) Bằng xe đưa đón của khách sạn","optionTranslations":"Câu hỏi: Người đàn ông sẽ đến sân bay bằng cách nào?\n(A) Bằng taxi\n(B) Bằng tàu\n(C) Bằng xe thuê\n(D) Bằng xe đưa đón của khách sạn","explanation":"Đáp án đúng: D. Người đàn ông từ chối việc thu xếp xe và nói: “The hotel shuttle is included in the room rate.” Taxi, tàu và xe thuê đều không được nhắc đến, nên A, B, C sai.","hintWords":["woman","drafted","itinerary","your","trip"],"keyVocab":[{"word":"shuttle","meaning":"xe đưa đón"},{"word":"room rate","meaning":"giá phòng"},{"word":"include","meaning":"bao gồm"}],"practiceOptions":[{"key":"A","text":"By taxi","correct":false},{"key":"B","text":"By train","correct":false},{"key":"C","text":"By rental car","correct":false},{"key":"D","text":"By hotel shuttle","correct":true}]},{"id":"ets-orig-test-2-q56","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 56 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What is the woman's concern about Bell & Sons?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g09.mp3","audioText":"Ms. Harlow, have you looked at the bids for the new library branch?\nI have. Three companies submitted proposals, but only two included the accessibility features required by the grant.\nWhich two?\nBell & Sons and Harbor Construction. Bell's price is lower, but their timeline is six months longer.\nThe grant requires us to open within eighteen months. Would Harbor's schedule meet that?\nYes, they estimate sixteen months. However, their bid is about 12 percent higher.\nCan we ask them to explain the difference? Maybe some of the cost is for the optional courtyard.\nGood point. I'll request a breakdown of their costs and compare it with Bell's.","fullTranscript":"Man: Ms. Harlow, have you looked at the bids for the new library branch? Woman: I have. Three companies submitted proposals, but only two included the accessibility features required by the grant. Man: Which two? Woman: Bell & Sons and Harbor Construction. Bell's price is lower, but their timeline is six months longer. Man: The grant requires us to open within eighteen months. Would Harbor's schedule meet that? Woman: Yes, they estimate sixteen months. However, their bid is about 12 percent higher. Man: Can we ask them to explain the difference? Maybe some of the cost is for the optional courtyard. Woman: Good point. I'll request a breakdown of their costs and compare it with Bell's.","vietnamese":"Câu hỏi: Người phụ nữ lo ngại điều gì về Bell & Sons?\n(A) Giá thầu của họ quá cao.\n(B) Thời gian thi công của họ quá dài.\n(C) Họ thiếu các tính năng tiếp cận.\n(D) Họ không có kinh nghiệm xây thư viện.","optionTranslations":"Câu hỏi: Người phụ nữ lo ngại điều gì về Bell & Sons?\n(A) Giá thầu của họ quá cao.\n(B) Thời gian thi công của họ quá dài.\n(C) Họ thiếu các tính năng tiếp cận.\n(D) Họ không có kinh nghiệm xây thư viện.","explanation":"Đáp án đúng: B. Người phụ nữ nói: “Bell's price is lower, but their timeline is six months longer.” Giá của Bell thấp hơn nên A sai; Bell nằm trong hai công ty có tính năng tiếp cận nên C sai; không có thông tin về kinh nghiệm xây thư viện nên D sai.","hintWords":["harlow","have","looked","bids","library"],"keyVocab":[{"word":"bid","meaning":"giá thầu, hồ sơ dự thầu"},{"word":"proposal","meaning":"đề xuất"},{"word":"timeline","meaning":"tiến độ, thời gian thực hiện"},{"word":"accessibility","meaning":"khả năng tiếp cận"}],"practiceOptions":[{"key":"A","text":"Its bid is too expensive.","correct":false},{"key":"B","text":"Its timeline is too long.","correct":true},{"key":"C","text":"It lacks accessibility features.","correct":false},{"key":"D","text":"It has no experience with libraries.","correct":false}]},{"id":"ets-orig-test-2-q57","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 57 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What does the man suggest?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g09.mp3","audioText":"Ms. Harlow, have you looked at the bids for the new library branch?\nI have. Three companies submitted proposals, but only two included the accessibility features required by the grant.\nWhich two?\nBell & Sons and Harbor Construction. Bell's price is lower, but their timeline is six months longer.\nThe grant requires us to open within eighteen months. Would Harbor's schedule meet that?\nYes, they estimate sixteen months. However, their bid is about 12 percent higher.\nCan we ask them to explain the difference? Maybe some of the cost is for the optional courtyard.\nGood point. I'll request a breakdown of their costs and compare it with Bell's.","fullTranscript":"Man: Ms. Harlow, have you looked at the bids for the new library branch? Woman: I have. Three companies submitted proposals, but only two included the accessibility features required by the grant. Man: Which two? Woman: Bell & Sons and Harbor Construction. Bell's price is lower, but their timeline is six months longer. Man: The grant requires us to open within eighteen months. Would Harbor's schedule meet that? Woman: Yes, they estimate sixteen months. However, their bid is about 12 percent higher. Man: Can we ask them to explain the difference? Maybe some of the cost is for the optional courtyard. Woman: Good point. I'll request a breakdown of their costs and compare it with Bell's.","vietnamese":"Câu hỏi: Người đàn ông đề xuất điều gì?\n(A) Từ chối cả hai đề xuất\n(B) Thuê Bell & Sons ngay lập tức\n(C) Giảm quy mô thư viện\n(D) Yêu cầu Harbor Construction giải trình chi tiết chi phí","optionTranslations":"Câu hỏi: Người đàn ông đề xuất điều gì?\n(A) Từ chối cả hai đề xuất\n(B) Thuê Bell & Sons ngay lập tức\n(C) Giảm quy mô thư viện\n(D) Yêu cầu Harbor Construction giải trình chi tiết chi phí","explanation":"Đáp án đúng: D. Người đàn ông nói: “Can we ask them to explain the difference? Maybe some of the cost is for the optional courtyard.” “Them” là Harbor Construction. Người phụ nữ đồng ý và sẽ yêu cầu bảng phân tích chi phí. Không ai đề nghị từ chối cả hai, thuê Bell ngay hay thu nhỏ thư viện, nên A, B, C sai.","hintWords":["harlow","have","looked","bids","library"],"keyVocab":[{"word":"breakdown","meaning":"sự phân tích chi tiết"},{"word":"optional","meaning":"tùy chọn"},{"word":"courtyard","meaning":"sân trong"},{"word":"estimate","meaning":"ước tính"}],"practiceOptions":[{"key":"A","text":"Rejecting both proposals","correct":false},{"key":"B","text":"Hiring Bell & Sons immediately","correct":false},{"key":"C","text":"Reducing the size of the library","correct":false},{"key":"D","text":"Asking Harbor Construction for a cost breakdown","correct":true}]},{"id":"ets-orig-test-2-q58","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 58 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What will the woman do next?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g09.mp3","audioText":"Ms. Harlow, have you looked at the bids for the new library branch?\nI have. Three companies submitted proposals, but only two included the accessibility features required by the grant.\nWhich two?\nBell & Sons and Harbor Construction. Bell's price is lower, but their timeline is six months longer.\nThe grant requires us to open within eighteen months. Would Harbor's schedule meet that?\nYes, they estimate sixteen months. However, their bid is about 12 percent higher.\nCan we ask them to explain the difference? Maybe some of the cost is for the optional courtyard.\nGood point. I'll request a breakdown of their costs and compare it with Bell's.","fullTranscript":"Man: Ms. Harlow, have you looked at the bids for the new library branch? Woman: I have. Three companies submitted proposals, but only two included the accessibility features required by the grant. Man: Which two? Woman: Bell & Sons and Harbor Construction. Bell's price is lower, but their timeline is six months longer. Man: The grant requires us to open within eighteen months. Would Harbor's schedule meet that? Woman: Yes, they estimate sixteen months. However, their bid is about 12 percent higher. Man: Can we ask them to explain the difference? Maybe some of the cost is for the optional courtyard. Woman: Good point. I'll request a breakdown of their costs and compare it with Bell's.","vietnamese":"Câu hỏi: Người phụ nữ sẽ làm gì tiếp theo?\n(A) Nộp đơn xin khoản tài trợ mới\n(B) Thăm công trường\n(C) Yêu cầu thông tin chi phí chi tiết\n(D) Ký hợp đồng với Harbor","optionTranslations":"Câu hỏi: Người phụ nữ sẽ làm gì tiếp theo?\n(A) Nộp đơn xin khoản tài trợ mới\n(B) Thăm công trường\n(C) Yêu cầu thông tin chi phí chi tiết\n(D) Ký hợp đồng với Harbor","explanation":"Đáp án đúng: C. Người phụ nữ nói: “I'll request a breakdown of their costs and compare it with Bell's.” Bà ấy chưa chọn nhà thầu nên chưa ký hợp đồng, D sai; không có việc xin tài trợ mới hay thăm công trường, nên A và B sai.","hintWords":["harlow","have","looked","bids","library"],"keyVocab":[{"word":"grant","meaning":"khoản tài trợ"},{"word":"contract","meaning":"hợp đồng"},{"word":"compare","meaning":"so sánh"},{"word":"branch","meaning":"chi nhánh"}],"practiceOptions":[{"key":"A","text":"Apply for a new grant","correct":false},{"key":"B","text":"Visit the construction site","correct":false},{"key":"C","text":"Request detailed cost information","correct":true},{"key":"D","text":"Sign a contract with Harbor","correct":false}]},{"id":"ets-orig-test-2-q59","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 59 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What is the customer's problem?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g10.mp3","audioText":"I ordered a set of four dining chairs last week, but only two arrived. The box was damaged on one side.\nI'm sorry about that. Could you give me your order number?\nIt's 48217. I need the other two chairs before my parents visit on the twentieth.\nLet me check the stock... We have the same model in walnut, but not in oak. Would you accept walnut for the missing chairs?\nI'd prefer to keep the set matching. Is there any way to get oak?\nI can order them from our other warehouse. They should arrive in five business days.\nThat works. And what about the damaged box? Should I send it back?\nNo need. Our courier will collect it when the new chairs are delivered.","fullTranscript":"Man: I ordered a set of four dining chairs last week, but only two arrived. The box was damaged on one side. Woman: I'm sorry about that. Could you give me your order number? Man: It's 48217. I need the other two chairs before my parents visit on the twentieth. Woman: Let me check the stock... We have the same model in walnut, but not in oak. Would you accept walnut for the missing chairs? Man: I'd prefer to keep the set matching. Is there any way to get oak? Woman: I can order them from our other warehouse. They should arrive in five business days. Man: That works. And what about the damaged box? Should I send it back? Woman: No need. Our courier will collect it when the new chairs are delivered.","vietnamese":"Câu hỏi: Khách hàng gặp vấn đề gì?\n(A) Anh ấy nhận được ghế sai màu.\n(B) Đơn hàng của anh ấy đến muộn.\n(C) Chỉ một phần đơn hàng được giao.\n(D) Ghế đắt hơn giá quảng cáo.","optionTranslations":"Câu hỏi: Khách hàng gặp vấn đề gì?\n(A) Anh ấy nhận được ghế sai màu.\n(B) Đơn hàng của anh ấy đến muộn.\n(C) Chỉ một phần đơn hàng được giao.\n(D) Ghế đắt hơn giá quảng cáo.","explanation":"Đáp án đúng: C. Người đàn ông nói: “I ordered a set of four dining chairs last week, but only two arrived.” Anh ấy đặt bốn chiếc nhưng chỉ nhận hai. Không có việc nhận sai màu, giao muộn hay giá cao hơn quảng cáo, nên A, B, D sai.","hintWords":["ordered","four","dining","chairs","last"],"keyVocab":[{"word":"dining chair","meaning":"ghế ăn"},{"word":"damaged","meaning":"bị hư hỏng"},{"word":"order number","meaning":"mã đơn hàng"}],"practiceOptions":[{"key":"A","text":"He received the wrong color chairs.","correct":false},{"key":"B","text":"His order arrived late.","correct":false},{"key":"C","text":"Only part of his order was delivered.","correct":true},{"key":"D","text":"The chairs were more expensive than advertised.","correct":false}]},{"id":"ets-orig-test-2-q60","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 60 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What does the woman offer to do?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g10.mp3","audioText":"I ordered a set of four dining chairs last week, but only two arrived. The box was damaged on one side.\nI'm sorry about that. Could you give me your order number?\nIt's 48217. I need the other two chairs before my parents visit on the twentieth.\nLet me check the stock... We have the same model in walnut, but not in oak. Would you accept walnut for the missing chairs?\nI'd prefer to keep the set matching. Is there any way to get oak?\nI can order them from our other warehouse. They should arrive in five business days.\nThat works. And what about the damaged box? Should I send it back?\nNo need. Our courier will collect it when the new chairs are delivered.","fullTranscript":"Man: I ordered a set of four dining chairs last week, but only two arrived. The box was damaged on one side. Woman: I'm sorry about that. Could you give me your order number? Man: It's 48217. I need the other two chairs before my parents visit on the twentieth. Woman: Let me check the stock... We have the same model in walnut, but not in oak. Would you accept walnut for the missing chairs? Man: I'd prefer to keep the set matching. Is there any way to get oak? Woman: I can order them from our other warehouse. They should arrive in five business days. Man: That works. And what about the damaged box? Should I send it back? Woman: No need. Our courier will collect it when the new chairs are delivered.","vietnamese":"Câu hỏi: Người phụ nữ đề nghị làm gì?\n(A) Đặt hai chiếc ghế còn thiếu từ kho khác\n(B) Hoàn lại toàn bộ tiền mua\n(C) Gửi một chiếc ghế trưng bày để thay thế tạm thời\n(D) Thu xếp lắp ráp miễn phí","optionTranslations":"Câu hỏi: Người phụ nữ đề nghị làm gì?\n(A) Đặt hai chiếc ghế còn thiếu từ kho khác\n(B) Hoàn lại toàn bộ tiền mua\n(C) Gửi một chiếc ghế trưng bày để thay thế tạm thời\n(D) Thu xếp lắp ráp miễn phí","explanation":"Đáp án đúng: A. Người phụ nữ nói: “I can order them from our other warehouse. They should arrive in five business days.” Bà ấy có đề nghị mẫu walnut nhưng khách từ chối, và đó không phải phương án cuối cùng; không có hoàn tiền, gửi ghế trưng bày hay lắp ráp miễn phí, nên B, C, D sai.","hintWords":["ordered","four","dining","chairs","last"],"keyVocab":[{"word":"stock","meaning":"hàng tồn kho"},{"word":"walnut","meaning":"gỗ óc chó"},{"word":"warehouse","meaning":"nhà kho"}],"practiceOptions":[{"key":"A","text":"Order the missing chairs from another warehouse","correct":true},{"key":"B","text":"Refund the full purchase price","correct":false},{"key":"C","text":"Sending a floor model as a temporary replacement","correct":false},{"key":"D","text":"Arrange free assembly","correct":false}]},{"id":"ets-orig-test-2-q61","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 61 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What does the woman say about the damaged box?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g10.mp3","audioText":"I ordered a set of four dining chairs last week, but only two arrived. The box was damaged on one side.\nI'm sorry about that. Could you give me your order number?\nIt's 48217. I need the other two chairs before my parents visit on the twentieth.\nLet me check the stock... We have the same model in walnut, but not in oak. Would you accept walnut for the missing chairs?\nI'd prefer to keep the set matching. Is there any way to get oak?\nI can order them from our other warehouse. They should arrive in five business days.\nThat works. And what about the damaged box? Should I send it back?\nNo need. Our courier will collect it when the new chairs are delivered.","fullTranscript":"Man: I ordered a set of four dining chairs last week, but only two arrived. The box was damaged on one side. Woman: I'm sorry about that. Could you give me your order number? Man: It's 48217. I need the other two chairs before my parents visit on the twentieth. Woman: Let me check the stock... We have the same model in walnut, but not in oak. Would you accept walnut for the missing chairs? Man: I'd prefer to keep the set matching. Is there any way to get oak? Woman: I can order them from our other warehouse. They should arrive in five business days. Man: That works. And what about the damaged box? Should I send it back? Woman: No need. Our courier will collect it when the new chairs are delivered.","vietnamese":"Câu hỏi: Người phụ nữ nói gì về chiếc hộp bị hỏng?\n(A) Khách hàng nên mang nó trả lại cửa hàng.\n(B) Nhân viên giao hàng sẽ thu gom nó cùng lúc giao ghế mới.\n(C) Nó phải được chụp ảnh để làm bảo hiểm.\n(D) Nó sẽ được thay thế riêng.","optionTranslations":"Câu hỏi: Người phụ nữ nói gì về chiếc hộp bị hỏng?\n(A) Khách hàng nên mang nó trả lại cửa hàng.\n(B) Nhân viên giao hàng sẽ thu gom nó cùng lúc giao ghế mới.\n(C) Nó phải được chụp ảnh để làm bảo hiểm.\n(D) Nó sẽ được thay thế riêng.","explanation":"Đáp án đúng: B. Người phụ nữ nói: “No need. Our courier will collect it when the new chairs are delivered.” Không cần khách mang trả, chụp ảnh hay thay hộp riêng, nên A, C, D sai.","hintWords":["ordered","four","dining","chairs","last"],"keyVocab":[{"word":"courier","meaning":"nhân viên giao nhận"},{"word":"collect","meaning":"thu gom, lấy về"},{"word":"assembly","meaning":"việc lắp ráp"}],"practiceOptions":[{"key":"A","text":"The customer should return it to a store.","correct":false},{"key":"B","text":"A courier will collect it with the delivery.","correct":true},{"key":"C","text":"It must be photographed for insurance.","correct":false},{"key":"D","text":"It will be replaced separately.","correct":false}]},{"id":"ets-orig-test-2-q62","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 62 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"Why does the training need to take place as scheduled?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g11.mp3","audioText":"The safety training for the new warehouse staff is scheduled for Monday, but the instructor just called in sick.\nWe can't postpone it. The audit is on Wednesday, and everyone needs to be certified before then.\nCould we use the online module instead? It covers the same material and takes about two hours.\nThe online module is fine for the written part, but they also need hands-on practice with the forklift.\nI can lead that session myself. I have the trainer certification.\nPerfect. I'll reserve the training room and send the online link to the group this afternoon.\nMake sure they finish the module before they come. Otherwise, we'll lose time.\nI'll tell them it's due by Sunday evening.","fullTranscript":"Man: The safety training for the new warehouse staff is scheduled for Monday, but the instructor just called in sick. Woman: We can't postpone it. The audit is on Wednesday, and everyone needs to be certified before then. Man: Could we use the online module instead? It covers the same material and takes about two hours. Woman: The online module is fine for the written part, but they also need hands-on practice with the forklift. Man: I can lead that session myself. I have the trainer certification. Woman: Perfect. I'll reserve the training room and send the online link to the group this afternoon. Man: Make sure they finish the module before they come. Otherwise, we'll lose time. Woman: I'll tell them it's due by Sunday evening.","vietnamese":"Câu hỏi: Tại sao buổi đào tạo phải diễn ra đúng lịch?\n(A) Giảng viên sắp rời công ty.\n(B) Nhà kho khai trương vào thứ Hai.\n(C) Nhân viên đã yêu cầu làm thêm giờ.\n(D) Một cuộc kiểm toán được lên lịch vào thứ Tư.","optionTranslations":"Câu hỏi: Tại sao buổi đào tạo phải diễn ra đúng lịch?\n(A) Giảng viên sắp rời công ty.\n(B) Nhà kho khai trương vào thứ Hai.\n(C) Nhân viên đã yêu cầu làm thêm giờ.\n(D) Một cuộc kiểm toán được lên lịch vào thứ Tư.","explanation":"Đáp án đúng: D. Người phụ nữ nói: “We can't postpone it. The audit is on Wednesday, and everyone needs to be certified before then.” Giảng viên chỉ gọi báo ốm chứ không rời công ty, nên A sai; không có việc nhà kho khai trương hay nhân viên xin làm thêm giờ, nên B và C sai.","hintWords":["safety","training","warehouse","staff","scheduled"],"keyVocab":[{"word":"audit","meaning":"cuộc kiểm toán, kiểm tra"},{"word":"certify","meaning":"chứng nhận"},{"word":"postpone","meaning":"hoãn"},{"word":"safety training","meaning":"huấn luyện an toàn"}],"practiceOptions":[{"key":"A","text":"The instructor is leaving the company.","correct":false},{"key":"B","text":"The warehouse opens on Monday.","correct":false},{"key":"C","text":"The staff have requested overtime.","correct":false},{"key":"D","text":"An audit is scheduled for Wednesday.","correct":true}]},{"id":"ets-orig-test-2-q63","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 63 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What does the woman say the online module cannot replace?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g11.mp3","audioText":"The safety training for the new warehouse staff is scheduled for Monday, but the instructor just called in sick.\nWe can't postpone it. The audit is on Wednesday, and everyone needs to be certified before then.\nCould we use the online module instead? It covers the same material and takes about two hours.\nThe online module is fine for the written part, but they also need hands-on practice with the forklift.\nI can lead that session myself. I have the trainer certification.\nPerfect. I'll reserve the training room and send the online link to the group this afternoon.\nMake sure they finish the module before they come. Otherwise, we'll lose time.\nI'll tell them it's due by Sunday evening.","fullTranscript":"Man: The safety training for the new warehouse staff is scheduled for Monday, but the instructor just called in sick. Woman: We can't postpone it. The audit is on Wednesday, and everyone needs to be certified before then. Man: Could we use the online module instead? It covers the same material and takes about two hours. Woman: The online module is fine for the written part, but they also need hands-on practice with the forklift. Man: I can lead that session myself. I have the trainer certification. Woman: Perfect. I'll reserve the training room and send the online link to the group this afternoon. Man: Make sure they finish the module before they come. Otherwise, we'll lose time. Woman: I'll tell them it's due by Sunday evening.","vietnamese":"Câu hỏi: Người phụ nữ nói mô-đun trực tuyến không thể thay thế điều gì?\n(A) Bài kiểm tra viết\n(B) Phần giới thiệu của giảng viên\n(C) Thực hành trực tiếp với xe nâng\n(D) Video an toàn","optionTranslations":"Câu hỏi: Người phụ nữ nói mô-đun trực tuyến không thể thay thế điều gì?\n(A) Bài kiểm tra viết\n(B) Phần giới thiệu của giảng viên\n(C) Thực hành trực tiếp với xe nâng\n(D) Video an toàn","explanation":"Đáp án đúng: C. Người phụ nữ nói: “The online module is fine for the written part, but they also need hands-on practice with the forklift.” Như vậy phần viết có thể học trực tuyến, còn thực hành xe nâng thì không, nên A sai và C đúng. Không có phần giới thiệu hay video an toàn nào được nhắc đến, nên B và D sai.","hintWords":["safety","training","warehouse","staff","scheduled"],"keyVocab":[{"word":"module","meaning":"mô-đun, bài học"},{"word":"hands-on","meaning":"thực hành trực tiếp"},{"word":"forklift","meaning":"xe nâng"},{"word":"written","meaning":"bằng văn bản"}],"practiceOptions":[{"key":"A","text":"The written test","correct":false},{"key":"B","text":"The instructor's introduction","correct":false},{"key":"C","text":"Hands-on forklift practice","correct":true},{"key":"D","text":"The safety video","correct":false}]},{"id":"ets-orig-test-2-q64","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 64 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What will the man do?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g11.mp3","audioText":"The safety training for the new warehouse staff is scheduled for Monday, but the instructor just called in sick.\nWe can't postpone it. The audit is on Wednesday, and everyone needs to be certified before then.\nCould we use the online module instead? It covers the same material and takes about two hours.\nThe online module is fine for the written part, but they also need hands-on practice with the forklift.\nI can lead that session myself. I have the trainer certification.\nPerfect. I'll reserve the training room and send the online link to the group this afternoon.\nMake sure they finish the module before they come. Otherwise, we'll lose time.\nI'll tell them it's due by Sunday evening.","fullTranscript":"Man: The safety training for the new warehouse staff is scheduled for Monday, but the instructor just called in sick. Woman: We can't postpone it. The audit is on Wednesday, and everyone needs to be certified before then. Man: Could we use the online module instead? It covers the same material and takes about two hours. Woman: The online module is fine for the written part, but they also need hands-on practice with the forklift. Man: I can lead that session myself. I have the trainer certification. Woman: Perfect. I'll reserve the training room and send the online link to the group this afternoon. Man: Make sure they finish the module before they come. Otherwise, we'll lose time. Woman: I'll tell them it's due by Sunday evening.","vietnamese":"Câu hỏi: Người đàn ông sẽ làm gì?\n(A) Dẫn buổi thực hành\n(B) Hoãn cuộc kiểm toán\n(C) Liên hệ giảng viên\n(D) Đặt phòng đào tạo","optionTranslations":"Câu hỏi: Người đàn ông sẽ làm gì?\n(A) Dẫn buổi thực hành\n(B) Hoãn cuộc kiểm toán\n(C) Liên hệ giảng viên\n(D) Đặt phòng đào tạo","explanation":"Đáp án đúng: A. Người đàn ông nói: “I can lead that session myself. I have the trainer certification.” Anh ấy sẽ phụ trách phần thực hành. Người phụ nữ mới là người đặt phòng và gửi link, nên D sai; không ai hoãn kiểm toán hay yêu cầu anh ấy gọi giảng viên, nên B và C sai.","hintWords":["safety","training","warehouse","staff","scheduled"],"keyVocab":[{"word":"session","meaning":"buổi học, buổi thực hành"},{"word":"certification","meaning":"chứng chỉ"},{"word":"reserve","meaning":"đặt trước"}],"practiceOptions":[{"key":"A","text":"Lead the hands-on session","correct":true},{"key":"B","text":"Postpone the audit","correct":false},{"key":"C","text":"Contact the instructor","correct":false},{"key":"D","text":"Reserve the training room","correct":false}]},{"id":"ets-orig-test-2-q65","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 65 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What does the woman say is missing from the application?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g12.mp3","audioText":"Mr. Patel, I've reviewed your application for the equipment loan. The amount you requested is fifty thousand dollars.\nThat's right. We need two new ovens for the bakery, and the installation is included in that figure.\nYour revenue has grown steadily, but the bank usually asks for two years of financial statements. You've only provided last year's.\nMy accountant has the previous year's records. I can have them sent over this afternoon.\nGood. We'll also need a list of the equipment and a quote from the supplier.\nI have the quote. I'll ask the supplier to break down the installation cost separately. Is there anything I can do to speed up the review?\nThat would help. As for speeding things up, the review usually takes about ten business days, so submit the documents together in one email rather than sending them one at a time.","fullTranscript":"Woman: Mr. Patel, I've reviewed your application for the equipment loan. The amount you requested is fifty thousand dollars. Man: That's right. We need two new ovens for the bakery, and the installation is included in that figure. Woman: Your revenue has grown steadily, but the bank usually asks for two years of financial statements. You've only provided last year's. Man: My accountant has the previous year's records. I can have them sent over this afternoon. Woman: Good. We'll also need a list of the equipment and a quote from the supplier. Man: I have the quote. I'll ask the supplier to break down the installation cost separately. Is there anything I can do to speed up the review? Woman: That would help. As for speeding things up, the review usually takes about ten business days, so submit the documents together in one email rather than sending them one at a time.","vietnamese":"Câu hỏi: Người phụ nữ nói hồ sơ còn thiếu gì?\n(A) Báo cáo tài chính của năm trước\n(B) Một bản sao giấy phép kinh doanh\n(C) Thông tin liên hệ của nhà cung cấp\n(D) Mô tả về tiệm bánh","optionTranslations":"Câu hỏi: Người phụ nữ nói hồ sơ còn thiếu gì?\n(A) Báo cáo tài chính của năm trước\n(B) Một bản sao giấy phép kinh doanh\n(C) Thông tin liên hệ của nhà cung cấp\n(D) Mô tả về tiệm bánh","explanation":"Đáp án đúng: A. Người phụ nữ nói: “the bank usually asks for two years of financial statements. You've only provided last year's.” Như vậy hồ sơ thiếu báo cáo tài chính của năm trước. Không có giấy phép kinh doanh, thông tin liên hệ hay bản mô tả tiệm bánh nào được nhắc đến, nên B, C, D sai.","hintWords":["woman","patel","reviewed","your","application"],"keyVocab":[{"word":"loan","meaning":"khoản vay"},{"word":"financial statement","meaning":"báo cáo tài chính"},{"word":"revenue","meaning":"doanh thu"},{"word":"accountant","meaning":"kế toán viên"}],"practiceOptions":[{"key":"A","text":"The previous year's financial statements","correct":true},{"key":"B","text":"A copy of the business license","correct":false},{"key":"C","text":"The supplier's contact information","correct":false},{"key":"D","text":"A description of the bakery","correct":false}]},{"id":"ets-orig-test-2-q66","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 66 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What will the man ask the supplier to do?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g12.mp3","audioText":"Mr. Patel, I've reviewed your application for the equipment loan. The amount you requested is fifty thousand dollars.\nThat's right. We need two new ovens for the bakery, and the installation is included in that figure.\nYour revenue has grown steadily, but the bank usually asks for two years of financial statements. You've only provided last year's.\nMy accountant has the previous year's records. I can have them sent over this afternoon.\nGood. We'll also need a list of the equipment and a quote from the supplier.\nI have the quote. I'll ask the supplier to break down the installation cost separately. Is there anything I can do to speed up the review?\nThat would help. As for speeding things up, the review usually takes about ten business days, so submit the documents together in one email rather than sending them one at a time.","fullTranscript":"Woman: Mr. Patel, I've reviewed your application for the equipment loan. The amount you requested is fifty thousand dollars. Man: That's right. We need two new ovens for the bakery, and the installation is included in that figure. Woman: Your revenue has grown steadily, but the bank usually asks for two years of financial statements. You've only provided last year's. Man: My accountant has the previous year's records. I can have them sent over this afternoon. Woman: Good. We'll also need a list of the equipment and a quote from the supplier. Man: I have the quote. I'll ask the supplier to break down the installation cost separately. Is there anything I can do to speed up the review? Woman: That would help. As for speeding things up, the review usually takes about ten business days, so submit the documents together in one email rather than sending them one at a time.","vietnamese":"Câu hỏi: Người đàn ông sẽ yêu cầu nhà cung cấp làm gì?\n(A) Giảm giá lò nướng\n(B) Tách chi phí lắp đặt khỏi chi phí thiết bị\n(C) Giao lò nướng sớm hơn\n(D) Cung cấp bảo hành dài hơn","optionTranslations":"Câu hỏi: Người đàn ông sẽ yêu cầu nhà cung cấp làm gì?\n(A) Giảm giá lò nướng\n(B) Tách chi phí lắp đặt khỏi chi phí thiết bị\n(C) Giao lò nướng sớm hơn\n(D) Cung cấp bảo hành dài hơn","explanation":"Đáp án đúng: B. Người đàn ông nói: “I'll ask the supplier to break down the installation cost separately.” Anh ấy muốn tách riêng chi phí lắp đặt. Không có yêu cầu giảm giá, giao sớm hay bảo hành dài hơn, nên A, C, D sai.","hintWords":["woman","patel","reviewed","your","application"],"keyVocab":[{"word":"quote","meaning":"báo giá"},{"word":"installation","meaning":"việc lắp đặt"},{"word":"break down","meaning":"phân tách, phân tích"},{"word":"supplier","meaning":"nhà cung cấp"}],"practiceOptions":[{"key":"A","text":"Lower the price of the ovens","correct":false},{"key":"B","text":"Separate the installation cost from the equipment cost","correct":true},{"key":"C","text":"Deliver the ovens earlier","correct":false},{"key":"D","text":"Provide a longer warranty","correct":false}]},{"id":"ets-orig-test-2-q67","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 67 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What does the woman recommend?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g12.mp3","audioText":"Mr. Patel, I've reviewed your application for the equipment loan. The amount you requested is fifty thousand dollars.\nThat's right. We need two new ovens for the bakery, and the installation is included in that figure.\nYour revenue has grown steadily, but the bank usually asks for two years of financial statements. You've only provided last year's.\nMy accountant has the previous year's records. I can have them sent over this afternoon.\nGood. We'll also need a list of the equipment and a quote from the supplier.\nI have the quote. I'll ask the supplier to break down the installation cost separately. Is there anything I can do to speed up the review?\nThat would help. As for speeding things up, the review usually takes about ten business days, so submit the documents together in one email rather than sending them one at a time.","fullTranscript":"Woman: Mr. Patel, I've reviewed your application for the equipment loan. The amount you requested is fifty thousand dollars. Man: That's right. We need two new ovens for the bakery, and the installation is included in that figure. Woman: Your revenue has grown steadily, but the bank usually asks for two years of financial statements. You've only provided last year's. Man: My accountant has the previous year's records. I can have them sent over this afternoon. Woman: Good. We'll also need a list of the equipment and a quote from the supplier. Man: I have the quote. I'll ask the supplier to break down the installation cost separately. Is there anything I can do to speed up the review? Woman: That would help. As for speeding things up, the review usually takes about ten business days, so submit the documents together in one email rather than sending them one at a time.","vietnamese":"Câu hỏi: Người phụ nữ khuyến nghị điều gì?\n(A) Xin một khoản vay lớn hơn\n(B) Chờ đến năm sau\n(C) Đến ngân hàng trực tiếp\n(D) Gửi tất cả tài liệu trong một email","optionTranslations":"Câu hỏi: Người phụ nữ khuyến nghị điều gì?\n(A) Xin một khoản vay lớn hơn\n(B) Chờ đến năm sau\n(C) Đến ngân hàng trực tiếp\n(D) Gửi tất cả tài liệu trong một email","explanation":"Đáp án đúng: D. Người phụ nữ nói: “Submit the documents together in one email rather than sending them one at a time.” Bà ấy muốn nhận đủ hồ sơ trong một lần để xử lý nhanh. Không có đề nghị vay thêm, chờ sang năm hay đến ngân hàng, nên A, B, C sai.","hintWords":["woman","patel","reviewed","your","application"],"keyVocab":[{"word":"submit","meaning":"nộp"},{"word":"review","meaning":"việc xem xét"},{"word":"business day","meaning":"ngày làm việc"}],"practiceOptions":[{"key":"A","text":"Applying for a larger loan","correct":false},{"key":"B","text":"Waiting until next year","correct":false},{"key":"C","text":"Visiting the bank in person","correct":false},{"key":"D","text":"Sending all the documents in one email","correct":true}]},{"id":"ets-orig-test-2-q68","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 68 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What is the man trying to do?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g13.mp3","audioText":"I'm planning the sales conference for October, and I need to confirm the venue by Friday.\nHave you compared the two hotels we discussed?\nYes. The Grandview has a larger ballroom, but it's fully booked on the eighth.\nBut the eighth is the only date the keynote speaker can attend.\nI know. The Riverside Hotel is available, but they require a deposit of 30 percent instead of 10.\nThe deposit is higher, but their room rate is lower. Over three days, we'd still save about two thousand dollars.\nThat's true. Should I ask them to hold the date while we finalize the menu?\nYes, and ask whether the rate includes the audio equipment. We spent a lot on rentals last year.","fullTranscript":"Man: I'm planning the sales conference for October, and I need to confirm the venue by Friday. Woman: Have you compared the two hotels we discussed? Man: Yes. The Grandview has a larger ballroom, but it's fully booked on the eighth. Woman: But the eighth is the only date the keynote speaker can attend. Man: I know. The Riverside Hotel is available, but they require a deposit of 30 percent instead of 10. Woman: The deposit is higher, but their room rate is lower. Over three days, we'd still save about two thousand dollars. Man: That's true. Should I ask them to hold the date while we finalize the menu? Woman: Yes, and ask whether the rate includes the audio equipment. We spent a lot on rentals last year.","vietnamese":"Câu hỏi: Người đàn ông đang cố gắng làm gì?\n(A) Thuê diễn giả chính\n(B) Đổi ngày hội nghị\n(C) Chọn địa điểm cho một hội nghị\n(D) Thương lượng giá phòng thấp hơn","optionTranslations":"Câu hỏi: Người đàn ông đang cố gắng làm gì?\n(A) Thuê diễn giả chính\n(B) Đổi ngày hội nghị\n(C) Chọn địa điểm cho một hội nghị\n(D) Thương lượng giá phòng thấp hơn","explanation":"Đáp án đúng: C. Người đàn ông nói: “I'm planning the sales conference for October, and I need to confirm the venue by Friday.” Anh ấy đang so sánh hai khách sạn để chọn địa điểm. Diễn giả đã có ngày cố định, không phải đang thuê, nên A sai; ngày hội nghị không đổi, nên B sai; giá phòng của Riverside vốn đã thấp hơn, không có thương lượng, nên D sai.","hintWords":["planning","sales","conference","october","need"],"keyVocab":[{"word":"venue","meaning":"địa điểm tổ chức"},{"word":"confirm","meaning":"xác nhận"},{"word":"conference","meaning":"hội nghị"},{"word":"ballroom","meaning":"phòng khiêu vũ lớn"}],"practiceOptions":[{"key":"A","text":"Hire a keynote speaker","correct":false},{"key":"B","text":"Change the conference date","correct":false},{"key":"C","text":"Choose a venue for a conference","correct":true},{"key":"D","text":"Negotiate a lower room rate","correct":false}]},{"id":"ets-orig-test-2-q69","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 69 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What is the disadvantage of the Riverside Hotel?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g13.mp3","audioText":"I'm planning the sales conference for October, and I need to confirm the venue by Friday.\nHave you compared the two hotels we discussed?\nYes. The Grandview has a larger ballroom, but it's fully booked on the eighth.\nBut the eighth is the only date the keynote speaker can attend.\nI know. The Riverside Hotel is available, but they require a deposit of 30 percent instead of 10.\nThe deposit is higher, but their room rate is lower. Over three days, we'd still save about two thousand dollars.\nThat's true. Should I ask them to hold the date while we finalize the menu?\nYes, and ask whether the rate includes the audio equipment. We spent a lot on rentals last year.","fullTranscript":"Man: I'm planning the sales conference for October, and I need to confirm the venue by Friday. Woman: Have you compared the two hotels we discussed? Man: Yes. The Grandview has a larger ballroom, but it's fully booked on the eighth. Woman: But the eighth is the only date the keynote speaker can attend. Man: I know. The Riverside Hotel is available, but they require a deposit of 30 percent instead of 10. Woman: The deposit is higher, but their room rate is lower. Over three days, we'd still save about two thousand dollars. Man: That's true. Should I ask them to hold the date while we finalize the menu? Woman: Yes, and ask whether the rate includes the audio equipment. We spent a lot on rentals last year.","vietnamese":"Câu hỏi: Điểm bất lợi của khách sạn Riverside là gì?\n(A) Phòng tiệc của khách sạn nhỏ hơn.\n(B) Khách sạn không còn trống vào ngày mùng tám.\n(C) Giá phòng của khách sạn cao hơn.\n(D) Khách sạn yêu cầu tiền đặt cọc lớn hơn.","optionTranslations":"Câu hỏi: Điểm bất lợi của khách sạn Riverside là gì?\n(A) Phòng tiệc của khách sạn nhỏ hơn.\n(B) Khách sạn không còn trống vào ngày mùng tám.\n(C) Giá phòng của khách sạn cao hơn.\n(D) Khách sạn yêu cầu tiền đặt cọc lớn hơn.","explanation":"Đáp án đúng: D. Người đàn ông nói: “The Riverside Hotel is available, but they require a deposit of 30 percent instead of 10.” Đặt cọc 30% thay vì 10% là bất lợi. Riverside còn trống ngày mùng tám nên B sai; giá phòng thấp hơn nên C sai; phòng tiệc lớn hơn là của Grandview, không có thông tin Riverside nhỏ hơn, nên A sai.","hintWords":["planning","sales","conference","october","need"],"keyVocab":[{"word":"deposit","meaning":"tiền đặt cọc"},{"word":"fully booked","meaning":"được đặt kín"},{"word":"room rate","meaning":"giá phòng"}],"practiceOptions":[{"key":"A","text":"It has a smaller ballroom.","correct":false},{"key":"B","text":"It is unavailable on the eighth.","correct":false},{"key":"C","text":"Its room rate is higher.","correct":false},{"key":"D","text":"It requires a larger deposit.","correct":true}]},{"id":"ets-orig-test-2-q70","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 3","partNumber":3,"level":"ETS Format","title":"Test 02 • Câu 70 (Part 3: Đoạn hội thoại (Short Conversations))","questionPrompt":"What does the woman want the man to ask about?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p3-g13.mp3","audioText":"I'm planning the sales conference for October, and I need to confirm the venue by Friday.\nHave you compared the two hotels we discussed?\nYes. The Grandview has a larger ballroom, but it's fully booked on the eighth.\nBut the eighth is the only date the keynote speaker can attend.\nI know. The Riverside Hotel is available, but they require a deposit of 30 percent instead of 10.\nThe deposit is higher, but their room rate is lower. Over three days, we'd still save about two thousand dollars.\nThat's true. Should I ask them to hold the date while we finalize the menu?\nYes, and ask whether the rate includes the audio equipment. We spent a lot on rentals last year.","fullTranscript":"Man: I'm planning the sales conference for October, and I need to confirm the venue by Friday. Woman: Have you compared the two hotels we discussed? Man: Yes. The Grandview has a larger ballroom, but it's fully booked on the eighth. Woman: But the eighth is the only date the keynote speaker can attend. Man: I know. The Riverside Hotel is available, but they require a deposit of 30 percent instead of 10. Woman: The deposit is higher, but their room rate is lower. Over three days, we'd still save about two thousand dollars. Man: That's true. Should I ask them to hold the date while we finalize the menu? Woman: Yes, and ask whether the rate includes the audio equipment. We spent a lot on rentals last year.","vietnamese":"Câu hỏi: Người phụ nữ muốn người đàn ông hỏi về điều gì?\n(A) Các lựa chọn thực đơn\n(B) Thiết bị âm thanh\n(C) Cơ sở đậu xe\n(D) Chính sách hủy","optionTranslations":"Câu hỏi: Người phụ nữ muốn người đàn ông hỏi về điều gì?\n(A) Các lựa chọn thực đơn\n(B) Thiết bị âm thanh\n(C) Cơ sở đậu xe\n(D) Chính sách hủy","explanation":"Đáp án đúng: B. Người phụ nữ nói: “ask whether the rate includes the audio equipment. We spent a lot on rentals last year.” Bà ấy muốn biết giá phòng có gồm thiết bị âm thanh không. Thực đơn đang được hoàn thiện chứ không phải điều cần hỏi khách sạn, nên A sai; không nhắc đến bãi đỗ xe hay chính sách hủy, nên C và D sai.","hintWords":["planning","sales","conference","october","need"],"keyVocab":[{"word":"audio equipment","meaning":"thiết bị âm thanh"},{"word":"rental","meaning":"việc thuê"},{"word":"finalize","meaning":"hoàn tất"},{"word":"include","meaning":"bao gồm"}],"practiceOptions":[{"key":"A","text":"The menu options","correct":false},{"key":"B","text":"The audio equipment","correct":true},{"key":"C","text":"The parking facilities","correct":false},{"key":"D","text":"The cancellation policy","correct":false}]},{"id":"ets-orig-test-2-q71","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 71 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"Why will the flight's baggage be handled at Terminal 3?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g01.mp3","audioText":"Attention passengers arriving on Flight 218 from Seoul. Because of an electrical fault in Terminal 2, baggage from this flight will be unloaded at Terminal 3, Carousel 7. Please follow the purple signs to the inter-terminal shuttle, which departs every ten minutes and takes about eight minutes. Passengers who arranged ground transportation through our partner desk should check in at the Terminal 3 arrivals hall, where staff can update their pickup times. We apologize for the inconvenience. If you left items on the aircraft, please contact the lost-and-found office before 6 p.m.","fullTranscript":"Attention passengers arriving on Flight 218 from Seoul. Because of an electrical fault in Terminal 2, baggage from this flight will be unloaded at Terminal 3, Carousel 7. Please follow the purple signs to the inter-terminal shuttle, which departs every ten minutes and takes about eight minutes. Passengers who arranged ground transportation through our partner desk should check in at the Terminal 3 arrivals hall, where staff can update their pickup times. We apologize for the inconvenience. If you left items on the aircraft, please contact the lost-and-found office before 6 p.m.","vietnamese":"Vì sao hành lý của chuyến bay sẽ được xử lý tại Nhà ga 3? — (A) Một đợt cải tạo đã lên kế hoạch (B) Một sự cố điện (C) Một cuộc kiểm tra an ninh (D) Thời tiết khắc nghiệt.","optionTranslations":"Vì sao hành lý của chuyến bay sẽ được xử lý tại Nhà ga 3? — (A) Một đợt cải tạo đã lên kế hoạch (B) Một sự cố điện (C) Một cuộc kiểm tra an ninh (D) Thời tiết khắc nghiệt.","explanation":"Đáp án B. Thông báo nêu rõ: \"Because of an electrical fault in Terminal 2, baggage from this flight will be unloaded at Terminal 3\" — hành lý được chuyển sang Nhà ga 3 do sự cố điện ở Nhà ga 2. A sai vì không có kế hoạch cải tạo nào được nhắc đến. C sai vì bài không nói đến kiểm tra an ninh. D sai vì nguyên nhân được nêu là sự cố điện, không phải thời tiết.","hintWords":["attention","passengers","arriving","flight","from"],"keyVocab":[{"word":"fault","meaning":"sự cố, lỗi"},{"word":"unload","meaning":"dỡ hàng xuống"},{"word":"carousel","meaning":"băng chuyền hành lý"},{"word":"terminal","meaning":"nhà ga"},{"word":"inconvenience","meaning":"sự bất tiện"}],"practiceOptions":[{"key":"A","text":"A scheduled renovation","correct":false},{"key":"B","text":"An electrical fault","correct":true},{"key":"C","text":"A security inspection","correct":false},{"key":"D","text":"Severe weather","correct":false}]},{"id":"ets-orig-test-2-q72","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 72 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"How often does the inter-terminal shuttle depart?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g01.mp3","audioText":"Attention passengers arriving on Flight 218 from Seoul. Because of an electrical fault in Terminal 2, baggage from this flight will be unloaded at Terminal 3, Carousel 7. Please follow the purple signs to the inter-terminal shuttle, which departs every ten minutes and takes about eight minutes. Passengers who arranged ground transportation through our partner desk should check in at the Terminal 3 arrivals hall, where staff can update their pickup times. We apologize for the inconvenience. If you left items on the aircraft, please contact the lost-and-found office before 6 p.m.","fullTranscript":"Attention passengers arriving on Flight 218 from Seoul. Because of an electrical fault in Terminal 2, baggage from this flight will be unloaded at Terminal 3, Carousel 7. Please follow the purple signs to the inter-terminal shuttle, which departs every ten minutes and takes about eight minutes. Passengers who arranged ground transportation through our partner desk should check in at the Terminal 3 arrivals hall, where staff can update their pickup times. We apologize for the inconvenience. If you left items on the aircraft, please contact the lost-and-found office before 6 p.m.","vietnamese":"Xe đưa đón giữa các nhà ga khởi hành bao lâu một lần? — (A) Mười phút một lần (B) Mười lăm phút một lần (C) Hai mươi phút một lần (D) Ba mươi phút một lần.","optionTranslations":"Xe đưa đón giữa các nhà ga khởi hành bao lâu một lần? — (A) Mười phút một lần (B) Mười lăm phút một lần (C) Hai mươi phút một lần (D) Ba mươi phút một lần.","explanation":"Đáp án A. Bài nói cho biết shuttle \"departs every ten minutes and takes about eight minutes\" — cứ mười phút một chuyến; tám phút là thời gian di chuyển chứ không phải tần suất. B, C và D đều là những con số không xuất hiện trong bài.","hintWords":["attention","passengers","arriving","flight","from"],"keyVocab":[{"word":"depart","meaning":"khởi hành"},{"word":"shuttle","meaning":"xe đưa đón"},{"word":"inter-terminal","meaning":"liên nhà ga"},{"word":"arrivals hall","meaning":"sảnh đến"}],"practiceOptions":[{"key":"A","text":"Every ten minutes","correct":true},{"key":"B","text":"Every fifteen minutes","correct":false},{"key":"C","text":"Every twenty minutes","correct":false},{"key":"D","text":"Every thirty minutes","correct":false}]},{"id":"ets-orig-test-2-q73","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 73 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What should passengers with arranged ground transportation do?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g01.mp3","audioText":"Attention passengers arriving on Flight 218 from Seoul. Because of an electrical fault in Terminal 2, baggage from this flight will be unloaded at Terminal 3, Carousel 7. Please follow the purple signs to the inter-terminal shuttle, which departs every ten minutes and takes about eight minutes. Passengers who arranged ground transportation through our partner desk should check in at the Terminal 3 arrivals hall, where staff can update their pickup times. We apologize for the inconvenience. If you left items on the aircraft, please contact the lost-and-found office before 6 p.m.","fullTranscript":"Attention passengers arriving on Flight 218 from Seoul. Because of an electrical fault in Terminal 2, baggage from this flight will be unloaded at Terminal 3, Carousel 7. Please follow the purple signs to the inter-terminal shuttle, which departs every ten minutes and takes about eight minutes. Passengers who arranged ground transportation through our partner desk should check in at the Terminal 3 arrivals hall, where staff can update their pickup times. We apologize for the inconvenience. If you left items on the aircraft, please contact the lost-and-found office before 6 p.m.","vietnamese":"Hành khách đã sắp xếp phương tiện đưa đón nên làm gì? — (A) Gọi ngay cho tài xế (B) Chờ ở băng chuyền số 7 (C) Làm thủ tục tại sảnh đến Nhà ga 3 (D) Bắt taxi đến Nhà ga 2.","optionTranslations":"Hành khách đã sắp xếp phương tiện đưa đón nên làm gì? — (A) Gọi ngay cho tài xế (B) Chờ ở băng chuyền số 7 (C) Làm thủ tục tại sảnh đến Nhà ga 3 (D) Bắt taxi đến Nhà ga 2.","explanation":"Đáp án C. Bài nói hướng dẫn: \"Passengers who arranged ground transportation through our partner desk should check in at the Terminal 3 arrivals hall, where staff can update their pickup times.\" A sai vì không có yêu cầu gọi tài xế. B sai vì băng chuyền 7 chỉ là nơi nhận hành lý. D sai vì hành khách đang được hướng dẫn đến Nhà ga 3, không phải quay lại Nhà ga 2.","hintWords":["attention","passengers","arriving","flight","from"],"keyVocab":[{"word":"ground transportation","meaning":"phương tiện đưa đón trên mặt đất"},{"word":"pickup","meaning":"việc đón khách"},{"word":"staff","meaning":"nhân viên"},{"word":"lost-and-found","meaning":"nơi lưu giữ đồ thất lạc"}],"practiceOptions":[{"key":"A","text":"Call their driver immediately","correct":false},{"key":"B","text":"Wait at Carousel 7","correct":false},{"key":"C","text":"Check in at the Terminal 3 arrivals hall","correct":true},{"key":"D","text":"Take a taxi to Terminal 2","correct":false}]},{"id":"ets-orig-test-2-q74","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 74 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What is the purpose of the call?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g02.mp3","audioText":"Hello, this is Marcus from Northline Construction. I'm calling with an update on the Riverside office project. The steel beams we ordered will arrive on Tuesday rather than Friday, so we can start framing two days early. However, the city has not yet approved the revised electrical plan, and we cannot close up the walls until an inspector signs off. Could you send the updated drawings to the inspection office today? Also, please confirm whether the client wants the lobby windows tinted. I'll be on site until four, but email is best after that. Thanks.","fullTranscript":"Hello, this is Marcus from Northline Construction. I'm calling with an update on the Riverside office project. The steel beams we ordered will arrive on Tuesday rather than Friday, so we can start framing two days early. However, the city has not yet approved the revised electrical plan, and we cannot close up the walls until an inspector signs off. Could you send the updated drawings to the inspection office today? Also, please confirm whether the client wants the lobby windows tinted. I'll be on site until four, but email is best after that. Thanks.","vietnamese":"Mục đích của cuộc gọi là gì? — (A) Cung cấp thông tin cập nhật về dự án (B) Yêu cầu một nhà cung cấp mới (C) Báo cáo tai nạn lao động (D) Lên lịch họp với khách hàng.","optionTranslations":"Mục đích của cuộc gọi là gì? — (A) Cung cấp thông tin cập nhật về dự án (B) Yêu cầu một nhà cung cấp mới (C) Báo cáo tai nạn lao động (D) Lên lịch họp với khách hàng.","explanation":"Đáp án A. Marcus mở đầu bằng: \"I'm calling with an update on the Riverside office project.\" B sai vì anh ấy không đề nghị nhà cung cấp mới; dầm thép đã được đặt. C sai vì không có tai nạn nào. D sai vì cuộc gọi không nhằm lên lịch họp mà để trao đổi tiến độ và đề nghị gửi bản vẽ.","hintWords":["hello","this","marcus","from","northline"],"keyVocab":[{"word":"update","meaning":"thông tin cập nhật"},{"word":"construction","meaning":"xây dựng"},{"word":"beam","meaning":"dầm (thép)"},{"word":"framing","meaning":"việc đóng khung kết cấu"},{"word":"revised","meaning":"đã được sửa đổi"}],"practiceOptions":[{"key":"A","text":"To provide a project update","correct":true},{"key":"B","text":"To request a new supplier","correct":false},{"key":"C","text":"To report a workplace injury","correct":false},{"key":"D","text":"To schedule a client meeting","correct":false}]},{"id":"ets-orig-test-2-q75","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 75 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What must happen before the walls can be closed up?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g02.mp3","audioText":"Hello, this is Marcus from Northline Construction. I'm calling with an update on the Riverside office project. The steel beams we ordered will arrive on Tuesday rather than Friday, so we can start framing two days early. However, the city has not yet approved the revised electrical plan, and we cannot close up the walls until an inspector signs off. Could you send the updated drawings to the inspection office today? Also, please confirm whether the client wants the lobby windows tinted. I'll be on site until four, but email is best after that. Thanks.","fullTranscript":"Hello, this is Marcus from Northline Construction. I'm calling with an update on the Riverside office project. The steel beams we ordered will arrive on Tuesday rather than Friday, so we can start framing two days early. However, the city has not yet approved the revised electrical plan, and we cannot close up the walls until an inspector signs off. Could you send the updated drawings to the inspection office today? Also, please confirm whether the client wants the lobby windows tinted. I'll be on site until four, but email is best after that. Thanks.","vietnamese":"Điều gì phải xảy ra trước khi các bức tường được đóng lại? — (A) Dầm thép phải được giao đến (B) Khách hàng phải duyệt ngân sách (C) Cửa sổ sảnh phải được lắp đặt (D) Thanh tra phải duyệt kế hoạch điện.","optionTranslations":"Điều gì phải xảy ra trước khi các bức tường được đóng lại? — (A) Dầm thép phải được giao đến (B) Khách hàng phải duyệt ngân sách (C) Cửa sổ sảnh phải được lắp đặt (D) Thanh tra phải duyệt kế hoạch điện.","explanation":"Đáp án D. Bài nói nêu: \"the city has not yet approved the revised electrical plan, and we cannot close up the walls until an inspector signs off\" — phải có thanh tra chấp thuận kế hoạch điện sửa đổi. A sai vì dầm thép đến sớm chỉ giúp bắt đầu đóng khung sớm hơn. B và C không được nêu là điều kiện để đóng tường.","hintWords":["hello","this","marcus","from","northline"],"keyVocab":[{"word":"approve","meaning":"phê duyệt"},{"word":"inspector","meaning":"thanh tra viên"},{"word":"sign off","meaning":"ký duyệt, chấp thuận"},{"word":"electrical plan","meaning":"kế hoạch hệ thống điện"}],"practiceOptions":[{"key":"A","text":"The steel beams must arrive.","correct":false},{"key":"B","text":"The client must approve the budget.","correct":false},{"key":"C","text":"The lobby windows must be installed.","correct":false},{"key":"D","text":"An inspector must approve the electrical plan.","correct":true}]},{"id":"ets-orig-test-2-q76","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 76 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What does the speaker ask the listener to confirm?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g02.mp3","audioText":"Hello, this is Marcus from Northline Construction. I'm calling with an update on the Riverside office project. The steel beams we ordered will arrive on Tuesday rather than Friday, so we can start framing two days early. However, the city has not yet approved the revised electrical plan, and we cannot close up the walls until an inspector signs off. Could you send the updated drawings to the inspection office today? Also, please confirm whether the client wants the lobby windows tinted. I'll be on site until four, but email is best after that. Thanks.","fullTranscript":"Hello, this is Marcus from Northline Construction. I'm calling with an update on the Riverside office project. The steel beams we ordered will arrive on Tuesday rather than Friday, so we can start framing two days early. However, the city has not yet approved the revised electrical plan, and we cannot close up the walls until an inspector signs off. Could you send the updated drawings to the inspection office today? Also, please confirm whether the client wants the lobby windows tinted. I'll be on site until four, but email is best after that. Thanks.","vietnamese":"Người nói đề nghị người nghe xác nhận điều gì? — (A) Liệu việc đóng khung kết cấu có nên bắt đầu sớm không (B) Liệu khách hàng có muốn dán phim màu cho cửa sổ sảnh không (C) Liệu văn phòng thanh tra có mở cửa không (D) Liệu đơn đặt dầm thép có nên bị hủy không.","optionTranslations":"Người nói đề nghị người nghe xác nhận điều gì? — (A) Liệu việc đóng khung kết cấu có nên bắt đầu sớm không (B) Liệu khách hàng có muốn dán phim màu cho cửa sổ sảnh không (C) Liệu văn phòng thanh tra có mở cửa không (D) Liệu đơn đặt dầm thép có nên bị hủy không.","explanation":"Đáp án B. Người nói đề nghị: \"please confirm whether the client wants the lobby windows tinted\" — xác nhận khách có muốn cửa sổ sảnh được dán phim màu hay không. A sai vì việc đóng khung đã được quyết định bắt đầu sớm, không cần xác nhận. C sai vì anh ấy chỉ nhờ gửi bản vẽ đến văn phòng thanh tra. D sai vì không có ý định hủy đơn thép.","hintWords":["hello","this","marcus","from","northline"],"keyVocab":[{"word":"tint","meaning":"dán phim màu, làm tối màu"},{"word":"confirm","meaning":"xác nhận"},{"word":"lobby","meaning":"sảnh"},{"word":"on site","meaning":"tại công trường"}],"practiceOptions":[{"key":"A","text":"Whether framing should begin early","correct":false},{"key":"B","text":"Whether the client wants tinted lobby windows","correct":true},{"key":"C","text":"Whether the inspection office is open","correct":false},{"key":"D","text":"Whether the steel order should be canceled","correct":false}]},{"id":"ets-orig-test-2-q77","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 77 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What is the main purpose of the advertisement?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g03.mp3","audioText":"Spring is here, and so is the biggest sale of the year at Willow Creek Garden Center. From Friday through Sunday, take thirty percent off all outdoor furniture, planters, and lighting. Members of our Green Thumb Club earn double points on every purchase and receive a free bag of potting soil with any purchase over fifty dollars. Not a member yet? Sign up at the checkout counter—it takes less than a minute, and there is no annual fee. The first fifty customers on Saturday will also receive a complimentary herb garden starter kit. Visit willowcreekgarden.com for directions and store hours.","fullTranscript":"Spring is here, and so is the biggest sale of the year at Willow Creek Garden Center. From Friday through Sunday, take thirty percent off all outdoor furniture, planters, and lighting. Members of our Green Thumb Club earn double points on every purchase and receive a free bag of potting soil with any purchase over fifty dollars. Not a member yet? Sign up at the checkout counter—it takes less than a minute, and there is no annual fee. The first fifty customers on Saturday will also receive a complimentary herb garden starter kit. Visit willowcreekgarden.com for directions and store hours.","vietnamese":"Mục đích chính của quảng cáo là gì? — (A) Quảng bá dịch vụ thiết kế cảnh quan (B) Giới thiệu quản lý cửa hàng mới (C) Khuyến mãi đợt giảm giá theo mùa (D) Tuyển nhân viên cho trung tâm làm vườn.","optionTranslations":"Mục đích chính của quảng cáo là gì? — (A) Quảng bá dịch vụ thiết kế cảnh quan (B) Giới thiệu quản lý cửa hàng mới (C) Khuyến mãi đợt giảm giá theo mùa (D) Tuyển nhân viên cho trung tâm làm vườn.","explanation":"Đáp án C. Quảng cáo mở đầu: \"Spring is here, and so is the biggest sale of the year at Willow Creek Garden Center\" và nêu rõ mức giảm 30% từ thứ Sáu đến Chủ nhật. A sai vì đây là cửa hàng bán đồ làm vườn, không phải dịch vụ thiết kế cảnh quan. B sai vì không có quản lý mới. D sai vì không có nội dung tuyển dụng.","hintWords":["spring","here","biggest","sale","year"],"keyVocab":[{"word":"seasonal","meaning":"theo mùa"},{"word":"promotion","meaning":"khuyến mãi"},{"word":"outdoor furniture","meaning":"đồ nội thất ngoài trời"},{"word":"planter","meaning":"chậu cây"},{"word":"loyalty program","meaning":"chương trình khách hàng thân thiết"}],"practiceOptions":[{"key":"A","text":"To promote a landscaping service","correct":false},{"key":"B","text":"To introduce a new store manager","correct":false},{"key":"C","text":"To promote a seasonal sale","correct":true},{"key":"D","text":"To recruit garden center staff","correct":false}]},{"id":"ets-orig-test-2-q78","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 78 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"According to the advertisement, what will Green Thumb Club members receive with a purchase of more than fifty dollars?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g03.mp3","audioText":"Spring is here, and so is the biggest sale of the year at Willow Creek Garden Center. From Friday through Sunday, take thirty percent off all outdoor furniture, planters, and lighting. Members of our Green Thumb Club earn double points on every purchase and receive a free bag of potting soil with any purchase over fifty dollars. Not a member yet? Sign up at the checkout counter—it takes less than a minute, and there is no annual fee. The first fifty customers on Saturday will also receive a complimentary herb garden starter kit. Visit willowcreekgarden.com for directions and store hours.","fullTranscript":"Spring is here, and so is the biggest sale of the year at Willow Creek Garden Center. From Friday through Sunday, take thirty percent off all outdoor furniture, planters, and lighting. Members of our Green Thumb Club earn double points on every purchase and receive a free bag of potting soil with any purchase over fifty dollars. Not a member yet? Sign up at the checkout counter—it takes less than a minute, and there is no annual fee. The first fifty customers on Saturday will also receive a complimentary herb garden starter kit. Visit willowcreekgarden.com for directions and store hours.","vietnamese":"Theo quảng cáo, thành viên Green Thumb Club sẽ nhận được gì khi mua hàng trên 50 đô-la? — (A) Giao hàng miễn phí (B) Một túi đất trồng miễn phí (C) Giảm giá 30% (D) Một bộ khởi đầu vườn thảo mộc miễn phí.","optionTranslations":"Theo quảng cáo, thành viên Green Thumb Club sẽ nhận được gì khi mua hàng trên 50 đô-la? — (A) Giao hàng miễn phí (B) Một túi đất trồng miễn phí (C) Giảm giá 30% (D) Một bộ khởi đầu vườn thảo mộc miễn phí.","explanation":"Đáp án B. Quảng cáo nêu thành viên \"receive a free bag of potting soil with any purchase over fifty dollars.\" A sai vì không nhắc đến giao hàng. C sai vì mức giảm 30% áp dụng cho tất cả khách trong đợt sale, không phải quà riêng khi mua trên 50 đô. D sai vì bộ vườn thảo mộc dành cho 50 khách đầu tiên vào thứ Bảy.","hintWords":["spring","here","biggest","sale","year"],"keyVocab":[{"word":"potting soil","meaning":"đất trồng cây"},{"word":"purchase","meaning":"giao dịch mua hàng"},{"word":"annual fee","meaning":"phí thường niên"},{"word":"member","meaning":"thành viên"},{"word":"checkout counter","meaning":"quầy thanh toán"}],"practiceOptions":[{"key":"A","text":"Free delivery","correct":false},{"key":"B","text":"A free bag of potting soil","correct":true},{"key":"C","text":"A thirty-percent discount","correct":false},{"key":"D","text":"A free herb garden starter kit","correct":false}]},{"id":"ets-orig-test-2-q79","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 79 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What will the first fifty customers on Saturday receive?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g03.mp3","audioText":"Spring is here, and so is the biggest sale of the year at Willow Creek Garden Center. From Friday through Sunday, take thirty percent off all outdoor furniture, planters, and lighting. Members of our Green Thumb Club earn double points on every purchase and receive a free bag of potting soil with any purchase over fifty dollars. Not a member yet? Sign up at the checkout counter—it takes less than a minute, and there is no annual fee. The first fifty customers on Saturday will also receive a complimentary herb garden starter kit. Visit willowcreekgarden.com for directions and store hours.","fullTranscript":"Spring is here, and so is the biggest sale of the year at Willow Creek Garden Center. From Friday through Sunday, take thirty percent off all outdoor furniture, planters, and lighting. Members of our Green Thumb Club earn double points on every purchase and receive a free bag of potting soil with any purchase over fifty dollars. Not a member yet? Sign up at the checkout counter—it takes less than a minute, and there is no annual fee. The first fifty customers on Saturday will also receive a complimentary herb garden starter kit. Visit willowcreekgarden.com for directions and store hours.","vietnamese":"50 khách hàng đầu tiên vào thứ Bảy sẽ nhận được gì? — (A) Một cuốn sách dạy nấu ăn miễn phí (B) Một thẻ quà tặng 10 đô-la (C) Một túi cà phê (D) Một bộ khởi đầu vườn thảo mộc miễn phí.","optionTranslations":"50 khách hàng đầu tiên vào thứ Bảy sẽ nhận được gì? — (A) Một cuốn sách dạy nấu ăn miễn phí (B) Một thẻ quà tặng 10 đô-la (C) Một túi cà phê (D) Một bộ khởi đầu vườn thảo mộc miễn phí.","explanation":"Đáp án D. Quảng cáo cho biết: \"The first fifty customers on Saturday will also receive a complimentary herb garden starter kit.\" A, B và C không xuất hiện trong bài; đây là các phương án gây nhiễu.","hintWords":["spring","here","biggest","sale","year"],"keyVocab":[{"word":"complimentary","meaning":"miễn phí, tặng kèm"},{"word":"starter kit","meaning":"bộ khởi đầu"},{"word":"herb","meaning":"thảo mộc"},{"word":"customer","meaning":"khách hàng"}],"practiceOptions":[{"key":"A","text":"A free cookbook","correct":false},{"key":"B","text":"A ten-dollar gift card","correct":false},{"key":"C","text":"A bag of coffee","correct":false},{"key":"D","text":"A complimentary herb garden starter kit","correct":true}]},{"id":"ets-orig-test-2-q80","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 80 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What should workers do before clearing a jam?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g04.mp3","audioText":"Before we begin the shift, I want to review the safety procedures for the new conveyor system. Always press the red stop button before clearing a jam, and never reach under the belt while it is moving. High-visibility vests must be worn in the loading zone at all times. If you notice a burning smell or unusual noise, shut down the line and notify the shift supervisor immediately. Emergency exits are located at the north and east walls; please keep those areas clear of pallets. We will run a short evacuation drill at 2 p.m. today, so listen for the alarm.","fullTranscript":"Before we begin the shift, I want to review the safety procedures for the new conveyor system. Always press the red stop button before clearing a jam, and never reach under the belt while it is moving. High-visibility vests must be worn in the loading zone at all times. If you notice a burning smell or unusual noise, shut down the line and notify the shift supervisor immediately. Emergency exits are located at the north and east walls; please keep those areas clear of pallets. We will run a short evacuation drill at 2 p.m. today, so listen for the alarm.","vietnamese":"Công nhân nên làm gì trước khi gỡ kẹt máy? — (A) Báo cho giám sát ca (B) Đeo găng tay bảo hộ (C) Tắt đèn băng tải (D) Nhấn nút dừng màu đỏ.","optionTranslations":"Công nhân nên làm gì trước khi gỡ kẹt máy? — (A) Báo cho giám sát ca (B) Đeo găng tay bảo hộ (C) Tắt đèn băng tải (D) Nhấn nút dừng màu đỏ.","explanation":"Đáp án D. Hướng dẫn nêu: \"Always press the red stop button before clearing a jam.\" A sai vì chỉ báo giám sát khi ngửi thấy mùi cháy hoặc nghe tiếng lạ. B sai vì bài chỉ nhắc áo phản quang, không nhắc găng tay. C sai vì không có chỉ dẫn tắt đèn băng tải.","hintWords":["before","begin","shift","want","review"],"keyVocab":[{"word":"conveyor","meaning":"băng tải"},{"word":"jam","meaning":"tình trạng kẹt máy"},{"word":"clear","meaning":"xử lý, gỡ (kẹt)"},{"word":"stop button","meaning":"nút dừng"},{"word":"supervisor","meaning":"người giám sát"}],"practiceOptions":[{"key":"A","text":"Notify the shift supervisor","correct":false},{"key":"B","text":"Put on safety gloves","correct":false},{"key":"C","text":"Turn off the conveyor lights","correct":false},{"key":"D","text":"Press the red stop button","correct":true}]},{"id":"ets-orig-test-2-q81","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 81 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"Where are the emergency exits located?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g04.mp3","audioText":"Before we begin the shift, I want to review the safety procedures for the new conveyor system. Always press the red stop button before clearing a jam, and never reach under the belt while it is moving. High-visibility vests must be worn in the loading zone at all times. If you notice a burning smell or unusual noise, shut down the line and notify the shift supervisor immediately. Emergency exits are located at the north and east walls; please keep those areas clear of pallets. We will run a short evacuation drill at 2 p.m. today, so listen for the alarm.","fullTranscript":"Before we begin the shift, I want to review the safety procedures for the new conveyor system. Always press the red stop button before clearing a jam, and never reach under the belt while it is moving. High-visibility vests must be worn in the loading zone at all times. If you notice a burning smell or unusual noise, shut down the line and notify the shift supervisor immediately. Emergency exits are located at the north and east walls; please keep those areas clear of pallets. We will run a short evacuation drill at 2 p.m. today, so listen for the alarm.","vietnamese":"Các lối thoát hiểm nằm ở đâu? — (A) Dọc theo tường phía bắc và phía đông (B) Cạnh khu vực bốc xếp (C) Bên cạnh văn phòng chính (D) Phía sau nhà ăn.","optionTranslations":"Các lối thoát hiểm nằm ở đâu? — (A) Dọc theo tường phía bắc và phía đông (B) Cạnh khu vực bốc xếp (C) Bên cạnh văn phòng chính (D) Phía sau nhà ăn.","explanation":"Đáp án A. Bài nói cho biết: \"Emergency exits are located at the north and east walls.\" B, C và D không được nhắc đến; khu bốc xếp chỉ là nơi bắt buộc mặc áo phản quang.","hintWords":["before","begin","shift","want","review"],"keyVocab":[{"word":"emergency exit","meaning":"lối thoát hiểm"},{"word":"loading zone","meaning":"khu vực bốc xếp"},{"word":"pallet","meaning":"kệ hàng, pallet"},{"word":"evacuation drill","meaning":"buổi diễn tập sơ tán"}],"practiceOptions":[{"key":"A","text":"Along the north and east walls","correct":true},{"key":"B","text":"Next to the loading zone","correct":false},{"key":"C","text":"Beside the main office","correct":false},{"key":"D","text":"Behind the cafeteria","correct":false}]},{"id":"ets-orig-test-2-q82","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 82 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What will happen at 2 p.m.?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g04.mp3","audioText":"Before we begin the shift, I want to review the safety procedures for the new conveyor system. Always press the red stop button before clearing a jam, and never reach under the belt while it is moving. High-visibility vests must be worn in the loading zone at all times. If you notice a burning smell or unusual noise, shut down the line and notify the shift supervisor immediately. Emergency exits are located at the north and east walls; please keep those areas clear of pallets. We will run a short evacuation drill at 2 p.m. today, so listen for the alarm.","fullTranscript":"Before we begin the shift, I want to review the safety procedures for the new conveyor system. Always press the red stop button before clearing a jam, and never reach under the belt while it is moving. High-visibility vests must be worn in the loading zone at all times. If you notice a burning smell or unusual noise, shut down the line and notify the shift supervisor immediately. Emergency exits are located at the north and east walls; please keep those areas clear of pallets. We will run a short evacuation drill at 2 p.m. today, so listen for the alarm.","vietnamese":"Điều gì sẽ diễn ra lúc 2 giờ chiều? — (A) Một băng tải mới sẽ được lắp đặt (B) Ca làm việc sẽ kết thúc sớm (C) Một buổi diễn tập sơ tán sẽ diễn ra (D) Một đợt kiểm tra an toàn sẽ bắt đầu.","optionTranslations":"Điều gì sẽ diễn ra lúc 2 giờ chiều? — (A) Một băng tải mới sẽ được lắp đặt (B) Ca làm việc sẽ kết thúc sớm (C) Một buổi diễn tập sơ tán sẽ diễn ra (D) Một đợt kiểm tra an toàn sẽ bắt đầu.","explanation":"Đáp án C. Bài nói thông báo: \"We will run a short evacuation drill at 2 p.m. today.\" A sai vì hệ thống băng tải mới đã được đưa vào sử dụng. B sai vì không nói ca làm việc kết thúc sớm. D sai vì 2 giờ chiều là giờ diễn tập, không phải kiểm tra an toàn.","hintWords":["before","begin","shift","want","review"],"keyVocab":[{"word":"evacuation","meaning":"sự sơ tán"},{"word":"drill","meaning":"buổi diễn tập"},{"word":"alarm","meaning":"chuông báo động"},{"word":"shift","meaning":"ca làm việc"}],"practiceOptions":[{"key":"A","text":"A new conveyor will be installed.","correct":false},{"key":"B","text":"The shift will end early.","correct":false},{"key":"C","text":"An evacuation drill will take place.","correct":true},{"key":"D","text":"A safety inspection will begin.","correct":false}]},{"id":"ets-orig-test-2-q83","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 83 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What drove the increase in revenue?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g05.mp3","audioText":"Good morning, everyone. I'll start with the third-quarter results. Revenue reached 4.2 million dollars, up six percent from the same period last year, driven mainly by strong online sales. Operating costs, however, rose by nine percent because of higher shipping rates and the new distribution center. As a result, net profit was slightly below our forecast. To address this, we will renegotiate our courier contracts next month and postpone the planned office expansion until the spring. I want to emphasize that our cash reserves remain healthy, and we still expect to meet our annual sales target.","fullTranscript":"Good morning, everyone. I'll start with the third-quarter results. Revenue reached 4.2 million dollars, up six percent from the same period last year, driven mainly by strong online sales. Operating costs, however, rose by nine percent because of higher shipping rates and the new distribution center. As a result, net profit was slightly below our forecast. To address this, we will renegotiate our courier contracts next month and postpone the planned office expansion until the spring. I want to emphasize that our cash reserves remain healthy, and we still expect to meet our annual sales target.","vietnamese":"Điều gì đã thúc đẩy doanh thu tăng? — (A) Một chiến dịch quảng cáo mới (B) Doanh số trực tuyến mạnh (C) Giá sản phẩm cao hơn (D) Một vụ sáp nhập quốc tế.","optionTranslations":"Điều gì đã thúc đẩy doanh thu tăng? — (A) Một chiến dịch quảng cáo mới (B) Doanh số trực tuyến mạnh (C) Giá sản phẩm cao hơn (D) Một vụ sáp nhập quốc tế.","explanation":"Đáp án B. Báo cáo nêu doanh thu \"up six percent from the same period last year, driven mainly by strong online sales\" — doanh số trực tuyến mạnh là động lực chính. A sai vì không có chiến dịch quảng cáo nào được nhắc. C sai vì không nói đến việc tăng giá. D sai vì không có sáp nhập quốc tế.","hintWords":["good","morning","everyone","start","with"],"keyVocab":[{"word":"revenue","meaning":"doanh thu"},{"word":"quarter","meaning":"quý (ba tháng)"},{"word":"online sales","meaning":"doanh số bán hàng trực tuyến"},{"word":"forecast","meaning":"dự báo"}],"practiceOptions":[{"key":"A","text":"A new advertising campaign","correct":false},{"key":"B","text":"Strong online sales","correct":true},{"key":"C","text":"Higher product prices","correct":false},{"key":"D","text":"An international merger","correct":false}]},{"id":"ets-orig-test-2-q84","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 84 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"Why did operating costs rise?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g05.mp3","audioText":"Good morning, everyone. I'll start with the third-quarter results. Revenue reached 4.2 million dollars, up six percent from the same period last year, driven mainly by strong online sales. Operating costs, however, rose by nine percent because of higher shipping rates and the new distribution center. As a result, net profit was slightly below our forecast. To address this, we will renegotiate our courier contracts next month and postpone the planned office expansion until the spring. I want to emphasize that our cash reserves remain healthy, and we still expect to meet our annual sales target.","fullTranscript":"Good morning, everyone. I'll start with the third-quarter results. Revenue reached 4.2 million dollars, up six percent from the same period last year, driven mainly by strong online sales. Operating costs, however, rose by nine percent because of higher shipping rates and the new distribution center. As a result, net profit was slightly below our forecast. To address this, we will renegotiate our courier contracts next month and postpone the planned office expansion until the spring. I want to emphasize that our cash reserves remain healthy, and we still expect to meet our annual sales target.","vietnamese":"Vì sao chi phí vận hành tăng? — (A) Lương đã được tăng (B) Ngân sách tiếp thị được mở rộng (C) Cước vận chuyển và trung tâm phân phối mới làm tăng chi phí (D) Chính phủ áp dụng thuế mới.","optionTranslations":"Vì sao chi phí vận hành tăng? — (A) Lương đã được tăng (B) Ngân sách tiếp thị được mở rộng (C) Cước vận chuyển và trung tâm phân phối mới làm tăng chi phí (D) Chính phủ áp dụng thuế mới.","explanation":"Đáp án C. Báo cáo nói rõ: \"Operating costs, however, rose by nine percent because of higher shipping rates and the new distribution center.\" A, B và D đều không được nêu là nguyên nhân.","hintWords":["good","morning","everyone","start","with"],"keyVocab":[{"word":"operating costs","meaning":"chi phí vận hành"},{"word":"shipping rate","meaning":"cước vận chuyển"},{"word":"distribution center","meaning":"trung tâm phân phối"},{"word":"net profit","meaning":"lợi nhuận ròng"}],"practiceOptions":[{"key":"A","text":"Salaries were increased.","correct":false},{"key":"B","text":"The marketing budget was expanded.","correct":false},{"key":"C","text":"Shipping rates and a new distribution center raised costs.","correct":true},{"key":"D","text":"The government introduced new taxes.","correct":false}]},{"id":"ets-orig-test-2-q85","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 85 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What will the company do to address the cost increase?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g05.mp3","audioText":"Good morning, everyone. I'll start with the third-quarter results. Revenue reached 4.2 million dollars, up six percent from the same period last year, driven mainly by strong online sales. Operating costs, however, rose by nine percent because of higher shipping rates and the new distribution center. As a result, net profit was slightly below our forecast. To address this, we will renegotiate our courier contracts next month and postpone the planned office expansion until the spring. I want to emphasize that our cash reserves remain healthy, and we still expect to meet our annual sales target.","fullTranscript":"Good morning, everyone. I'll start with the third-quarter results. Revenue reached 4.2 million dollars, up six percent from the same period last year, driven mainly by strong online sales. Operating costs, however, rose by nine percent because of higher shipping rates and the new distribution center. As a result, net profit was slightly below our forecast. To address this, we will renegotiate our courier contracts next month and postpone the planned office expansion until the spring. I want to emphasize that our cash reserves remain healthy, and we still expect to meet our annual sales target.","vietnamese":"Công ty sẽ làm gì để giải quyết việc chi phí tăng? — (A) Đàm phán lại hợp đồng với đơn vị chuyển phát (B) Giảm số lượng nhân viên (C) Đóng cửa trung tâm phân phối (D) Tăng giá sản phẩm.","optionTranslations":"Công ty sẽ làm gì để giải quyết việc chi phí tăng? — (A) Đàm phán lại hợp đồng với đơn vị chuyển phát (B) Giảm số lượng nhân viên (C) Đóng cửa trung tâm phân phối (D) Tăng giá sản phẩm.","explanation":"Đáp án A. Người báo cáo nói: \"we will renegotiate our courier contracts next month\" — đàm phán lại hợp đồng với đơn vị chuyển phát. B, C và D không được nêu; công ty còn hoãn kế hoạch mở rộng văn phòng chứ không đóng trung tâm phân phối.","hintWords":["good","morning","everyone","start","with"],"keyVocab":[{"word":"renegotiate","meaning":"đàm phán lại"},{"word":"courier","meaning":"đơn vị chuyển phát"},{"word":"postpone","meaning":"hoãn lại"},{"word":"expansion","meaning":"việc mở rộng"},{"word":"cash reserves","meaning":"dự trữ tiền mặt"}],"practiceOptions":[{"key":"A","text":"Renegotiate courier contracts","correct":true},{"key":"B","text":"Reduce staff numbers","correct":false},{"key":"C","text":"Close the distribution center","correct":false},{"key":"D","text":"Increase product prices","correct":false}]},{"id":"ets-orig-test-2-q86","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 86 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"Where will the networking session be held?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g06.mp3","audioText":"Welcome to the annual Harbor City Business Luncheon. Our keynote speaker, economist Dr. Elena Marsh, will begin at 12:30 in the Grand Ballroom, followed by a panel discussion on sustainable supply chains. Please note that the networking session has been moved from the terrace to the Maple Room because of the forecast. Lunch will be served at 1:15, and vegetarian options are available at the east buffet. Raffle tickets can be purchased at the registration desk until 2 p.m.; the drawing will take place before the closing remarks. We kindly ask that you silence your phones during the presentations.","fullTranscript":"Welcome to the annual Harbor City Business Luncheon. Our keynote speaker, economist Dr. Elena Marsh, will begin at 12:30 in the Grand Ballroom, followed by a panel discussion on sustainable supply chains. Please note that the networking session has been moved from the terrace to the Maple Room because of the forecast. Lunch will be served at 1:15, and vegetarian options are available at the east buffet. Raffle tickets can be purchased at the registration desk until 2 p.m.; the drawing will take place before the closing remarks. We kindly ask that you silence your phones during the presentations.","vietnamese":"Phiên kết nối giao lưu sẽ được tổ chức ở đâu? — (A) Tại Grand Ballroom (B) Trên sân thượng (C) Tại quầy buffet phía đông (D) Tại phòng Maple.","optionTranslations":"Phiên kết nối giao lưu sẽ được tổ chức ở đâu? — (A) Tại Grand Ballroom (B) Trên sân thượng (C) Tại quầy buffet phía đông (D) Tại phòng Maple.","explanation":"Đáp án D. Thông báo cho biết networking session \"has been moved from the terrace to the Maple Room because of the forecast.\" A là nơi diễn ra bài phát biểu chính. B là địa điểm cũ trước khi đổi. C là nơi phục vụ bữa trưa, không phải nơi tổ chức phiên kết nối.","hintWords":["welcome","annual","harbor","city","business"],"keyVocab":[{"word":"keynote speaker","meaning":"diễn giả chính"},{"word":"panel discussion","meaning":"phiên thảo luận nhóm"},{"word":"networking session","meaning":"phiên kết nối giao lưu"},{"word":"terrace","meaning":"sân thượng"},{"word":"forecast","meaning":"dự báo thời tiết"}],"practiceOptions":[{"key":"A","text":"In the Grand Ballroom","correct":false},{"key":"B","text":"On the terrace","correct":false},{"key":"C","text":"At the east buffet","correct":false},{"key":"D","text":"In the Maple Room","correct":true}]},{"id":"ets-orig-test-2-q87","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 87 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What can attendees purchase at the registration desk?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g06.mp3","audioText":"Welcome to the annual Harbor City Business Luncheon. Our keynote speaker, economist Dr. Elena Marsh, will begin at 12:30 in the Grand Ballroom, followed by a panel discussion on sustainable supply chains. Please note that the networking session has been moved from the terrace to the Maple Room because of the forecast. Lunch will be served at 1:15, and vegetarian options are available at the east buffet. Raffle tickets can be purchased at the registration desk until 2 p.m.; the drawing will take place before the closing remarks. We kindly ask that you silence your phones during the presentations.","fullTranscript":"Welcome to the annual Harbor City Business Luncheon. Our keynote speaker, economist Dr. Elena Marsh, will begin at 12:30 in the Grand Ballroom, followed by a panel discussion on sustainable supply chains. Please note that the networking session has been moved from the terrace to the Maple Room because of the forecast. Lunch will be served at 1:15, and vegetarian options are available at the east buffet. Raffle tickets can be purchased at the registration desk until 2 p.m.; the drawing will take place before the closing remarks. We kindly ask that you silence your phones during the presentations.","vietnamese":"Khách tham dự có thể mua gì tại quầy đăng ký? — (A) Phiếu ăn trưa (B) Vé xổ số (C) Bản ghi âm hội nghị (D) Vé gửi xe.","optionTranslations":"Khách tham dự có thể mua gì tại quầy đăng ký? — (A) Phiếu ăn trưa (B) Vé xổ số (C) Bản ghi âm hội nghị (D) Vé gửi xe.","explanation":"Đáp án B. Thông báo nêu: \"Raffle tickets can be purchased at the registration desk until 2 p.m.\" A sai vì bữa trưa được phục vụ, không nói bán phiếu. C và D không xuất hiện trong bài.","hintWords":["welcome","annual","harbor","city","business"],"keyVocab":[{"word":"raffle","meaning":"xổ số (bán vé gây quỹ)"},{"word":"registration desk","meaning":"quầy đăng ký"},{"word":"drawing","meaning":"buổi rút thăm"},{"word":"closing remarks","meaning":"lời bế mạc"}],"practiceOptions":[{"key":"A","text":"Lunch vouchers","correct":false},{"key":"B","text":"Raffle tickets","correct":true},{"key":"C","text":"Conference recordings","correct":false},{"key":"D","text":"Parking passes","correct":false}]},{"id":"ets-orig-test-2-q88","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 88 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What are attendees asked to do during the presentations?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g06.mp3","audioText":"Welcome to the annual Harbor City Business Luncheon. Our keynote speaker, economist Dr. Elena Marsh, will begin at 12:30 in the Grand Ballroom, followed by a panel discussion on sustainable supply chains. Please note that the networking session has been moved from the terrace to the Maple Room because of the forecast. Lunch will be served at 1:15, and vegetarian options are available at the east buffet. Raffle tickets can be purchased at the registration desk until 2 p.m.; the drawing will take place before the closing remarks. We kindly ask that you silence your phones during the presentations.","fullTranscript":"Welcome to the annual Harbor City Business Luncheon. Our keynote speaker, economist Dr. Elena Marsh, will begin at 12:30 in the Grand Ballroom, followed by a panel discussion on sustainable supply chains. Please note that the networking session has been moved from the terrace to the Maple Room because of the forecast. Lunch will be served at 1:15, and vegetarian options are available at the east buffet. Raffle tickets can be purchased at the registration desk until 2 p.m.; the drawing will take place before the closing remarks. We kindly ask that you silence your phones during the presentations.","vietnamese":"Khách tham dự được yêu cầu làm gì trong các phần trình bày? — (A) Tắt tiếng điện thoại (B) Ghi chép chi tiết (C) Ngồi gần phía trước (D) Đặt câu hỏi trong lúc đang nói.","optionTranslations":"Khách tham dự được yêu cầu làm gì trong các phần trình bày? — (A) Tắt tiếng điện thoại (B) Ghi chép chi tiết (C) Ngồi gần phía trước (D) Đặt câu hỏi trong lúc đang nói.","explanation":"Đáp án A. Câu cuối bài nói: \"We kindly ask that you silence your phones during the presentations.\" B, C và D không được yêu cầu trong bài.","hintWords":["welcome","annual","harbor","city","business"],"keyVocab":[{"word":"silence","meaning":"tắt tiếng, làm im lặng"},{"word":"presentation","meaning":"bài trình bày"},{"word":"attendee","meaning":"người tham dự"},{"word":"vegetarian","meaning":"dành cho người ăn chay"}],"practiceOptions":[{"key":"A","text":"Silence their phones","correct":true},{"key":"B","text":"Take detailed notes","correct":false},{"key":"C","text":"Sit near the front","correct":false},{"key":"D","text":"Ask questions during the talks","correct":false}]},{"id":"ets-orig-test-2-q89","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 89 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What position is being recruited?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g07.mp3","audioText":"Thank you for visiting the Brightline Logistics booth. We are hiring warehouse supervisors for our new facility in Dayton, which opens in January. The position requires at least two years of experience in inventory management and a valid forklift certification. Supervisors work four ten-hour shifts per week, with both morning and evening options available. In addition to a competitive salary, we offer health insurance from the first day and tuition assistance after six months. If you are interested, please submit your resume through our website by November 20. Interviews will be held on-site the following week.","fullTranscript":"Thank you for visiting the Brightline Logistics booth. We are hiring warehouse supervisors for our new facility in Dayton, which opens in January. The position requires at least two years of experience in inventory management and a valid forklift certification. Supervisors work four ten-hour shifts per week, with both morning and evening options available. In addition to a competitive salary, we offer health insurance from the first day and tuition assistance after six months. If you are interested, please submit your resume through our website by November 20. Interviews will be held on-site the following week.","vietnamese":"Vị trí nào đang được tuyển dụng? — (A) Giám sát kho hàng (B) Tài xế giao hàng (C) Nhân viên kiểm kê hàng hóa (D) Thợ sửa xe nâng.","optionTranslations":"Vị trí nào đang được tuyển dụng? — (A) Giám sát kho hàng (B) Tài xế giao hàng (C) Nhân viên kiểm kê hàng hóa (D) Thợ sửa xe nâng.","explanation":"Đáp án A. Bài nói nêu rõ: \"We are hiring warehouse supervisors for our new facility in Dayton.\" B, C và D không phải vị trí đang tuyển; \"inventory management\" chỉ là yêu cầu kinh nghiệm, không phải chức danh.","hintWords":["thank","visiting","brightline","logistics","booth"],"keyVocab":[{"word":"hire","meaning":"tuyển dụng"},{"word":"warehouse","meaning":"kho hàng"},{"word":"supervisor","meaning":"giám sát viên"},{"word":"facility","meaning":"cơ sở, nhà máy"},{"word":"shift","meaning":"ca làm việc"}],"practiceOptions":[{"key":"A","text":"Warehouse supervisors","correct":true},{"key":"B","text":"Delivery drivers","correct":false},{"key":"C","text":"Inventory clerks","correct":false},{"key":"D","text":"Forklift mechanics","correct":false}]},{"id":"ets-orig-test-2-q90","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 90 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What is a requirement for the position?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g07.mp3","audioText":"Thank you for visiting the Brightline Logistics booth. We are hiring warehouse supervisors for our new facility in Dayton, which opens in January. The position requires at least two years of experience in inventory management and a valid forklift certification. Supervisors work four ten-hour shifts per week, with both morning and evening options available. In addition to a competitive salary, we offer health insurance from the first day and tuition assistance after six months. If you are interested, please submit your resume through our website by November 20. Interviews will be held on-site the following week.","fullTranscript":"Thank you for visiting the Brightline Logistics booth. We are hiring warehouse supervisors for our new facility in Dayton, which opens in January. The position requires at least two years of experience in inventory management and a valid forklift certification. Supervisors work four ten-hour shifts per week, with both morning and evening options available. In addition to a competitive salary, we offer health insurance from the first day and tuition assistance after six months. If you are interested, please submit your resume through our website by November 20. Interviews will be held on-site the following week.","vietnamese":"Yêu cầu nào dành cho vị trí này? — (A) Bằng đại học (B) Năm năm kinh nghiệm quản lý (C) Chứng chỉ vận hành xe nâng còn hiệu lực (D) Giấy phép lái xe thương mại.","optionTranslations":"Yêu cầu nào dành cho vị trí này? — (A) Bằng đại học (B) Năm năm kinh nghiệm quản lý (C) Chứng chỉ vận hành xe nâng còn hiệu lực (D) Giấy phép lái xe thương mại.","explanation":"Đáp án C. Bài nói cho biết: \"The position requires at least two years of experience in inventory management and a valid forklift certification.\" A sai vì không yêu cầu bằng đại học. B sai vì chỉ cần ít nhất hai năm kinh nghiệm quản lý hàng tồn kho, không phải năm năm quản lý. D sai vì không nhắc giấy phép lái xe thương mại.","hintWords":["thank","visiting","brightline","logistics","booth"],"keyVocab":[{"word":"inventory management","meaning":"quản lý hàng tồn kho"},{"word":"valid","meaning":"còn hiệu lực"},{"word":"forklift certification","meaning":"chứng chỉ vận hành xe nâng"},{"word":"requirement","meaning":"yêu cầu"}],"practiceOptions":[{"key":"A","text":"A college degree","correct":false},{"key":"B","text":"Five years of management experience","correct":false},{"key":"C","text":"A valid forklift certification","correct":true},{"key":"D","text":"A commercial driver's license","correct":false}]},{"id":"ets-orig-test-2-q91","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 91 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"Which benefit is available after six months?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g07.mp3","audioText":"Thank you for visiting the Brightline Logistics booth. We are hiring warehouse supervisors for our new facility in Dayton, which opens in January. The position requires at least two years of experience in inventory management and a valid forklift certification. Supervisors work four ten-hour shifts per week, with both morning and evening options available. In addition to a competitive salary, we offer health insurance from the first day and tuition assistance after six months. If you are interested, please submit your resume through our website by November 20. Interviews will be held on-site the following week.","fullTranscript":"Thank you for visiting the Brightline Logistics booth. We are hiring warehouse supervisors for our new facility in Dayton, which opens in January. The position requires at least two years of experience in inventory management and a valid forklift certification. Supervisors work four ten-hour shifts per week, with both morning and evening options available. In addition to a competitive salary, we offer health insurance from the first day and tuition assistance after six months. If you are interested, please submit your resume through our website by November 20. Interviews will be held on-site the following week.","vietnamese":"Phúc lợi nào có sau sáu tháng? — (A) Bảo hiểm y tế (B) Ngày nghỉ thêm (C) Xe công ty (D) Hỗ trợ học phí.","optionTranslations":"Phúc lợi nào có sau sáu tháng? — (A) Bảo hiểm y tế (B) Ngày nghỉ thêm (C) Xe công ty (D) Hỗ trợ học phí.","explanation":"Đáp án D. Bài nói nêu: \"we offer health insurance from the first day and tuition assistance after six months.\" A sai vì bảo hiểm y tế có ngay từ ngày đầu. B và C không được nhắc đến.","hintWords":["thank","visiting","brightline","logistics","booth"],"keyVocab":[{"word":"tuition assistance","meaning":"hỗ trợ học phí"},{"word":"competitive salary","meaning":"mức lương cạnh tranh"},{"word":"benefit","meaning":"phúc lợi"},{"word":"on-site","meaning":"tại chỗ, tại địa điểm"}],"practiceOptions":[{"key":"A","text":"Health insurance","correct":false},{"key":"B","text":"Extra vacation days","correct":false},{"key":"C","text":"A company vehicle","correct":false},{"key":"D","text":"Tuition assistance","correct":true}]},{"id":"ets-orig-test-2-q92","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 92 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What is the main purpose of the announcement?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g08.mp3","audioText":"This is a weather advisory for residents of coastal Marlow County. A strong storm system is expected to bring heavy rain and wind gusts of up to sixty miles per hour beginning this evening. The National Weather Service has issued a flood watch for low-lying areas through Thursday morning. Residents should secure outdoor furniture, charge phones, and avoid driving on flooded roads. Sandbags are available free of charge at the community center on Oak Street until 8 p.m. tonight. School buses will run on a delayed schedule tomorrow, and any further updates will be posted on the county website.","fullTranscript":"This is a weather advisory for residents of coastal Marlow County. A strong storm system is expected to bring heavy rain and wind gusts of up to sixty miles per hour beginning this evening. The National Weather Service has issued a flood watch for low-lying areas through Thursday morning. Residents should secure outdoor furniture, charge phones, and avoid driving on flooded roads. Sandbags are available free of charge at the community center on Oak Street until 8 p.m. tonight. School buses will run on a delayed schedule tomorrow, and any further updates will be posted on the county website.","vietnamese":"Mục đích chính của thông báo là gì? — (A) Thông báo đóng cửa trường học (B) Mô tả dự án xây dựng đường (C) Cảnh báo cư dân về thời tiết khắc nghiệt (D) Báo cáo sự cố mất điện.","optionTranslations":"Mục đích chính của thông báo là gì? — (A) Thông báo đóng cửa trường học (B) Mô tả dự án xây dựng đường (C) Cảnh báo cư dân về thời tiết khắc nghiệt (D) Báo cáo sự cố mất điện.","explanation":"Đáp án C. Bài nói mở đầu: \"This is a weather advisory\" và toàn bài nói về bão, mưa lớn, gió giật và nguy cơ lũ. A sai vì trường học không đóng cửa, chỉ lùi giờ xe buýt. B và D không được nhắc đến.","hintWords":["this","weather","advisory","residents","coastal"],"keyVocab":[{"word":"advisory","meaning":"bản cảnh báo, khuyến cáo"},{"word":"storm system","meaning":"hệ thống bão"},{"word":"gust","meaning":"cơn gió giật"},{"word":"flood watch","meaning":"cảnh báo nguy cơ lũ"},{"word":"low-lying","meaning":"thấp trũng"}],"practiceOptions":[{"key":"A","text":"To announce a school closure","correct":false},{"key":"B","text":"To describe a road construction project","correct":false},{"key":"C","text":"To warn residents about severe weather","correct":true},{"key":"D","text":"To report a power outage","correct":false}]},{"id":"ets-orig-test-2-q93","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 93 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What are residents advised to avoid?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g08.mp3","audioText":"This is a weather advisory for residents of coastal Marlow County. A strong storm system is expected to bring heavy rain and wind gusts of up to sixty miles per hour beginning this evening. The National Weather Service has issued a flood watch for low-lying areas through Thursday morning. Residents should secure outdoor furniture, charge phones, and avoid driving on flooded roads. Sandbags are available free of charge at the community center on Oak Street until 8 p.m. tonight. School buses will run on a delayed schedule tomorrow, and any further updates will be posted on the county website.","fullTranscript":"This is a weather advisory for residents of coastal Marlow County. A strong storm system is expected to bring heavy rain and wind gusts of up to sixty miles per hour beginning this evening. The National Weather Service has issued a flood watch for low-lying areas through Thursday morning. Residents should secure outdoor furniture, charge phones, and avoid driving on flooded roads. Sandbags are available free of charge at the community center on Oak Street until 8 p.m. tonight. School buses will run on a delayed schedule tomorrow, and any further updates will be posted on the county website.","vietnamese":"Cư dân được khuyên tránh làm gì? — (A) Sạc điện thoại (B) Đến trung tâm cộng đồng (C) Để cửa sổ mở (D) Lái xe trên đường ngập.","optionTranslations":"Cư dân được khuyên tránh làm gì? — (A) Sạc điện thoại (B) Đến trung tâm cộng đồng (C) Để cửa sổ mở (D) Lái xe trên đường ngập.","explanation":"Đáp án D. Bài nói khuyên: \"avoid driving on flooded roads.\" A và B là những việc nên làm (sạc điện thoại, nhận bao cát tại trung tâm cộng đồng). C không được nhắc đến trong bài.","hintWords":["this","weather","advisory","residents","coastal"],"keyVocab":[{"word":"secure","meaning":"cố định, gia cố"},{"word":"charge","meaning":"sạc (điện)"},{"word":"flooded road","meaning":"đường bị ngập"},{"word":"resident","meaning":"cư dân"}],"practiceOptions":[{"key":"A","text":"Charging their phones","correct":false},{"key":"B","text":"Visiting the community center","correct":false},{"key":"C","text":"Leaving windows open","correct":false},{"key":"D","text":"Driving on flooded roads","correct":true}]},{"id":"ets-orig-test-2-q94","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 94 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"Where can residents get sandbags?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g08.mp3","audioText":"This is a weather advisory for residents of coastal Marlow County. A strong storm system is expected to bring heavy rain and wind gusts of up to sixty miles per hour beginning this evening. The National Weather Service has issued a flood watch for low-lying areas through Thursday morning. Residents should secure outdoor furniture, charge phones, and avoid driving on flooded roads. Sandbags are available free of charge at the community center on Oak Street until 8 p.m. tonight. School buses will run on a delayed schedule tomorrow, and any further updates will be posted on the county website.","fullTranscript":"This is a weather advisory for residents of coastal Marlow County. A strong storm system is expected to bring heavy rain and wind gusts of up to sixty miles per hour beginning this evening. The National Weather Service has issued a flood watch for low-lying areas through Thursday morning. Residents should secure outdoor furniture, charge phones, and avoid driving on flooded roads. Sandbags are available free of charge at the community center on Oak Street until 8 p.m. tonight. School buses will run on a delayed schedule tomorrow, and any further updates will be posted on the county website.","vietnamese":"Cư dân có thể lấy bao cát ở đâu? — (A) Tại văn phòng quận (B) Tại trung tâm cộng đồng trên phố Oak (C) Tại trạm cứu hỏa địa phương (D) Tại cửa hàng kim khí gần đó.","optionTranslations":"Cư dân có thể lấy bao cát ở đâu? — (A) Tại văn phòng quận (B) Tại trung tâm cộng đồng trên phố Oak (C) Tại trạm cứu hỏa địa phương (D) Tại cửa hàng kim khí gần đó.","explanation":"Đáp án B. Bài nói cho biết: \"Sandbags are available free of charge at the community center on Oak Street until 8 p.m. tonight.\" A, C và D không xuất hiện trong bài.","hintWords":["this","weather","advisory","residents","coastal"],"keyVocab":[{"word":"sandbag","meaning":"bao cát"},{"word":"free of charge","meaning":"miễn phí"},{"word":"community center","meaning":"trung tâm cộng đồng"},{"word":"delayed schedule","meaning":"lịch trình bị lùi giờ"}],"practiceOptions":[{"key":"A","text":"At the county office","correct":false},{"key":"B","text":"At the community center on Oak Street","correct":true},{"key":"C","text":"At the local fire station","correct":false},{"key":"D","text":"At a nearby hardware store","correct":false}]},{"id":"ets-orig-test-2-q95","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 95 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What will the first one hundred visitors receive?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g09.mp3","audioText":"Come celebrate the grand opening of Meridian Home Goods this Saturday at our new location on Cedar Avenue. The first one hundred visitors will receive a ten-dollar gift card, and everyone can enjoy free pastries and coffee from nine to eleven. Our founder will cut the ribbon at ten o'clock, followed by a cooking demonstration with local chef Antonio Reyes. Children can take part in a craft workshop in the back garden while parents browse. Parking is limited, so we encourage guests to use the free shuttle from the downtown library. The store will remain open until 8 p.m.","fullTranscript":"Come celebrate the grand opening of Meridian Home Goods this Saturday at our new location on Cedar Avenue. The first one hundred visitors will receive a ten-dollar gift card, and everyone can enjoy free pastries and coffee from nine to eleven. Our founder will cut the ribbon at ten o'clock, followed by a cooking demonstration with local chef Antonio Reyes. Children can take part in a craft workshop in the back garden while parents browse. Parking is limited, so we encourage guests to use the free shuttle from the downtown library. The store will remain open until 8 p.m.","vietnamese":"100 khách đầu tiên sẽ nhận được gì? — (A) Một cuốn sách dạy nấu ăn miễn phí (B) Một thẻ quà tặng 10 đô-la (C) Một túi cà phê (D) Một bộ đồ thủ công.","optionTranslations":"100 khách đầu tiên sẽ nhận được gì? — (A) Một cuốn sách dạy nấu ăn miễn phí (B) Một thẻ quà tặng 10 đô-la (C) Một túi cà phê (D) Một bộ đồ thủ công.","explanation":"Đáp án B. Bài nói nêu: \"The first one hundred visitors will receive a ten-dollar gift card.\" A, C và D không đúng; cà phê và bánh ngọt miễn phí cho mọi người từ 9 đến 11 giờ, không phải quà dành riêng cho 100 khách đầu tiên.","hintWords":["come","celebrate","grand","opening","meridian"],"keyVocab":[{"word":"grand opening","meaning":"lễ khai trương"},{"word":"gift card","meaning":"thẻ quà tặng"},{"word":"visitor","meaning":"khách tham quan"},{"word":"pastry","meaning":"bánh ngọt"}],"practiceOptions":[{"key":"A","text":"A free cookbook","correct":false},{"key":"B","text":"A ten-dollar gift card","correct":true},{"key":"C","text":"A bag of coffee","correct":false},{"key":"D","text":"A craft kit","correct":false}]},{"id":"ets-orig-test-2-q96","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 96 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"Who will cut the ribbon?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g09.mp3","audioText":"Come celebrate the grand opening of Meridian Home Goods this Saturday at our new location on Cedar Avenue. The first one hundred visitors will receive a ten-dollar gift card, and everyone can enjoy free pastries and coffee from nine to eleven. Our founder will cut the ribbon at ten o'clock, followed by a cooking demonstration with local chef Antonio Reyes. Children can take part in a craft workshop in the back garden while parents browse. Parking is limited, so we encourage guests to use the free shuttle from the downtown library. The store will remain open until 8 p.m.","fullTranscript":"Come celebrate the grand opening of Meridian Home Goods this Saturday at our new location on Cedar Avenue. The first one hundred visitors will receive a ten-dollar gift card, and everyone can enjoy free pastries and coffee from nine to eleven. Our founder will cut the ribbon at ten o'clock, followed by a cooking demonstration with local chef Antonio Reyes. Children can take part in a craft workshop in the back garden while parents browse. Parking is limited, so we encourage guests to use the free shuttle from the downtown library. The store will remain open until 8 p.m.","vietnamese":"Ai sẽ cắt băng khánh thành? — (A) Người sáng lập cửa hàng (B) Đầu bếp Antonio Reyes (C) Quản lý cửa hàng (D) Một quan chức địa phương.","optionTranslations":"Ai sẽ cắt băng khánh thành? — (A) Người sáng lập cửa hàng (B) Đầu bếp Antonio Reyes (C) Quản lý cửa hàng (D) Một quan chức địa phương.","explanation":"Đáp án A. Bài nói cho biết: \"Our founder will cut the ribbon at ten o'clock.\" B sai vì Antonio Reyes chỉ thực hiện phần trình diễn nấu ăn sau đó. C và D không được nhắc đến.","hintWords":["come","celebrate","grand","opening","meridian"],"keyVocab":[{"word":"founder","meaning":"người sáng lập"},{"word":"cut the ribbon","meaning":"cắt băng khánh thành"},{"word":"cooking demonstration","meaning":"buổi trình diễn nấu ăn"},{"word":"local","meaning":"địa phương"}],"practiceOptions":[{"key":"A","text":"The founder","correct":true},{"key":"B","text":"Chef Antonio Reyes","correct":false},{"key":"C","text":"The store manager","correct":false},{"key":"D","text":"A local official","correct":false}]},{"id":"ets-orig-test-2-q97","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 97 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"How are guests encouraged to travel to the store?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g09.mp3","audioText":"Come celebrate the grand opening of Meridian Home Goods this Saturday at our new location on Cedar Avenue. The first one hundred visitors will receive a ten-dollar gift card, and everyone can enjoy free pastries and coffee from nine to eleven. Our founder will cut the ribbon at ten o'clock, followed by a cooking demonstration with local chef Antonio Reyes. Children can take part in a craft workshop in the back garden while parents browse. Parking is limited, so we encourage guests to use the free shuttle from the downtown library. The store will remain open until 8 p.m.","fullTranscript":"Come celebrate the grand opening of Meridian Home Goods this Saturday at our new location on Cedar Avenue. The first one hundred visitors will receive a ten-dollar gift card, and everyone can enjoy free pastries and coffee from nine to eleven. Our founder will cut the ribbon at ten o'clock, followed by a cooking demonstration with local chef Antonio Reyes. Children can take part in a craft workshop in the back garden while parents browse. Parking is limited, so we encourage guests to use the free shuttle from the downtown library. The store will remain open until 8 p.m.","vietnamese":"Khách được khuyến khích đến cửa hàng bằng cách nào? — (A) Đỗ xe trong vườn sau (B) Đi xe đạp (C) Đi xe buýt thành phố (D) Dùng xe đưa đón miễn phí từ thư viện trung tâm.","optionTranslations":"Khách được khuyến khích đến cửa hàng bằng cách nào? — (A) Đỗ xe trong vườn sau (B) Đi xe đạp (C) Đi xe buýt thành phố (D) Dùng xe đưa đón miễn phí từ thư viện trung tâm.","explanation":"Đáp án D. Bài nói cho biết: \"Parking is limited, so we encourage guests to use the free shuttle from the downtown library.\" A sai vì vườn sau dành cho buổi làm đồ thủ công của trẻ em, không phải bãi đỗ xe. B và C không được nhắc đến.","hintWords":["come","celebrate","grand","opening","meridian"],"keyVocab":[{"word":"shuttle","meaning":"xe đưa đón"},{"word":"parking","meaning":"bãi đỗ xe, việc đỗ xe"},{"word":"limited","meaning":"hạn chế"},{"word":"browse","meaning":"xem hàng, dạo xem"}],"practiceOptions":[{"key":"A","text":"Park in the back garden","correct":false},{"key":"B","text":"Ride a bicycle","correct":false},{"key":"C","text":"Take a city bus","correct":false},{"key":"D","text":"Use the free shuttle from the downtown library","correct":true}]},{"id":"ets-orig-test-2-q98","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 98 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What is the workshop about?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g10.mp3","audioText":"Welcome to the customer service workshop. Today we will focus on handling complaints over the phone. In the first session, we will review our new refund policy and practice a three-step response: listen, acknowledge, and offer a solution. After lunch, you will work in pairs to role-play difficult calls, and each pair will receive feedback from a coach. Please bring the printed handbook you received this morning; extra copies are at the back of the room. The workshop ends at 4:30, and a short survey will be emailed to you tomorrow. Your responses will help us plan the next session.","fullTranscript":"Welcome to the customer service workshop. Today we will focus on handling complaints over the phone. In the first session, we will review our new refund policy and practice a three-step response: listen, acknowledge, and offer a solution. After lunch, you will work in pairs to role-play difficult calls, and each pair will receive feedback from a coach. Please bring the printed handbook you received this morning; extra copies are at the back of the room. The workshop ends at 4:30, and a short survey will be emailed to you tomorrow. Your responses will help us plan the next session.","vietnamese":"Buổi đào tạo nói về nội dung gì? — (A) Xử lý khiếu nại qua điện thoại (B) Cải thiện kỹ năng bán hàng (C) Viết email chuyên nghiệp (D) Quản lý nhóm.","optionTranslations":"Buổi đào tạo nói về nội dung gì? — (A) Xử lý khiếu nại qua điện thoại (B) Cải thiện kỹ năng bán hàng (C) Viết email chuyên nghiệp (D) Quản lý nhóm.","explanation":"Đáp án A. Bài nói nêu rõ: \"Today we will focus on handling complaints over the phone.\" B, C và D không được đề cập; nội dung gồm chính sách hoàn tiền và quy trình ba bước, không phải bán hàng hay viết email.","hintWords":["welcome","customer","service","workshop","today"],"keyVocab":[{"word":"complaint","meaning":"lời khiếu nại"},{"word":"refund policy","meaning":"chính sách hoàn tiền"},{"word":"acknowledge","meaning":"ghi nhận, thừa nhận"},{"word":"workshop","meaning":"buổi đào tạo, hội thảo thực hành"},{"word":"session","meaning":"phiên, buổi"}],"practiceOptions":[{"key":"A","text":"Handling complaints over the phone","correct":true},{"key":"B","text":"Improving sales techniques","correct":false},{"key":"C","text":"Writing professional emails","correct":false},{"key":"D","text":"Managing a team","correct":false}]},{"id":"ets-orig-test-2-q99","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 99 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"What will participants do after lunch?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g10.mp3","audioText":"Welcome to the customer service workshop. Today we will focus on handling complaints over the phone. In the first session, we will review our new refund policy and practice a three-step response: listen, acknowledge, and offer a solution. After lunch, you will work in pairs to role-play difficult calls, and each pair will receive feedback from a coach. Please bring the printed handbook you received this morning; extra copies are at the back of the room. The workshop ends at 4:30, and a short survey will be emailed to you tomorrow. Your responses will help us plan the next session.","fullTranscript":"Welcome to the customer service workshop. Today we will focus on handling complaints over the phone. In the first session, we will review our new refund policy and practice a three-step response: listen, acknowledge, and offer a solution. After lunch, you will work in pairs to role-play difficult calls, and each pair will receive feedback from a coach. Please bring the printed handbook you received this morning; extra copies are at the back of the room. The workshop ends at 4:30, and a short survey will be emailed to you tomorrow. Your responses will help us plan the next session.","vietnamese":"Sau bữa trưa, người tham gia sẽ làm gì? — (A) Làm bài kiểm tra viết (B) Xem video đào tạo (C) Gặp khách hàng (D) Đóng vai các cuộc gọi khó theo cặp.","optionTranslations":"Sau bữa trưa, người tham gia sẽ làm gì? — (A) Làm bài kiểm tra viết (B) Xem video đào tạo (C) Gặp khách hàng (D) Đóng vai các cuộc gọi khó theo cặp.","explanation":"Đáp án D. Bài nói hướng dẫn: \"After lunch, you will work in pairs to role-play difficult calls.\" A, B và C không được nhắc đến.","hintWords":["welcome","customer","service","workshop","today"],"keyVocab":[{"word":"role-play","meaning":"đóng vai, thực hành tình huống"},{"word":"in pairs","meaning":"theo cặp"},{"word":"feedback","meaning":"phản hồi, nhận xét"},{"word":"coach","meaning":"huấn luyện viên"}],"practiceOptions":[{"key":"A","text":"Take a written test","correct":false},{"key":"B","text":"Watch a training video","correct":false},{"key":"C","text":"Meet with customers","correct":false},{"key":"D","text":"Role-play difficult calls in pairs","correct":true}]},{"id":"ets-orig-test-2-q100","etsYear":"2026","etsTestId":"ets-orig-test-2","part":"Part 4","partNumber":4,"level":"ETS Format","title":"Test 02 • Câu 100 (Part 4: Bài nói ngắn (Short Talks))","questionPrompt":"When will the survey be sent?","imageType":"office_laptop","imageCaption":"","imageUrl":"","audioUrl":"listening/audio/lv1-test-02/p4-g10.mp3","audioText":"Welcome to the customer service workshop. Today we will focus on handling complaints over the phone. In the first session, we will review our new refund policy and practice a three-step response: listen, acknowledge, and offer a solution. After lunch, you will work in pairs to role-play difficult calls, and each pair will receive feedback from a coach. Please bring the printed handbook you received this morning; extra copies are at the back of the room. The workshop ends at 4:30, and a short survey will be emailed to you tomorrow. Your responses will help us plan the next session.","fullTranscript":"Welcome to the customer service workshop. Today we will focus on handling complaints over the phone. In the first session, we will review our new refund policy and practice a three-step response: listen, acknowledge, and offer a solution. After lunch, you will work in pairs to role-play difficult calls, and each pair will receive feedback from a coach. Please bring the printed handbook you received this morning; extra copies are at the back of the room. The workshop ends at 4:30, and a short survey will be emailed to you tomorrow. Your responses will help us plan the next session.","vietnamese":"Bản khảo sát sẽ được gửi khi nào? — (A) Lúc 4:30 hôm nay (B) Tuần sau (C) Ngày mai (D) Sau buổi học tiếp theo.","optionTranslations":"Bản khảo sát sẽ được gửi khi nào? — (A) Lúc 4:30 hôm nay (B) Tuần sau (C) Ngày mai (D) Sau buổi học tiếp theo.","explanation":"Đáp án C. Bài nói cho biết: \"a short survey will be emailed to you tomorrow.\" A sai vì 4:30 là giờ kết thúc buổi đào tạo. B và D sai vì khảo sát được gửi ngay ngày mai để giúp lên kế hoạch cho buổi sau, không phải sau buổi sau mới gửi.","hintWords":["welcome","customer","service","workshop","today"],"keyVocab":[{"word":"survey","meaning":"bản khảo sát"},{"word":"respond","meaning":"trả lời, phản hồi"},{"word":"participant","meaning":"người tham gia"},{"word":"handbook","meaning":"sổ tay hướng dẫn"}],"practiceOptions":[{"key":"A","text":"At 4:30 today","correct":false},{"key":"B","text":"Next week","correct":false},{"key":"C","text":"Tomorrow","correct":true},{"key":"D","text":"After the next session","correct":false}]}]);
